// Content for Flip the Script (node g17, ages 9-12, Chapter 3): NEW v2 build to GDD 17 (mechanic-embodying),
// the gender-stereotype node (Thread E · Gender & Respect) and the **strike-and-rewrite (UN/RE) flagship**.
// "Spot it, flip it, call it out." 84 researched, India-grounded scenarios across the spot → flip → call-it-out
// arc, each encoded as one of the shared v2 play actions (strike-rewrite / spot / reflect / branch / role-play
// / sort / match): no binary "tap the right card", led by the **strike-and-rewrite card** (strike-rewrite ×29
// the signature flip: erase a stereotype, write the fair truth) and **spot-the-stereotype** media frames
// (spot ×14). The flip + spot renderers here are the **reference implementation the whole gender thread**
// (MythBuster Gender g25, Equalize g26, Smart Screen g12, Norm Storm g18) reuses. Teaches: spot stereotypes
// hidden in ads/films/songs/toys, that any job/role/trait/colour/feeling belongs to everyone, then flip a
// stereotyped message to a fair one and call it out kindly. Ethics: QUESTION DON'T PREACH; RESPECTFUL OF
// CULTURE (flips family/tradition respectfully ("is this fair, na?") question without attacking elders);
// NO ONE'S THE VILLAIN (stereotypes are learned scripts to flip, not proof a person is bad); ALL GENDERS
// FREED (boy-scripts AND girl-scripts equally: "boys can cry" beside "girls can lead"); SAFE TO CALL OUT
// (kind, doable lines; one voice can spark others). Builds on g10 (Fair Play World); prereq g16. Rendered by
// the shared engine (components/games/v2-engine.tsx). gameId "flip-script" (the GDD/library "flip-the-script"
// is design-doc only: config must use the engine-host registry id). DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // Spot the stereotype (in media)
  {"id":"fs-001","type":"spot","hook":"An ad for a cleaning product. Spot the stereotype.","scene":[{"id":"a","text":"A smiling mum scrubs the floor while the family relaxes","trick":true},{"id":"b","text":"The voice says \"every mother wants a clean home\"","trick":true},{"id":"c","text":"\"Gets out tough stains\"","trick":false},{"id":"d","text":"The bottle is bright green","trick":false},{"id":"e","text":"It removes a chai spill in seconds","trick":false}],"why":"Ads often show only women doing the cleaning, as if it's only their job.","relearn":"Cleaning ads often stereotype housework as only women's work; spot it.","persona":"Diya","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-002","type":"spot","hook":"A toy advert. Spot the stereotype.","scene":[{"id":"a","text":"Boys play with cars and building sets","trick":true},{"id":"b","text":"Girls play with dolls and kitchen sets","trick":true},{"id":"c","text":"\"Fun for everyone!\"","trick":false},{"id":"d","text":"The toys are on sale this week","trick":false},{"id":"e","text":"There's upbeat background music","trick":false}],"why":"Toy ads often split toys by gender, even though any kid can enjoy any toy.","relearn":"Toy ads stereotype toys as 'for boys' or 'for girls'; spot it.","persona":"any","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-003","type":"spot","hook":"A film scene. Spot the stereotype.","scene":[{"id":"a","text":"The girl waits to be rescued","trick":true},{"id":"b","text":"The boy does the brave rescue","trick":true},{"id":"c","text":"There's a dragon","trick":false},{"id":"d","text":"The castle has tall towers","trick":false},{"id":"e","text":"The music swells at the end","trick":false}],"why":"Films often make girls helpless and boys the heroes; real life isn't like that.","relearn":"Films often stereotype girls as helpless and boys as heroes; spot it.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-004","type":"spot","hook":"A school textbook picture. Spot the stereotype.","scene":[{"id":"a","text":"The doctor is drawn as a man","trick":true},{"id":"b","text":"The nurse is drawn as a woman","trick":true},{"id":"c","text":"There's a hospital bed","trick":false},{"id":"d","text":"A patient is being checked","trick":false},{"id":"e","text":"The room has a first-aid sign","trick":false}],"why":"Books often show men as doctors and women as nurses, but both can be either.","relearn":"Books often stereotype men as doctors, women as nurses; spot it.","persona":"any","source":"media literacy / jobs","cat":"spot-it"},
  {"id":"fs-005","type":"spot","hook":"A fairness-cream ad. Spot the stereotype.","scene":[{"id":"a","text":"A girl only gets the job after her skin turns fairer","trick":true},{"id":"b","text":"\"Lighter skin, brighter future\"","trick":true},{"id":"c","text":"There's an office with desks","trick":false},{"id":"d","text":"She's holding a job-offer letter","trick":false},{"id":"e","text":"The jingle is cheerful","trick":false}],"why":"These ads push the false idea that fairer skin means more worth or success.","relearn":"Fairness-cream ads stereotype fair skin as better; that's false.","persona":"Diya","source":"media literacy / colourism","cat":"spot-it"},
  {"id":"fs-006","type":"spot","hook":"A cricket broadcast. Spot the stereotype.","scene":[{"id":"a","text":"\"He plays like a real man\"","trick":true},{"id":"b","text":"The commentator ignores the women's match entirely","trick":true},{"id":"c","text":"It's a packed stadium","trick":false},{"id":"d","text":"The scoreboard shows the runs","trick":false},{"id":"e","text":"A six is replayed in slow motion","trick":false}],"why":"Sport coverage often treats men's games as the 'real' ones and sidelines women's.","relearn":"Sport media often stereotypes men's sport as the only 'real' sport; spot it.","persona":"Aarav","source":"media literacy / sport","cat":"spot-it"},
  {"id":"fs-007","type":"spot","hook":"A song lyric. Spot the stereotype.","scene":[{"id":"a","text":"\"Boys will be boys\" excusing bad behaviour","trick":true},{"id":"b","text":"\"Good girls stay quiet\"","trick":true},{"id":"c","text":"A catchy beat","trick":false},{"id":"d","text":"The chorus repeats twice","trick":false},{"id":"e","text":"A flute plays in the bridge","trick":false}],"why":"Some lyrics excuse boys and silence girls; those are stereotypes, not rules.","relearn":"'Boys will be boys' and 'good girls stay quiet' are stereotypes, not truths.","persona":"any","source":"media literacy / music","cat":"spot-it"},
  {"id":"fs-008","type":"spot","hook":"A greeting card. Spot the stereotype.","scene":[{"id":"a","text":"\"For a strong, brave boy\"","trick":true},{"id":"b","text":"\"For a sweet, pretty girl\"","trick":true},{"id":"c","text":"Happy birthday balloons","trick":false},{"id":"d","text":"A glittery border","trick":false},{"id":"e","text":"Space to write a name inside","trick":false}],"why":"Even cards box kids in: boys = strong, girls = pretty. Kids are all of these.","relearn":"Cards often stereotype boys as 'strong' and girls as 'pretty'; spot it.","persona":"any","source":"media literacy / products","cat":"spot-it"},
  {"id":"fs-009","type":"spot","hook":"A cooking-show line-up. Spot the stereotype.","scene":[{"id":"a","text":"\"Cooking at home is a woman's duty\"","trick":true},{"id":"b","text":"\"A real chef's kitchen is no place for a girl\"","trick":true},{"id":"c","text":"The famous TV chef is a man","trick":false},{"id":"d","text":"There's a busy kitchen","trick":false},{"id":"e","text":"A dosa is flipped on the tawa","trick":false}],"why":"Funny twist: top chefs are often men, yet home cooking is called 'women's work'.","relearn":"Cooking isn't gendered; the 'home cooking is women's duty' line is a stereotype.","persona":"Rohit","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-010","type":"spot","hook":"A car advert. Spot the stereotype.","scene":[{"id":"a","text":"A man drives the powerful car","trick":true},{"id":"b","text":"A woman just sits admiring him","trick":true},{"id":"c","text":"\"Goes from zero to top speed fast\"","trick":false},{"id":"d","text":"The car is bright red","trick":false},{"id":"e","text":"It speeds along a coastal road","trick":false}],"why":"Car ads often make men the drivers and women the decoration.","relearn":"Car ads often stereotype men as drivers and women as decoration; spot it.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-011","type":"spot","hook":"A 'family' emoji set. Spot the stereotype.","scene":[{"id":"a","text":"Only mum is shown holding the baby","trick":true},{"id":"b","text":"Only dad is shown carrying the briefcase","trick":true},{"id":"c","text":"There's a house emoji","trick":false},{"id":"d","text":"A pet dog emoji sits nearby","trick":false},{"id":"e","text":"The set comes in two skin tones","trick":false}],"why":"Even emojis can assume mums care and dads earn; both parents can do both.","relearn":"Defaults often stereotype mums as carers and dads as earners; spot it.","persona":"any","source":"media literacy / defaults","cat":"spot-it"},
  {"id":"fs-012","cat":"spot-it","type":"reflect","hook":"Lensy: once you start spotting stereotypes in media, you see them everywhere. Noticing more?","prompt":"What do you think?","options":["Yes, loads","More than before","Can't unsee them"],"affirm":"That radar is media literacy, and it's a superpower.","relearn":"Spotting stereotypes in media is a skill that grows with practice.","persona":"any","source":"media literacy"},
  {"id":"fs-013","cat":"spot-it","type":"reflect","hook":"Lensy: a stereotype is a too-simple story about a whole group. Make sense?","prompt":"What do you think?","options":["Yes","Too-simple story","Got it"],"affirm":"Real people are far richer than any stereotype.","relearn":"A stereotype is an over-simple story about a whole group.","persona":"any","source":"concept"},
  {"id":"fs-014","cat":"spot-it","type":"strike-rewrite","hook":"\"If I see it on TV, it must be how things really are.\"","myth":{"un":"What media shows is how the world really is.","re":"Media is made by people and often repeats stereotypes.","why":"Screens show choices made by writers, not simple truth."},"relearn":"Media isn't reality; it often repeats stereotypes.","persona":"Aarav","source":"media literacy"},
  {"id":"fs-015","cat":"spot-it","type":"strike-rewrite","hook":"\"Stereotypes are harmless, just a bit of fun.\"","myth":{"un":"Gender stereotypes are harmless fun.","re":"They quietly limit what kids think they're allowed to be.","why":"Repeated messages shape what feels 'normal'."},"relearn":"Stereotypes aren't harmless; they limit what people feel free to be.","persona":"any","source":"impact of stereotypes"},
  {"id":"fs-016","type":"sort","hook":"Sort: a stereotype, or just a fact?","items":[{"id":"a","text":"\"Girls can't do maths\""},{"id":"b","text":"\"This triangle has three sides\""},{"id":"c","text":"\"Boys don't feel sad\""},{"id":"d","text":"\"Water is wet\""},{"id":"e","text":"\"Cooking is only for women\""},{"id":"f","text":"\"The sun rises in the east\""}],"bins":[{"id":"stereo","label":"Stereotype","valence":"neg"},{"id":"fact","label":"Fact","valence":"pos"}],"key":{"a":"stereo","b":"fact","c":"stereo","d":"fact","e":"stereo","f":"fact"},"relearn":"Stereotypes about what a gender 'can' do aren't facts.","persona":"any","source":"concept","cat":"spot-it"},
  // Any job, any role
  {"id":"fs-017","cat":"jobs-roles","type":"sort","hook":"Sort: a real job anyone can do, or a made-up 'one gender' rule?","items":[{"id":"a","text":"Pilot"},{"id":"b","text":"Nurse"},{"id":"c","text":"Engineer"},{"id":"d","text":"Teacher"},{"id":"e","text":"\"Pilots must be men\""},{"id":"f","text":"\"Nursing is women's work only\""}],"bins":[{"id":"any","label":"Anyone can do it","valence":"pos"},{"id":"one","label":"Made-up rule","valence":"neg"}],"key":{"a":"any","b":"any","c":"any","d":"any","e":"one","f":"one"},"relearn":"Every job can be done by anyone, whatever their gender; 'one gender' rules are made up.","persona":"any","source":"jobs / equality"},
  {"id":"fs-018","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Flying planes is a man's job.\"","myth":{"un":"Flying planes is a man's job.","re":"Women fly planes too; India has one of the world's highest shares of women pilots.","why":"Skill, not gender, decides who can fly."},"relearn":"Women are pilots too; flying isn't a 'man's job'.","persona":"Diya","source":"jobs / India fact"},
  {"id":"fs-019","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Cooking is for women; men can't cook.\"","myth":{"un":"Cooking is women's work; men can't cook.","re":"Anyone can cook; many top chefs are men, and dads cook too.","why":"Cooking is a skill, not a gender."},"relearn":"Anyone can cook; it isn't 'women's work'.","persona":"Rohit","source":"chores / jobs"},
  {"id":"fs-020","cat":"jobs-roles","type":"match","hook":"Match the role to a real person who breaks the stereotype.","pairs":[{"left":"Astronaut","right":"Kalpana Chawla"},{"left":"Boxer","right":"Mary Kom"},{"left":"Cricket captain","right":"Harmanpreet Kaur"},{"left":"Fighter pilot","right":"A woman in the air force"},{"left":"Stay-at-home parent","right":"A caring dad"}],"relearn":"Real people break gender stereotypes in every field.","persona":"any","source":"role models"},
  {"id":"fs-021","cat":"jobs-roles","type":"sort","hook":"Sort: a chore anyone can share, or a made-up 'whose job' rule?","items":[{"id":"a","text":"Washing dishes"},{"id":"b","text":"Fixing a bike"},{"id":"c","text":"Cooking dinner"},{"id":"d","text":"Taking out the bin"},{"id":"e","text":"\"Dishes are only the girls' job\""},{"id":"f","text":"\"Boys never cook\""}],"bins":[{"id":"anyone","label":"Anyone at home","valence":"pos"},{"id":"gendered","label":"Made-up rule","valence":"neg"}],"key":{"a":"anyone","b":"anyone","c":"anyone","d":"anyone","e":"gendered","f":"gendered"},"relearn":"All home chores can be shared by anyone, not split by gender; 'whose job' rules are made up.","persona":"any","source":"chores"},
  {"id":"fs-022","cat":"jobs-roles","type":"branch","hook":"Your group is picking a class captain; someone says \"it should be a boy\".","options":[{"text":"Say \"anyone can lead; let's pick the best person\"","consequence":"The choice opens up fairly.","outcome":"fair","best":true},{"text":"Go along with 'a boy'","consequence":"Leadership isn't gendered; the best person can be anyone."}],"debrief":"Leadership isn't a boy or girl thing, it's a skill thing.","relearn":"Anyone can be a leader, regardless of gender.","persona":"Diya","source":"leadership / equality"},
  {"id":"fs-023","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Nursing is only for women.\"","myth":{"un":"Only women can be nurses.","re":"Men are nurses too; caring is a skill anyone can have.","why":"Care work isn't owned by one gender."},"relearn":"Men can be nurses; caring isn't only for women.","persona":"any","source":"jobs"},
  {"id":"fs-024","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Girls aren't good at science and maths.\"","myth":{"un":"Girls aren't good at science or maths.","re":"Girls do brilliantly in science and maths everywhere.","why":"Ability isn't decided by gender."},"relearn":"Girls excel in science and maths; the stereotype is false.","persona":"Diya","source":"education / equality"},
  {"id":"fs-025","cat":"jobs-roles","type":"branch","hook":"A friend says \"boys shouldn't do dance class\".","options":[{"text":"Point out famous male dancers and that anyone can dance","consequence":"Your friend rethinks it.","outcome":"fair","best":true},{"text":"Agree to avoid teasing","consequence":"Dance is for anyone; many celebrated dancers are men."}],"debrief":"Dance, like any art, is open to everyone.","relearn":"Boys can dance; the arts aren't gendered.","persona":"Aarav","source":"arts / equality"},
  {"id":"fs-026","cat":"jobs-roles","type":"match","hook":"Match the job to the truth.","pairs":[{"left":"Soldier","right":"Women serve too"},{"left":"Stay-at-home parent","right":"Can be a dad"},{"left":"Scientist","right":"Any gender"},{"left":"Pilot","right":"Women fly too"},{"left":"Nurse","right":"Men care too"}],"relearn":"Jobs and family roles aren't limited by gender.","persona":"any","source":"jobs / roles"},
  {"id":"fs-027","cat":"jobs-roles","type":"reflect","hook":"Lensy: name a job you'd love, does your gender stop you? (It doesn't.)","prompt":"What do you think?","options":["Nothing stops me","I can do it","Good point"],"affirm":"Your dreams aren't limited by your gender, ever.","relearn":"Your gender doesn't limit the job you can dream of.","persona":"any","source":"aspiration"},
  {"id":"fs-028","cat":"jobs-roles","type":"reflect","hook":"Lensy: when a home shares all chores, everyone wins. Agree?","prompt":"What do you think?","options":["Yes","Fairer for all","Less load on mum"],"affirm":"Shared chores mean a fairer, happier home.","relearn":"Sharing chores fairly helps everyone at home.","persona":"Rohit","source":"chores / fairness"},
  {"id":"fs-029","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Driving is a man's thing.\"","myth":{"un":"Driving is really a man's thing.","re":"Women drive everything from scooters to planes to trucks.","why":"Driving is a skill, not a gender."},"relearn":"Driving isn't a 'man's thing'; anyone can drive.","persona":"any","source":"jobs / skills"},
  {"id":"fs-030","cat":"jobs-roles","type":"sort","hook":"Sort: breaks a job stereotype, or repeats one?","items":[{"id":"a","text":"A woman fighter pilot"},{"id":"b","text":"\"Only men can be bosses\""},{"id":"c","text":"A male kindergarten teacher"},{"id":"d","text":"\"Girls should just be homemakers\""},{"id":"e","text":"A woman running her own garage"},{"id":"f","text":"\"Men can't be nurses\""}],"bins":[{"id":"breaks","label":"Breaks it","valence":"pos"},{"id":"repeats","label":"Repeats it","valence":"neg"}],"key":{"a":"breaks","b":"repeats","c":"breaks","d":"repeats","e":"breaks","f":"repeats"},"relearn":"Breaking job stereotypes shows what's really possible.","persona":"any","source":"jobs / equality"},
  // Feelings & strength (boys cry, girls lead)
  {"id":"fs-031","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Boys don't cry.\"","myth":{"un":"Real boys don't cry.","re":"Everyone cries; it's healthy, not weak.","why":"Feelings aren't a gender; bottling them up hurts."},"relearn":"Boys cry too; feelings aren't weakness.","persona":"Aarav","source":"emotions / gender"},
  {"id":"fs-032","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Be a man, toughen up, don't feel things.\"","myth":{"un":"Being a man means never showing feelings.","re":"Strong people feel and express emotions.","why":"Hiding all feelings isn't strength, it's strain."},"relearn":"Real strength includes feeling and showing emotions.","persona":"Aarav","source":"masculinity / emotions"},
  {"id":"fs-033","cat":"feelings-strength","type":"strike-rewrite","hook":"\"You throw like a girl\" (as an insult).","myth":{"un":"'Like a girl' means weak or bad.","re":"'Like a girl' can mean strong, fast and skilled.","why":"Using a gender as an insult is the stereotype."},"relearn":"'Like a girl' isn't an insult; girls are strong and skilled.","persona":"Diya","source":"language / gender"},
  {"id":"fs-034","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Girls are too emotional to lead.\"","myth":{"un":"Girls are too emotional to be good leaders.","re":"Understanding emotions makes someone a better leader.","why":"Emotional skill is a leadership strength."},"relearn":"Being in touch with emotions helps leadership; it doesn't block it.","persona":"any","source":"leadership / gender"},
  {"id":"fs-035","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Girls can't be angry; they should be sweet.\"","myth":{"un":"Girls should always be sweet, never angry.","re":"Everyone feels anger; girls are allowed to as well.","why":"Demanding only 'sweet' silences real feelings."},"relearn":"Girls can feel and show anger like anyone else.","persona":"Diya","source":"emotions / gender"},
  {"id":"fs-036","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Boys must always be brave and never scared.\"","myth":{"un":"Boys must always be brave and never afraid.","re":"Everyone feels fear; admitting it is brave too.","why":"Pretending you're never scared is its own pressure."},"relearn":"Boys feel fear too; admitting it is okay and brave.","persona":"Aarav","source":"emotions / gender"},
  {"id":"fs-037","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Caring and gentleness are only for girls.\"","myth":{"un":"Being caring and gentle is only for girls.","re":"Kindness and gentleness suit everyone.","why":"Good qualities aren't owned by a gender."},"relearn":"Caring and gentleness are for everyone, not just girls.","persona":"any","source":"traits / gender"},
  {"id":"fs-038","cat":"feelings-strength","type":"branch","hook":"A boy in your class is crying and others start mocking him.","options":[{"text":"Say \"it's okay to cry\" and stand with him","consequence":"You ease the shame; others may stop.","outcome":"ally","best":true},{"text":"Join the mocking so you're not next","consequence":"Crying isn't shameful; standing with him is the kinder, braver move."}],"debrief":"Mocking a boy for crying enforces a harmful stereotype.","relearn":"Support someone showing feelings; don't shame them.","persona":"Aarav","source":"emotions / bystander"},
  {"id":"fs-039","cat":"feelings-strength","type":"branch","hook":"A girl wants to try out for the football team; people laugh.","options":[{"text":"Encourage her and cheer her on","consequence":"She tries out; maybe others follow.","outcome":"ally","best":true},{"text":"Laugh along","consequence":"Girls play football brilliantly; back her up."}],"debrief":"Sport is for every gender; back people who break the mould.","relearn":"Girls can play any sport; cheer them on.","persona":"Diya","source":"sport / gender"},
  {"id":"fs-040","cat":"feelings-strength","type":"branch","hook":"Your friend says \"asking for help is for girls; men sort it alone\".","options":[{"text":"Say \"asking for help is smart for anyone\"","consequence":"You reframe help as strength.","outcome":"fair","best":true},{"text":"Agree and never ask for help","consequence":"Asking for help is a strength, not a gender thing."}],"debrief":"'Tough it out alone' is a harmful stereotype, help-seeking is healthy.","relearn":"Asking for help is smart for everyone, regardless of gender.","persona":"Aarav","source":"help-seeking / masculinity"},
  {"id":"fs-041","cat":"feelings-strength","type":"role-play","hook":"Someone tells you \"man up, stop whining\".","setup":"Flip it calmly. Say:","yourLine":[{"text":"\"Feeling things isn't whining; it's human.\"","best":true},{"text":"\"You're right, I'll hide it.\""}],"relearn":"You can push back on 'man up'; feelings are human.","persona":"Aarav","source":"masculinity / voice"},
  {"id":"fs-042","cat":"feelings-strength","type":"role-play","hook":"A friend mocks another girl for being 'bossy' when she leads.","setup":"Reframe it. Say:","yourLine":[{"text":"\"She's not bossy, she's a leader.\"","best":true},{"text":"\"Yeah, so bossy.\""}],"relearn":"A girl who leads is a leader, not 'bossy'.","persona":"Diya","source":"language / leadership"},
  {"id":"fs-043","cat":"feelings-strength","type":"role-play","hook":"Someone says \"that colour/hobby is too girly for you\".","setup":"Own it. Say:","yourLine":[{"text":"\"I like it, and that's enough.\"","best":true},{"text":"\"Okay, I'll stop liking it.\""}],"relearn":"You can like what you like; tastes aren't gendered.","persona":"any","source":"identity / voice"},
  {"id":"fs-044","cat":"feelings-strength","type":"reflect","hook":"Lensy: which feeling are you sometimes told to hide because of your gender?","prompt":"Be honest.","options":["Sadness","Anger","Fear","None, I show them all"],"affirm":"All your feelings are allowed; none belong to one gender.","relearn":"No feeling is off-limits because of your gender.","persona":"any","source":"emotions / gender"},
  {"id":"fs-045","cat":"feelings-strength","type":"reflect","hook":"Lensy: 'strong' can mean lifting weights or sharing how you feel. Both count?","prompt":"What do you think?","options":["Yes","Both are strength","Good point"],"affirm":"Emotional strength counts just as much as physical strength.","relearn":"Strength includes emotional openness, not just muscle.","persona":"Aarav","source":"strength / emotions"},
  {"id":"fs-046","cat":"feelings-strength","type":"reflect","hook":"Lensy: a world where boys can cry and girls can lead, better for everyone?","prompt":"What do you think?","options":["Yes","Freer for all","Definitely"],"affirm":"Dropping these rules frees everyone to be fully themselves.","relearn":"Letting go of gender rules frees everyone.","persona":"any","source":"equality"},
  // Colours, clothes & stuff aren't gendered
  {"id":"fs-047","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Pink is for girls, blue is for boys.\"","myth":{"un":"Pink is for girls and blue is for boys.","re":"Colours are for everyone; pink was once a 'boy' colour.","why":"Colour rules are made up and they change."},"relearn":"Colours have no gender; anyone can like any colour.","persona":"any","source":"colours / history"},
  {"id":"fs-048","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Boys can't have long hair.\"","myth":{"un":"Boys shouldn't have long hair.","re":"Hair length is a personal choice, not a gender rule.","why":"Across history and cultures, all genders wore long hair."},"relearn":"Hair length is personal, not a gender rule.","persona":"Aarav","source":"appearance"},
  {"id":"fs-049","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Girls must wear dresses; trousers aren't for them.\"","myth":{"un":"Girls should only wear dresses.","re":"Girls wear whatever is comfortable, trousers included.","why":"Clothes are about comfort and choice, not rules."},"relearn":"Girls can wear trousers or anything; clothes aren't gendered.","persona":"Diya","source":"clothing"},
  {"id":"fs-050","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Dolls are for girls; boys shouldn't play with them.\"","myth":{"un":"Dolls are only for girls.","re":"Playing with dolls helps any kid practise caring.","why":"Toys teach skills, not gender."},"relearn":"Any child can play with dolls; toys aren't gendered.","persona":"any","source":"toys"},
  {"id":"fs-051","cat":"looks-stuff","type":"sort","hook":"Sort each line: who is this colour/toy/clothing really for?","items":[{"id":"a","text":"\"A red football is for any kid\""},{"id":"b","text":"\"Purple bags are only for girls\""},{"id":"c","text":"\"A toy kitchen suits anyone\""},{"id":"d","text":"\"Building sets aren't for girls\""},{"id":"e","text":"\"Anyone can wear bangles\""},{"id":"f","text":"\"Blue raincoats are just for boys\""}],"bins":[{"id":"anyone","label":"For anyone","valence":"pos"},{"id":"one","label":"One gender only","valence":"neg"}],"key":{"a":"anyone","b":"one","c":"anyone","d":"one","e":"anyone","f":"one"},"relearn":"Colours, toys and clothes are for anyone who likes them.","persona":"any","source":"stuff / gender"},
  {"id":"fs-052","cat":"looks-stuff","type":"sort","hook":"Sort: a made-up rule, or a real reason?","items":[{"id":"a","text":"\"Boys can't wear pink\""},{"id":"b","text":"\"Wear a helmet on a bike\""},{"id":"c","text":"\"Girls can't have short hair\""},{"id":"d","text":"\"Wash hands before eating\""},{"id":"e","text":"\"Dolls aren't for boys\""},{"id":"f","text":"\"Tie hair back near a flame\""}],"bins":[{"id":"madeup","label":"Made-up rule","valence":"neg"},{"id":"real","label":"Real reason","valence":"pos"}],"key":{"a":"madeup","b":"real","c":"madeup","d":"real","e":"madeup","f":"real"},"relearn":"Gendered looks 'rules' are made up; safety and hygiene rules are real.","persona":"any","source":"rules / gender"},
  {"id":"fs-053","cat":"looks-stuff","type":"sort","hook":"Sort: colour facts.","items":[{"id":"a","text":"Pink was once seen as a strong 'boy' colour"},{"id":"b","text":"Colours have feelings of their own"},{"id":"c","text":"Anyone can like any colour"},{"id":"d","text":"Liking blue makes you a boy"},{"id":"e","text":"Colour-gender rules have changed over time"},{"id":"f","text":"A colour can decide who you are"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Colour-gender links are invented and have changed over time.","persona":"any","source":"colours / history"},
  {"id":"fs-054","cat":"looks-stuff","type":"spot","hook":"A shop's kids section. Spot the stereotype.","scene":[{"id":"a","text":"A pink aisle labelled 'Girls'","trick":true},{"id":"b","text":"A blue aisle labelled 'Boys'","trick":true},{"id":"c","text":"A checkout counter","trick":false},{"id":"d","text":"A shelf of school bags","trick":false},{"id":"e","text":"A basket of footballs","trick":false}],"why":"Splitting shops into pink-girl and blue-boy aisles is a made-up divide.","relearn":"Shops often stereotype with pink-girl, blue-boy aisles; spot it.","persona":"any","source":"media literacy / retail"},
  {"id":"fs-055","cat":"looks-stuff","type":"spot","hook":"A birthday party theme list. Spot the stereotype.","scene":[{"id":"a","text":"\"Princess parties for girls\"","trick":true},{"id":"b","text":"\"Superhero parties for boys\"","trick":true},{"id":"c","text":"\"Cake included\"","trick":false},{"id":"d","text":"\"Games for everyone\"","trick":false},{"id":"e","text":"\"Party starts at five\"","trick":false}],"why":"Party themes get split by gender, but any kid can love any theme.","relearn":"Party themes aren't gendered; spot the split.","persona":"any","source":"media literacy / products"},
  {"id":"fs-056","cat":"looks-stuff","type":"match","hook":"Match the item to the truth.","pairs":[{"left":"Pink shirt","right":"For anyone"},{"left":"Toy car","right":"Any kid can play with it"},{"left":"Hair clip","right":"Keeps anyone's hair tidy"},{"left":"Skipping rope","right":"For any kid who likes to play"},{"left":"Purple bag","right":"Just a colour anyone can carry"}],"relearn":"Everyday items aren't owned by one gender.","persona":"any","source":"stuff / gender"},
  {"id":"fs-057","cat":"looks-stuff","type":"reflect","hook":"Lensy: wear and like what you enjoy, who does that hurt? (No one.)","prompt":"What do you think?","options":["No one","It's my choice","Exactly"],"affirm":"Your tastes are yours; enjoying them harms no one.","relearn":"Liking what you like harms no one; it's your choice.","persona":"any","source":"identity"},
  {"id":"fs-058","cat":"looks-stuff","type":"reflect","hook":"Lensy: imagine if no toy or colour had a gender label. Freeing?","prompt":"What do you think?","options":["Yes","So much freer","I'd try everything"],"affirm":"Without labels, you're free to enjoy it all.","relearn":"Dropping gender labels on stuff frees everyone's choices.","persona":"any","source":"equality"},
  // Flip the script (remix the stereotype)
  {"id":"fs-059","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls are bad at sports.\"","myth":{"un":"Girls are bad at sports.","re":"Girls are champions in every sport.","why":"Skill comes from practice, not gender."},"relearn":"Flip 'girls are bad at sports' to 'girls are champions'.","persona":"Diya","source":"flip / sport"},
  {"id":"fs-060","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys can't take care of babies.\"","myth":{"un":"Boys can't take care of babies.","re":"Boys and men make caring, capable parents.","why":"Caring is learned, not gendered."},"relearn":"Flip 'boys can't care for babies' to 'men are caring parents'.","persona":"Rohit","source":"flip / caregiving"},
  {"id":"fs-061","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Leaders are men.\"","myth":{"un":"Leaders are men.","re":"Leaders are people of any gender with vision and care.","why":"Leadership is a skill set, not a gender."},"relearn":"Flip 'leaders are men' to 'leaders can be anyone'.","persona":"any","source":"flip / leadership"},
  {"id":"fs-062","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls should stay home.\"","myth":{"un":"A girl's place is at home.","re":"Girls belong anywhere they choose, school, work, the world.","why":"No place is off-limits because of gender."},"relearn":"Flip 'girls stay home' to 'girls belong anywhere they choose'.","persona":"Diya","source":"flip / aspiration"},
  {"id":"fs-063","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Real men don't do housework.\"","myth":{"un":"Real men don't do housework.","re":"Sharing housework is exactly what fair, real partners do.","why":"A home runs on everyone pitching in."},"relearn":"Flip 'men don't do housework' to 'fair partners share it'.","persona":"Rohit","source":"flip / chores"},
  {"id":"fs-064","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys are naturally smarter.\"","myth":{"un":"Boys are naturally smarter than girls.","re":"Intelligence isn't decided by gender at all.","why":"Brains don't come in 'boy' or 'girl' versions."},"relearn":"Flip 'boys are smarter' to 'intelligence isn't gendered'.","persona":"any","source":"flip / ability"},
  {"id":"fs-065","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Pretty is the most important thing for a girl.\"","myth":{"un":"Being pretty is the most important thing for a girl.","re":"Girls matter for their minds, skills and kindness, not just looks.","why":"Worth isn't a beauty score."},"relearn":"Flip 'pretty matters most' to 'her mind and skills matter most'.","persona":"Diya","source":"flip / worth"},
  {"id":"fs-066","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys who like reading or art are weird.\"","myth":{"un":"Boys who like reading or art are weird.","re":"Boys who love books and art are just being themselves.","why":"Interests don't have a gender."},"relearn":"Flip 'art is weird for boys' to 'any interest fits any kid'.","persona":"Aarav","source":"flip / interests"},
  {"id":"fs-067","cat":"flip-it","type":"branch","hook":"You're remixing an old advert for class. It shows only mum cooking.","options":[{"text":"Remix it: show the whole family cooking together","consequence":"Your flipped ad models fairness.","outcome":"creative","best":true},{"text":"Leave it as is","consequence":"Flipping it to a shared scene challenges the stereotype."}],"debrief":"Remaking a stereotyped message into a fair one is 'flipping the script'.","relearn":"You can remix stereotyped media into fair messages.","persona":"any","source":"flip / media-making"},
  {"id":"fs-068","cat":"flip-it","type":"branch","hook":"You're writing a story; the default hero is a boy who rescues a girl.","options":[{"text":"Flip it: make either character the hero, or both","consequence":"Your story breaks the tired mould.","outcome":"creative","best":true},{"text":"Keep the default","consequence":"Flipping the roles makes a fresher, fairer story."}],"debrief":"Stories don't have to follow the old gender script.","relearn":"You can write heroes of any gender.","persona":"any","source":"flip / storytelling"},
  {"id":"fs-069","cat":"flip-it","type":"role-play","hook":"A friend says \"that's a girls' game, you can't play\".","setup":"Flip the script. Say:","yourLine":[{"text":"\"Games don't have a gender, deal me in.\"","best":true},{"text":"\"Oh, okay, I'll watch.\""}],"relearn":"You can flip 'that's a girls'/boys' game' on the spot.","persona":"any","source":"flip / voice"},
  {"id":"fs-070","cat":"flip-it","type":"role-play","hook":"Someone says \"you can't be a doctor, you're a girl\".","setup":"Flip it confidently. Say:","yourLine":[{"text":"\"Watch me, girls are doctors all the time.\"","best":true},{"text":"\"Maybe you're right.\""}],"relearn":"You can flip 'a girl can't be a doctor' with confidence.","persona":"Diya","source":"flip / aspiration"},
  {"id":"fs-071","cat":"flip-it","type":"spot","hook":"You're checking your own remix for hidden stereotypes. Spot any.","scene":[{"id":"a","text":"The boss character is still always a man","trick":true},{"id":"b","text":"The team is mixed and fair","trick":false},{"id":"c","text":"The carer is still always a woman","trick":true},{"id":"d","text":"A girl is shown leading the project","trick":false},{"id":"e","text":"A dad is shown picking up the kids","trick":false}],"why":"Even when flipping, old defaults can sneak back; check your own work.","relearn":"Check even your own work for stereotypes that sneak in.","persona":"any","source":"flip / self-check"},
  {"id":"fs-072","cat":"flip-it","type":"reflect","hook":"Lensy: flipping a stereotype out loud, does it get easier with practice?","prompt":"What do you think?","options":["Yes","Much easier","Like a muscle"],"affirm":"Flipping scripts is a muscle, it strengthens every time.","relearn":"Challenging stereotypes gets easier the more you practise.","persona":"any","source":"practice"},
  // Call it out & remix it
  {"id":"fs-073","cat":"call-it-out","type":"role-play","hook":"An elder says \"girls shouldn't laugh so loudly\".","setup":"Respond respectfully but firmly. Say:","yourLine":[{"text":"\"I think everyone should be free to laugh, na?\"","best":true},{"text":"\"Sorry, I'll be quiet.\""}],"relearn":"You can question a stereotype respectfully, even with elders.","persona":"Diya","source":"voice / respect"},
  {"id":"fs-074","cat":"call-it-out","type":"role-play","hook":"A classmate says \"ew, that's so gay\" about a boy liking pink.","setup":"Call it out kindly. Say:","yourLine":[{"text":"\"Liking a colour is just liking a colour, leave him be.\"","best":true},{"text":"\"Haha yeah, so weird.\""}],"relearn":"You can call out put-downs that police how others express themselves.","persona":"Aarav","source":"voice / inclusion"},
  {"id":"fs-075","cat":"call-it-out","type":"role-play","hook":"A relative says to your brother \"you're the man, you'll handle money; she'll cook\".","setup":"Offer a fairer view. Say:","yourLine":[{"text":"\"We can both learn money and cooking, right?\"","best":true},{"text":"Stay silent"}],"relearn":"You can gently offer a fairer view when roles get assigned by gender.","persona":"Diya","source":"voice / family"},
  {"id":"fs-076","cat":"call-it-out","type":"role-play","hook":"Friends chant \"boys are better\" at a match.","setup":"Flip the chant. Say:","yourLine":[{"text":"\"Everyone's got game, let's just play.\"","best":true},{"text":"Join the chant"}],"relearn":"You can refuse and reframe 'one gender is better' chants.","persona":"Aarav","source":"voice / sport"},
  {"id":"fs-077","cat":"call-it-out","type":"branch","hook":"A teacher only ever picks boys to carry heavy things and girls to decorate.","options":[{"text":"Politely ask if everyone can get a turn at both","consequence":"The teacher rethinks the split.","outcome":"fair","best":true},{"text":"Say nothing","consequence":"A polite question can open up fairer choices."}],"debrief":"Even well-meant habits can stereotype; a kind question helps.","relearn":"You can ask, kindly, for tasks to be shared beyond gender.","persona":"any","source":"voice / school"},
  {"id":"fs-078","cat":"call-it-out","type":"branch","hook":"Online, a video mocks boys who do ballet. Friends are sharing it.","options":[{"text":"Don't share; comment that ballet takes huge strength","consequence":"You break the pile-on with a fact.","outcome":"ally","best":true},{"text":"Share it for the laughs","consequence":"Ballet is athletic and tough; don't amplify the mockery."}],"debrief":"You can refuse to spread stereotype-mocking content.","relearn":"Don't amplify content that mocks people for breaking gender norms.","persona":"Aarav","source":"voice / online"},
  {"id":"fs-079","cat":"call-it-out","type":"branch","hook":"Your little cousin is told \"don't be a sissy\". You're nearby.","options":[{"text":"Reassure them: \"feeling scared is normal and okay\"","consequence":"You undo a little of the harm.","outcome":"caring","best":true},{"text":"Ignore it","consequence":"A kind word counters the 'sissy' shaming."}],"debrief":"You can be the voice that flips a harmful message for a younger kid.","relearn":"You can reassure a younger child against gender shaming.","persona":"any","source":"voice / mentoring"},
  {"id":"fs-080","cat":"call-it-out","type":"strike-rewrite","hook":"\"Calling out a stereotype is rude or 'too much'.\"","myth":{"un":"Pointing out a stereotype is rude or too much.","re":"Questioning unfairness, kindly, is fair and brave.","why":"Politeness and standing up can go together."},"relearn":"Calling out a stereotype kindly is brave, not rude.","persona":"Asha","source":"voice / values"},
  {"id":"fs-081","cat":"call-it-out","type":"strike-rewrite","hook":"\"One person can't change how people think.\"","myth":{"un":"One kid speaking up changes nothing.","re":"One voice often gives others courage to agree.","why":"Change usually starts with one person."},"relearn":"One voice flipping a stereotype can spark others.","persona":"Asha","source":"voice / change"},
  {"id":"fs-082","cat":"call-it-out","type":"strike-rewrite","hook":"\"It's not my problem if a stereotype isn't about me.\"","myth":{"un":"Stereotypes that don't target me aren't my problem.","re":"Speaking up for others is how fairness spreads.","why":"Allies make the biggest difference."},"relearn":"You can speak up against stereotypes even when they're not about you.","persona":"any","source":"allyship"},
  {"id":"fs-083","cat":"call-it-out","type":"reflect","hook":"Lensy: what's your go-to line for flipping a stereotype now?","prompt":"Pick your line.","options":["\"Anyone can do that\"","\"That's just a stereotype\"","\"Let's be fair\"","\"Why not?\""],"affirm":"Keep that line ready, you're now a script-flipper.","relearn":"Having a ready line helps you flip stereotypes in the moment.","persona":"any","source":"consolidation"},
  {"id":"fs-084","cat":"call-it-out","type":"reflect","hook":"Lensy: biggest take-away from Flip the Script?","prompt":"Pick your motto.","options":["Spot it","Question it","Flip it","Call it out"],"affirm":"Spot it, flip it, call it out, you've got the whole move.","relearn":"Spot the stereotype, flip it, and call it out, that's the skill.","persona":"any","source":"consolidation"},
  {"id":"fs-900","cat":"call-it-out","type":"role-play","hook":"At a wedding, an aunty says \"beta, only girls do mehndi; you're a boy, go play outside\".","setup":"Stay warm but stand your ground. Say:","yourLine":[{"text":"\"Mehndi's just fun art, aunty. Can I try a small one too?\"","best":true},{"text":"\"Okay, sorry, I'll go.\""}],"relearn":"You can kindly question a 'that's only for girls' rule, even with elders.","persona":"any","source":"voice / family"},
  {"id":"fs-901","cat":"call-it-out","type":"role-play","hook":"In the playground, boys tell a girl \"go away, cricket is for boys only\".","setup":"Back her up. Say:","yourLine":[{"text":"\"She bats brilliantly. Let's pick teams by skill, na?\"","best":true},{"text":"\"Yeah, this is a boys' game.\""}],"relearn":"You can speak up so anyone gets a fair turn at a game.","persona":"Diya","source":"voice / sport"},
  {"id":"fs-902","cat":"call-it-out","type":"role-play","hook":"Your uncle laughs at your brother for helping in the kitchen: \"chef boy, ha!\"","setup":"Reframe it kindly. Say:","yourLine":[{"text":"\"Cooking's a great skill, uncle. I'm glad he's learning.\"","best":true},{"text":"\"Haha, yeah, so funny.\""}],"relearn":"You can gently defend someone teased for crossing a gender 'rule'.","persona":"Rohit","source":"voice / family"},
  {"id":"fs-903","cat":"call-it-out","type":"role-play","hook":"A shopkeeper hands the toy car to your friend's brother and a doll to her.","setup":"Speak up for fair choice. Say:","yourLine":[{"text":"\"They can each pick whichever one they like, right?\"","best":true},{"text":"Take it quietly and leave"}],"relearn":"You can ask, kindly, for kids to choose toys themselves, not by gender.","persona":"any","source":"voice / shops"},
  {"id":"fs-904","cat":"call-it-out","type":"role-play","hook":"A senior tells the new girl \"don't take science group, girls do better in arts\".","setup":"Offer a fairer view. Say:","yourLine":[{"text":"\"She should pick what she loves, girls ace science too.\"","best":true},{"text":"\"Maybe he's right, take arts.\""}],"relearn":"You can call out steering someone away from a subject by gender.","persona":"Diya","source":"voice / school"},
  {"id":"fs-905","cat":"call-it-out","type":"role-play","hook":"At a cousin's birthday, someone says \"don't give him that pink balloon, he'll cry like a baby\".","setup":"Call it out gently. Say:","yourLine":[{"text":"\"Pink's a happy colour. Give him whichever he wants.\"","best":true},{"text":"\"True, swap it for blue.\""}],"relearn":"You can flip a 'pink is shameful for boys' jibe on the spot.","persona":"Aarav","source":"voice / colours"},
  {"id":"fs-906","cat":"call-it-out","type":"role-play","hook":"A friend says \"don't tell anyone you do classical dance, boys will rag you\".","setup":"Stand by your choice. Say:","yourLine":[{"text":"\"Dance takes real strength and discipline. I'm proud of it.\"","best":true},{"text":"\"You're right, I'll hide it.\""}],"relearn":"You can refuse to feel ashamed of a hobby called 'not for boys'.","persona":"Aarav","source":"voice / identity"},
  {"id":"fs-907","cat":"call-it-out","type":"role-play","hook":"At tuition, a boy mocks a girl: \"you got top marks? Must've cheated, girls aren't smart\".","setup":"Defend her fairly. Say:","yourLine":[{"text":"\"She studied hard and earned it. That's just smart, full stop.\"","best":true},{"text":"\"Haha, yeah, lucky guess.\""}],"relearn":"You can call out a put-down that credits a girl's win to luck.","persona":"any","source":"voice / school"},
  {"id":"fs-908","cat":"call-it-out","type":"role-play","hook":"Relatives tease your friend's dad for pushing the baby's pram in the park.","setup":"Back the dad up. Say:","yourLine":[{"text":"\"It's lovely seeing a dad care for his baby like that.\"","best":true},{"text":"Laugh along with them"}],"relearn":"You can support a dad doing caregiving instead of joining the teasing.","persona":"Rohit","source":"voice / caregiving"},
  {"id":"fs-909","cat":"call-it-out","type":"role-play","hook":"In class, someone calls a boy a name for sitting with the girls.","setup":"Shut the name-calling down kindly. Say:","yourLine":[{"text":"\"That's just a mean name. Anyone can sit with anyone.\"","best":true},{"text":"Stay quiet and look away"}],"relearn":"You can name unfair teasing as wrong and stop it spreading.","persona":"any","source":"voice / inclusion"},
  {"id":"fs-910","cat":"call-it-out","type":"role-play","hook":"A coach says \"you girls warm up gently; boys, do the real drills\".","setup":"Ask for fair training. Say:","yourLine":[{"text":"\"Can we all do the same drills, sir? We're keen to push hard.\"","best":true},{"text":"\"Okay, we'll go gentle.\""}],"relearn":"You can ask, kindly, for the same chance to train as everyone else.","persona":"Diya","source":"voice / sport"},
  {"id":"fs-911","cat":"call-it-out","type":"role-play","hook":"Your grandmother says \"a girl shouldn't ride a bicycle to school because it's not nice\".","setup":"Question it respectfully. Say:","yourLine":[{"text":"\"Cycling's just quick and healthy, dadi. Is it really unfair to want that?\"","best":true},{"text":"\"Okay dadi, I'll walk.\""}],"relearn":"You can lovingly ask an elder 'is this fair?' without disrespect.","persona":"Diya","source":"voice / family"},
  {"id":"fs-912","cat":"call-it-out","type":"role-play","hook":"A boy in the group says \"crying's for girls\" when your friend tears up over a lost match.","setup":"Reassure your friend, flip the jibe. Say:","yourLine":[{"text":"\"He cares about the game. That's not weak, that's heart.\"","best":true},{"text":"\"Ha, yeah, what a baby.\""}],"relearn":"You can defend a boy's tears as normal, not 'girly' or weak.","persona":"Aarav","source":"voice / feelings"},
  {"id":"fs-913","cat":"call-it-out","type":"role-play","hook":"A neighbour tells your sister \"learn cooking now; your brother should just study\".","setup":"Suggest fairness. Say:","yourLine":[{"text":"\"We'd both love to learn cooking and study. Why not share both?\"","best":true},{"text":"Nod and say nothing"}],"relearn":"You can gently push back when chores get handed out by gender.","persona":"any","source":"voice / family"},
  {"id":"fs-914","cat":"call-it-out","type":"role-play","hook":"On the bus, kids chant at a long-haired boy: \"girl, girl, girl!\"","setup":"Step in calmly. Say:","yourLine":[{"text":"\"It's just his hair. Leave him be, it suits him fine.\"","best":true},{"text":"Join in for a laugh"}],"relearn":"You can stop teasing about a boy's hair without making a scene.","persona":"any","source":"voice / appearance"},
  {"id":"fs-915","cat":"call-it-out","type":"role-play","hook":"A teammate snaps at the captain: \"a girl can't lead us, she's too bossy\".","setup":"Reframe her leading. Say:","yourLine":[{"text":"\"She's not bossy. She's organised, and we're winning with her.\"","best":true},{"text":"\"Yeah, swap her out.\""}],"relearn":"You can rename 'bossy' as good leadership when a girl leads.","persona":"Diya","source":"voice / leadership"},
  {"id":"fs-916","cat":"call-it-out","type":"role-play","hook":"A friend forwards a 'funny' meme mocking househusbands and asks you to share it.","setup":"Decline kindly. Say:","yourLine":[{"text":"\"I'll skip this one, dads at home work hard, it's not a joke.\"","best":true},{"text":"\"Sure, sending it on.\""}],"relearn":"You can refuse to forward content that mocks people for sharing roles.","persona":"any","source":"voice / online"},
  {"id":"fs-917","cat":"call-it-out","type":"role-play","hook":"Your little cousin is told \"big boys don't get scared of the dark, so be a man\".","setup":"Reassure your cousin. Say:","yourLine":[{"text":"\"Being scared of the dark is normal. I'll sit with you till you sleep.\"","best":true},{"text":"\"Yeah, toughen up.\""}],"relearn":"You can comfort a younger kid shamed for feeling fear.","persona":"any","source":"voice / mentoring"},
  {"id":"fs-918","cat":"call-it-out","type":"branch","hook":"A group chat is piling 'unladylike' comments on a girl who posted herself skateboarding.","options":[{"text":"Say she skates great and ask the others to ease off","consequence":"Your support shifts the tone; the pile-on eases.","outcome":"ally","best":true},{"text":"Mute the group and ignore it","consequence":"One kind comment can break a pile-on; silence lets it grow."}],"debrief":"Speaking up online for someone you don't even know is real allyship.","relearn":"You can defend someone facing a gendered pile-on online.","persona":"Asha","source":"voice / online"},
  {"id":"fs-919","cat":"call-it-out","type":"branch","hook":"At a family lunch, an uncle says only the boys should be served first.","options":[{"text":"Quietly suggest everyone gets served together","consequence":"A few relatives nod; the table shares more evenly.","outcome":"fair","best":true},{"text":"Eat last without a word","consequence":"A gentle suggestion can nudge a fairer habit; silence keeps the old one."}],"debrief":"Even old family customs can be questioned, kindly, without a fight.","relearn":"You can gently question a custom that favours one gender.","persona":"Diya","source":"voice / family"},
  {"id":"fs-920","cat":"call-it-out","type":"branch","hook":"A teacher always asks boys to move desks and girls to wipe the board.","options":[{"text":"Ask politely if jobs can rotate so everyone does both","consequence":"The teacher agrees to swap roles each week.","outcome":"fair","best":true},{"text":"Just do your assigned job","consequence":"A kind question can open up fairer jobs; going along keeps the split."}],"debrief":"Well-meant routines can still stereotype; a polite ask helps.","relearn":"You can ask, kindly, for classroom jobs to be shared beyond gender.","persona":"any","source":"voice / school"},
  {"id":"fs-921","cat":"call-it-out","type":"branch","hook":"Your friends are laughing at a video of a man crying at his daughter's wedding.","options":[{"text":"Say it's touching, not funny, and don't reshare","consequence":"The laughing fades; one friend agrees it's sweet.","outcome":"ally","best":true},{"text":"Laugh and forward it","consequence":"A man's tears aren't a joke; you can choose not to amplify the mockery."}],"debrief":"You can refuse to spread content mocking men for showing feelings.","relearn":"You can decline to share clips that shame men for crying.","persona":"Aarav","source":"voice / online"},
  {"id":"fs-922","cat":"call-it-out","type":"branch","hook":"A shopkeeper tells your friend \"that football's for your brother, so pick a kitchen set\".","options":[{"text":"Say she actually wants the football and that's fine","consequence":"The shopkeeper hands her the ball; she beams.","outcome":"fair","best":true},{"text":"Let her take the kitchen set","consequence":"A kid can pick any toy; backing her choice beats going along."}],"debrief":"You can stand up for a friend's free choice of toy.","relearn":"You can back a friend choosing a toy that breaks the 'rule'.","persona":"any","source":"voice / shops"},
  {"id":"fs-923","cat":"call-it-out","type":"branch","hook":"In group chat, classmates rate girls' looks and tag your cousin to join in.","options":[{"text":"Say you're out and that rating people isn't cool","consequence":"Two others back you and the thread dies down.","outcome":"ally","best":true},{"text":"Add a rating to fit in","consequence":"Rating people reduces them to looks; opting out is the fairer call."}],"debrief":"You can refuse to join in reducing girls to a looks score.","relearn":"You can opt out of and call out a 'rate the girls' thread.","persona":"any","source":"voice / online"},
  {"id":"fs-924","cat":"call-it-out","type":"branch","hook":"At drama club, the teacher says \"boys can't play the lead nurse, so give it to a girl\".","options":[{"text":"Point out anyone can play any role and ask to audition fairly","consequence":"The teacher opens auditions to all.","outcome":"fair","best":true},{"text":"Accept the smaller role","consequence":"Roles aren't gendered; a fair audition is worth asking for."}],"debrief":"You can ask for casting by talent, not by gender.","relearn":"You can request that roles be cast on skill, not gender.","persona":"Aarav","source":"voice / school"},
  {"id":"fs-925","cat":"call-it-out","type":"branch","hook":"Your younger brother is crying and an elder says \"stop it or I'll put you with the girls\".","options":[{"text":"Tell your brother it's okay to cry and sit with him","consequence":"He calms down; the shaming loses its sting.","outcome":"caring","best":true},{"text":"Tell him to stop crying","consequence":"Crying isn't shameful; comforting him undoes a little of the harm."}],"debrief":"You can be the voice that tells a younger kid feelings are okay.","relearn":"You can reassure a younger child shamed for crying.","persona":"any","source":"voice / mentoring"},
  {"id":"fs-926","cat":"call-it-out","type":"branch","hook":"Friends plan to skip the women's match on TV, saying \"it's not real cricket\".","options":[{"text":"Suggest watching it; the women's team is brilliant","consequence":"They give it a go and end up cheering.","outcome":"ally","best":true},{"text":"Agree and switch the channel","consequence":"Women's sport is real sport; suggesting it can change minds."}],"debrief":"You can challenge the idea that only men's sport counts.","relearn":"You can speak up for women's sport getting equal airtime.","persona":"Diya","source":"voice / sport"},
  {"id":"fs-927","cat":"call-it-out","type":"branch","hook":"A relative gives your sister a beauty kit and you a science set, saying \"that suits each of you\".","options":[{"text":"Thank them, then say you'd both happily swap or share","consequence":"They laugh and let you both pick freely.","outcome":"fair","best":true},{"text":"Keep the gifts as assigned","consequence":"Interests aren't gendered; a warm word can open up the choice."}],"debrief":"You can question gifts handed out by gender, without seeming rude.","relearn":"You can gently flip gifts split along boy/girl lines.","persona":"any","source":"voice / family"},
  {"id":"fs-928","cat":"call-it-out","type":"branch","hook":"Boys block a girl from the carrom table: \"go skip rope, this is our game\".","options":[{"text":"Say she's next and the table's for everyone","consequence":"They make room; she plays a great round.","outcome":"ally","best":true},{"text":"Wait your turn and say nothing","consequence":"Games are for everyone; one fair word lets her in."}],"debrief":"You can make space for someone shut out of a game by gender.","relearn":"You can speak up so a game is open to every gender.","persona":"any","source":"voice / inclusion"},
  {"id":"fs-929","cat":"call-it-out","type":"branch","hook":"A classmate says \"don't pick her for the science fair, she'll just cry under pressure\".","options":[{"text":"Say she's calm and sharp and deserves a fair shot","consequence":"The team picks her; she shines.","outcome":"fair","best":true},{"text":"Pick someone else to be safe","consequence":"'Too emotional' is a stereotype, not a fact; back her on merit."}],"debrief":"You can challenge 'girls crack under pressure' with what you've seen.","relearn":"You can call out 'too emotional' used to sideline a girl.","persona":"Diya","source":"voice / school"},
  {"id":"fs-930","cat":"call-it-out","type":"branch","hook":"At a sleepover, a friend mocks another boy for bringing a soft toy from home.","options":[{"text":"Say lots of people keep comfort toys and it's no big deal","consequence":"The teasing stops; the boy relaxes.","outcome":"ally","best":true},{"text":"Hide your own and laugh","consequence":"Comfort isn't gendered; a kind word ends the teasing fast."}],"debrief":"You can defend a boy teased for something gentle or comforting.","relearn":"You can stand up for a boy mocked over a comfort object.","persona":"Aarav","source":"voice / feelings"},
  {"id":"fs-931","cat":"call-it-out","type":"branch","hook":"Online, a viral clip mocks a boy doing rangoli; your friends are commenting laughing emojis.","options":[{"text":"Comment that his rangoli is gorgeous and skip the mockery","consequence":"A few switch to praise; the tone lifts.","outcome":"ally","best":true},{"text":"Drop a laughing emoji too","consequence":"Art has no gender; praising the work beats joining the pile-on."}],"debrief":"You can swap a pile-on for genuine praise, online.","relearn":"You can replace online mockery with real appreciation.","persona":"any","source":"voice / online"},
  {"id":"fs-932","cat":"call-it-out","type":"strike-rewrite","hook":"\"If I call out a stereotype in front of elders, I'm being disrespectful.\"","myth":{"un":"Questioning an elder's stereotype is disrespectful.","re":"You can ask 'is this fair, na?' warmly and stay respectful.","why":"Respect and a gentle question can sit together."},"relearn":"You can question an elder's stereotype kindly and still be respectful.","persona":"Asha","source":"voice / respect"},
  {"id":"fs-933","cat":"call-it-out","type":"strike-rewrite","hook":"\"I should only speak up if the unfair comment is about me.\"","myth":{"un":"It's only my place to speak up if it's about me.","re":"Speaking up for someone else is how fairness spreads.","why":"Allies turn one voice into many."},"relearn":"You can speak up for others, not just yourself.","persona":"any","source":"allyship"},
  {"id":"fs-978","cat":"call-it-out","type":"strike-rewrite","hook":"\"Calling it out will just start a fight, so it's safer to stay quiet.\"","myth":{"un":"Calling out unfairness always starts a fight.","re":"A calm, kind question usually opens a talk, not a fight.","why":"How you say it sets the tone."},"relearn":"A gentle call-out invites a conversation, not a clash.","persona":"Asha","source":"voice / values"},
  {"id":"fs-934","cat":"call-it-out","type":"strike-rewrite","hook":"\"If I stay silent, at least I'm not making things worse.\"","myth":{"un":"Staying silent keeps me out of it and harms no one.","re":"Silence can let an unfair comment stand as if it's true.","why":"Saying nothing often reads as agreeing."},"relearn":"Silence can look like agreeing; a kind word breaks that.","persona":"any","source":"bystander / voice"},
  {"id":"fs-935","cat":"call-it-out","type":"strike-rewrite","hook":"\"You have to be loud and angry to call out unfairness.\"","myth":{"un":"Calling it out means being loud and angry.","re":"A quiet, kind question often works better than shouting.","why":"Calm words are easier to hear."},"relearn":"You don't have to be loud or angry to call it out: calm works.","persona":"Asha","source":"voice / how-to"},
  {"id":"fs-936","cat":"call-it-out","type":"strike-rewrite","hook":"\"One kid saying something can't change a whole group's habit.\"","myth":{"un":"One kid speaking up changes nothing in a group.","re":"One voice often gives others the courage to agree out loud.","why":"People wait for someone to go first."},"relearn":"One voice can free others to agree; change starts with one.","persona":"Asha","source":"voice / change"},
  {"id":"fs-937","cat":"call-it-out","type":"strike-rewrite","hook":"\"If something is a long-running tradition, I can't question it.\"","myth":{"un":"A tradition can't be questioned just because it's old.","re":"You can honour what's kind in a custom and still ask what's unfair.","why":"Customs are made by people and can grow fairer."},"relearn":"You can respect a tradition and still question its unfair parts.","persona":"any","source":"voice / culture"},
  {"id":"fs-938","cat":"call-it-out","type":"strike-rewrite","hook":"\"Pointing out a joke is sexist makes me a spoilsport.\"","myth":{"un":"Naming a sexist joke makes me a spoilsport.","re":"Saying 'that one's not fair' keeps the fun without the put-down.","why":"A joke that demeans a group isn't harmless fun."},"relearn":"You can call out a sexist joke without killing the fun.","persona":"any","source":"voice / humour"},
  {"id":"fs-939","cat":"call-it-out","type":"strike-rewrite","hook":"\"I don't have the right words, so I shouldn't say anything.\"","myth":{"un":"I need perfect words or I shouldn't speak up.","re":"A simple 'hey, that's not fair' is more than enough.","why":"Showing up matters more than sounding clever."},"relearn":"You don't need perfect words; a simple, kind line works.","persona":"any","source":"voice / how-to"},
  {"id":"fs-940","cat":"call-it-out","type":"strike-rewrite","hook":"\"Sharing a 'funny' sexist meme is fine. It's just a joke.\"","myth":{"un":"Forwarding a sexist meme is harmless, it's just a joke.","re":"Every share spreads the put-down a little further.","why":"You can choose not to pass it on."},"relearn":"You can refuse to forward a meme that puts down a gender.","persona":"any","source":"voice / online"},
  {"id":"fs-941","cat":"call-it-out","type":"strike-rewrite","hook":"\"Calling out my own friends will just lose me friends.\"","myth":{"un":"Calling out friends means losing them.","re":"Good friends can hear 'that wasn't fair' and still stay close.","why":"Honesty, said kindly, can deepen a friendship."},"relearn":"You can call out a friend kindly and keep the friendship.","persona":"any","source":"voice / friends"},
  {"id":"fs-942","cat":"call-it-out","type":"strike-rewrite","hook":"\"If a grown-up said it, it must be right, so I shouldn't argue.\"","myth":{"un":"If a grown-up said it, it must be right.","re":"Grown-ups can repeat old stereotypes too; you can gently ask why.","why":"Being older doesn't make a stereotype true."},"relearn":"Grown-ups can be wrong about stereotypes; you can kindly ask why.","persona":"any","source":"voice / respect"},
  {"id":"fs-943","cat":"call-it-out","type":"strike-rewrite","hook":"\"Defending someone from teasing just makes me the next target.\"","myth":{"un":"Sticking up for someone makes me the next target.","re":"Often others quietly agree and join you once you start.","why":"Standing together is safer than standing alone."},"relearn":"Standing up for someone often brings others to your side.","persona":"any","source":"allyship"},
  {"id":"fs-944","cat":"call-it-out","type":"strike-rewrite","hook":"\"It's not my job to fix how my little cousin is being raised.\"","myth":{"un":"It's not my place to flip a message a younger kid is told.","re":"You can quietly reassure a cousin told 'don't be a sissy'.","why":"A kind word from you can outweigh a harsh one."},"relearn":"You can reassure a younger kid against a harmful gender message.","persona":"any","source":"voice / mentoring"},
  {"id":"fs-945","cat":"call-it-out","type":"reflect","hook":"Lensy: think of a time you wished you'd spoken up but stayed quiet. What held you back?","prompt":"Be honest with yourself.","options":["Felt nervous","Didn't want a scene","Couldn't find words","Worried what friends think"],"affirm":"Naming what stops you is the first step to speaking up next time.","relearn":"Spotting what holds you back makes it easier to speak up next time.","persona":"any","source":"voice / reflection"},
  {"id":"fs-946","cat":"call-it-out","type":"reflect","hook":"Lensy: who in your life could use you as an ally when a stereotype lands on them?","prompt":"Picture them.","options":["A younger cousin","A new classmate","A friend who's teased","Someone left out"],"affirm":"Just imagining backing them up makes you readier to do it.","relearn":"Thinking of who needs an ally prepares you to be one.","persona":"any","source":"allyship"},
  {"id":"fs-947","cat":"call-it-out","type":"reflect","hook":"Lensy: kind or harsh, which call-out actually gets people to listen?","prompt":"What do you think?","options":["Kind, every time","Calm beats loud","Curious questions","Depends, but rarely harsh"],"affirm":"A kind, curious tone keeps the door open for people to change.","relearn":"Kind, calm call-outs are the ones people actually hear.","persona":"Asha","source":"voice / how-to"},
  {"id":"fs-948","cat":"call-it-out","type":"reflect","hook":"Lensy: what's one ready line you'll keep in your pocket to flip a stereotype?","prompt":"Pick yours.","options":["\"Is that fair, na?\"","\"Anyone can do that\"","\"Let's all get a turn\"","\"That's just a stereotype\""],"affirm":"Keep that line ready: you'll reach for it when the moment comes.","relearn":"Having a ready line helps you call it out in the moment.","persona":"any","source":"consolidation"},
  {"id":"fs-949","cat":"call-it-out","type":"reflect","hook":"Lensy: when you scroll and a clip mocks someone for breaking a gender 'rule', what feels right?","prompt":"What would you do?","options":["Don't share it","Scroll past","Drop a kind comment","Report if it's cruel"],"affirm":"Choosing not to amplify the mockery is a real, quiet kind of brave.","relearn":"You can choose not to spread content that mocks people online.","persona":"any","source":"voice / online"},
  {"id":"fs-950","cat":"call-it-out","type":"reflect","hook":"Lensy: does standing up for someone who isn't you feel worth it?","prompt":"What do you think?","options":["Yes, always","It's what allies do","I'd want the same","Fairness is for all"],"affirm":"Speaking up for others is how fairness spreads past your own seat.","relearn":"Allyship means speaking up for others, and it spreads fairness widely.","persona":"any","source":"allyship"},
  {"id":"fs-951","cat":"call-it-out","type":"reflect","hook":"Lensy: imagine a class where everyone calls out unfairness kindly. How does it feel?","prompt":"What do you think?","options":["Safer for all","Friendlier","Freer to be me","Everyone gets a turn"],"affirm":"When calling it out is normal and kind, everyone breathes easier.","relearn":"A space where people call out unfairness kindly feels safer for all.","persona":"any","source":"equality"},
  {"id":"fs-952","cat":"call-it-out","type":"reflect","hook":"Lensy: which feels braver: joining the laugh, or being the one who says 'not cool'?","prompt":"What do you think?","options":["Saying 'not cool'","Standing apart","Going against the crowd","Both take guts, but speaking up wins"],"affirm":"Going against an easy laugh to be fair is a quiet, real bravery.","relearn":"Speaking up against the crowd is braver than going along.","persona":"any","source":"voice / values"},
  {"id":"fs-953","cat":"call-it-out","type":"reflect","hook":"Lensy: after you call something out kindly, what usually happens inside you?","prompt":"What do you notice?","options":["Proud of myself","A bit nervous, then glad","Lighter","Like I'd do it again"],"affirm":"That after-glow is your fairness instinct getting stronger.","relearn":"Calling it out kindly builds your confidence to do it again.","persona":"any","source":"voice / reflection"},
  {"id":"fs-954","cat":"call-it-out","type":"spot","hook":"A class chat on who leads the project. Spot the unfair lines.","scene":[{"id":"a","text":"\"Let a boy lead, girls just chatter\"","trick":true},{"id":"b","text":"\"Whoever has the best plan should lead\"","trick":false},{"id":"c","text":"\"She ran the last fest really well\"","trick":false},{"id":"d","text":"\"Girls are too soft to handle the team\"","trick":true},{"id":"e","text":"\"Let's just vote on it\"","trick":false}],"why":"'Girls just chatter' and 'girls are too soft' are stereotypes worth calling out.","relearn":"You can spot gender put-downs in a chat and call them out.","persona":"Diya","source":"voice / online"},
  {"id":"fs-955","cat":"call-it-out","type":"spot","hook":"Comments under a girl's cricket video. Spot the two you'd call out.","scene":[{"id":"a","text":"\"Wow, what a cover drive!\"","trick":false},{"id":"b","text":"\"Go back to the kitchen\"","trick":true},{"id":"c","text":"\"Great footwork, keep it up\"","trick":false},{"id":"d","text":"\"Girls can't play, this is fake\"","trick":true},{"id":"e","text":"\"Selected for state? Brilliant!\"","trick":false}],"why":"'Go back to the kitchen' and 'girls can't play' are stereotypes, not fair feedback.","relearn":"You can spot and call out the put-downs hiding among real comments.","persona":"any","source":"voice / online"},
  {"id":"fs-956","cat":"call-it-out","type":"spot","hook":"Things said at a family dinner. Spot the two worth gently calling out.","scene":[{"id":"a","text":"\"Pass the dal, please\"","trick":false},{"id":"b","text":"\"Boys don't need to learn cooking\"","trick":true},{"id":"c","text":"\"This sabzi turned out great\"","trick":false},{"id":"d","text":"\"Let her clear up, that's a girl's job\"","trick":true},{"id":"e","text":"\"Who's washing up tonight? Let's take turns\"","trick":false}],"why":"'Boys needn't cook' and 'clearing up is a girl's job' are stereotypes to flip.","relearn":"You can spot gendered chore lines at home and kindly call them out.","persona":"Rohit","source":"voice / family"},
  {"id":"fs-957","cat":"call-it-out","type":"spot","hook":"Locker-room talk after PE. Spot the two lines to call out.","scene":[{"id":"a","text":"\"Good game, everyone\"","trick":false},{"id":"b","text":"\"You run like a girl, so slow\"","trick":true},{"id":"c","text":"\"Let's practise passing tomorrow\"","trick":false},{"id":"d","text":"\"Real boys don't stretch, that's soft\"","trick":true},{"id":"e","text":"\"Nice save in goal\"","trick":false}],"why":"'Run like a girl' and 'real boys don't stretch' are put-downs dressed as banter.","relearn":"You can spot a gender insult inside banter and call it out kindly.","persona":"Aarav","source":"voice / sport"},
  {"id":"fs-958","cat":"call-it-out","type":"spot","hook":"A teacher hands out roles for the school play. Spot the two unfair calls.","scene":[{"id":"a","text":"\"Auditions are open to anyone\"","trick":false},{"id":"b","text":"\"Boys can't play the caring nurse role\"","trick":true},{"id":"c","text":"\"We'll cast on who fits best\"","trick":false},{"id":"d","text":"\"Only girls for the dancing parts\"","trick":true},{"id":"e","text":"\"Let's read lines and decide together\"","trick":false}],"why":"Barring boys from caring roles or girls-only dancing splits parts by gender, not talent.","relearn":"You can spot roles split by gender and ask for fair casting.","persona":"any","source":"voice / school"},
  {"id":"fs-959","cat":"call-it-out","type":"spot","hook":"Replies to a dad's post about being a stay-at-home parent. Spot the two to call out.","scene":[{"id":"a","text":"\"Your kids are lucky, lovely to see\"","trick":false},{"id":"b","text":"\"A real man earns, he doesn't babysit\"","trick":true},{"id":"c","text":"\"Caring for your own kids is great\"","trick":false},{"id":"d","text":"\"That's the wife's job, not yours\"","trick":true},{"id":"e","text":"\"Respect: parenting is hard work\"","trick":false}],"why":"'Real men earn' and 'that's the wife's job' are stereotypes about who can care.","relearn":"You can spot and flip put-downs aimed at a caring dad.","persona":"Rohit","source":"voice / online"},
  {"id":"fs-960","cat":"call-it-out","type":"spot","hook":"Captions on a fairness-cream-style ad. Spot the two stereotype lines to call out.","scene":[{"id":"a","text":"\"She got the job after going fairer\"","trick":true},{"id":"b","text":"\"Skill got her the interview\"","trick":false},{"id":"c","text":"\"Confidence comes from within\"","trick":false},{"id":"d","text":"\"Fairer skin means a brighter future\"","trick":true},{"id":"e","text":"\"Your worth isn't your shade\"","trick":false}],"why":"Tying jobs and worth to fairer skin is a false, harmful message to call out.","relearn":"You can spot and call out 'fairer skin = more worth' messaging.","persona":"Diya","source":"voice / media"},
  {"id":"fs-961","cat":"call-it-out","type":"spot","hook":"Things said when a girl joins the chess club. Spot the two to call out.","scene":[{"id":"a","text":"\"Welcome, grab a board\"","trick":false},{"id":"b","text":"\"Chess needs a sharp mind, not for girls\"","trick":true},{"id":"c","text":"\"Want a friendly first game?\"","trick":false},{"id":"d","text":"\"You'll just cry when you lose\"","trick":true},{"id":"e","text":"\"We meet every Friday, join us\"","trick":false}],"why":"'Not for girls' and 'you'll just cry' are stereotypes, not real reasons to exclude.","relearn":"You can spot exclusion dressed as fact and call it out.","persona":"Diya","source":"voice / school"},
  {"id":"fs-962","cat":"call-it-out","type":"match","hook":"Match the unfair line to a kind, ready call-out.","pairs":[{"left":"\"Boys don't cry\"","right":"\"Everyone cries; it's just being human\""},{"left":"\"She's so bossy\"","right":"\"She's leading. That's a good thing\""},{"left":"\"That's a girls' game\"","right":"\"Games are for anyone, deal me in\""},{"left":"\"Pink's not for boys\"","right":"\"It's just a colour, he can like it\""},{"left":"\"Cooking's women's work\"","right":"\"Anyone can cook; it's a great skill\""}],"relearn":"For each stereotype, you can keep a kind, ready line to flip it.","persona":"any","source":"voice / how-to"},
  {"id":"fs-963","cat":"call-it-out","type":"match","hook":"Match the moment to a fair line you can say.","pairs":[{"left":"Elder bars a girl from cycling","right":"\"Is wanting to cycle unfair?\""},{"left":"Friend forwards a sexist meme","right":"\"I'll skip this put-down\""},{"left":"Cousin shamed for being scared","right":"\"Being scared is okay\""},{"left":"Coach gives girls easier drills","right":"\"Can we all do the same?\""},{"left":"Boys block a girl from cricket","right":"\"Pick teams by skill\""}],"relearn":"Each unfair moment has a kind, doable line you can use.","persona":"any","source":"voice / how-to"},
  {"id":"fs-964","cat":"call-it-out","type":"match","hook":"Match who you're standing up for to the allyship moment.","pairs":[{"left":"A new classmate left out","right":"Invite them into the game"},{"left":"A boy mocked for crying","right":"Sit with him and say it's okay"},{"left":"A girl told she can't lead","right":"Back her for captain"},{"left":"A dad teased for cooking","right":"Praise the meal he made"},{"left":"A kid piled on online","right":"Post one kind comment"}],"relearn":"Allyship means a small, concrete act for whoever needs backing.","persona":"any","source":"allyship"},
  {"id":"fs-965","cat":"call-it-out","type":"match","hook":"Match the stereotype to the real person who flips it.","pairs":[{"left":"\"Girls can't fly planes\"","right":"India has many women pilots"},{"left":"\"Boxing's not for girls\"","right":"Mary Kom, world champion"},{"left":"\"Space is a man's world\"","right":"Kalpana Chawla, astronaut"},{"left":"\"Girls can't captain\"","right":"A woman captains India"},{"left":"\"Men can't be carers\"","right":"Many dads raise kids full-time"}],"relearn":"Real examples help you call out a stereotype with a fact.","persona":"any","source":"role models"},
  {"id":"fs-966","cat":"call-it-out","type":"match","hook":"Match the kind of call-out to what makes it work.","pairs":[{"left":"Calm tone","right":"Easier for people to actually hear"},{"left":"A curious question","right":"Invites them to rethink, not defend"},{"left":"Speaking for others","right":"Spreads fairness past yourself"},{"left":"Going first","right":"Gives others courage to agree"},{"left":"Not resharing","right":"Stops the put-down spreading"}],"relearn":"Kind, calm, curious call-outs work better than loud ones.","persona":"Asha","source":"voice / how-to"},
  {"id":"fs-967","cat":"call-it-out","type":"match","hook":"Match each tricky moment to where it happens, so you're ready to speak up.","pairs":[{"left":"\"Serve the boys first\"","right":"At a family lunch"},{"left":"\"Girls warm up gently\"","right":"At sports practice"},{"left":"\"Rate the girls' looks\"","right":"In a group chat"},{"left":"\"Boys can't do the nurse role\"","right":"At drama club"},{"left":"\"That toy's for your brother\"","right":"In a shop"}],"relearn":"Stereotypes show up everywhere; you can be ready to call them out.","persona":"any","source":"voice / how-to"},
  {"id":"fs-968","cat":"call-it-out","type":"match","hook":"Match the worry that stops you to the reframe that frees you to speak up.","pairs":[{"left":"\"I'll seem rude\"","right":"A kind question is fair, not rude"},{"left":"\"I'll lose friends\"","right":"Good friends can hear honesty"},{"left":"\"It's not my problem\"","right":"Speaking up for others spreads fairness"},{"left":"\"One voice won't matter\"","right":"One voice gives others courage"},{"left":"\"I'll start a fight\"","right":"A calm word opens a talk"}],"relearn":"Each worry that silences you has a reframe that frees you.","persona":"any","source":"voice / values"},
  {"id":"fs-969","cat":"call-it-out","type":"match","hook":"Match the put-down to why it's unfair, ready to explain when you call it out.","pairs":[{"left":"\"You throw like a girl\"","right":"Uses a gender as an insult"},{"left":"\"She's just bossy\"","right":"Names leadership as a flaw"},{"left":"\"Real men don't cry\"","right":"Bans a normal human feeling"},{"left":"\"Pink's a girls' colour\"","right":"Invents a rule for a colour"},{"left":"\"Girls can't do maths\"","right":"Claims ability comes from gender"}],"relearn":"Knowing why a line is unfair helps you call it out clearly.","persona":"any","source":"voice / how-to"},
  {"id":"fs-970","cat":"call-it-out","type":"sort","hook":"Sort each line: a kind call-out worth saying, or a put-down to flip?","items":[{"id":"a","text":"\"Let's all get a turn at this game\""},{"id":"b","text":"\"Go away, girls can't play\""},{"id":"c","text":"\"He's allowed to cry, leave him be\""},{"id":"d","text":"\"Crying's for babies and girls\""},{"id":"e","text":"\"Anyone can cook, it's a great skill\""},{"id":"f","text":"\"Cooking's not a boy's job\""}],"bins":[{"id":"callout","label":"Kind call-out","valence":"tell"},{"id":"putdown","label":"Put-down to flip","valence":"neg"}],"key":{"a":"callout","b":"putdown","c":"callout","d":"putdown","e":"callout","f":"putdown"},"relearn":"You can tell a fair, kind call-out from the put-down it answers.","persona":"any","source":"voice / how-to"},
  {"id":"fs-971","cat":"call-it-out","type":"sort","hook":"Sort each call-out: kind and likely to land, or harsh and likely to backfire?","items":[{"id":"a","text":"\"Hey, is that really fair, na?\""},{"id":"b","text":"\"You're so stupid for saying that\""},{"id":"c","text":"\"Can we share this job around?\""},{"id":"d","text":"\"Shut up, you're a sexist idiot\""},{"id":"e","text":"\"I see it differently. Anyone can lead\""},{"id":"f","text":"\"Only a moron thinks that\""}],"bins":[{"id":"kind","label":"Kind, lands","valence":"pos"},{"id":"harsh","label":"Harsh, backfires","valence":"uhoh"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Kind, calm call-outs land; insults make people defensive.","persona":"Asha","source":"voice / how-to"},
  {"id":"fs-972","cat":"call-it-out","type":"sort","hook":"Sort each move: speaking up for someone, or staying a silent bystander?","items":[{"id":"a","text":"Posting a kind comment on a piled-on video"},{"id":"b","text":"Scrolling past and saying nothing"},{"id":"c","text":"Sitting with a teased classmate"},{"id":"d","text":"Laughing along to fit in"},{"id":"e","text":"Asking the teacher to share jobs fairly"},{"id":"f","text":"Pretending you didn't hear it"}],"bins":[{"id":"speak","label":"Speaking up","valence":"tell"},{"id":"silent","label":"Staying silent","valence":"uhoh"}],"key":{"a":"speak","b":"silent","c":"speak","d":"silent","e":"speak","f":"silent"},"relearn":"Allyship is active; silence often lets unfairness stand.","persona":"any","source":"allyship"},
  {"id":"fs-973","cat":"call-it-out","type":"sort","hook":"Sort each line elders might say: a kind question back, or just going along?","items":[{"id":"a","text":"\"Is it really unfair to let her cycle?\""},{"id":"b","text":"\"Okay, I'll stay quiet then.\""},{"id":"c","text":"\"Could we both learn cooking, dadi?\""},{"id":"d","text":"\"Fine, the boys eat first.\""},{"id":"e","text":"\"What if everyone got a fair turn?\""},{"id":"f","text":"\"Sorry, I won't ask again.\""}],"bins":[{"id":"ask","label":"Kind question","valence":"tell"},{"id":"along","label":"Going along","valence":"uhoh"}],"key":{"a":"ask","b":"along","c":"ask","d":"along","e":"ask","f":"along"},"relearn":"You can question elders with a warm, respectful question, not silence.","persona":"Diya","source":"voice / respect"},
  {"id":"fs-974","cat":"call-it-out","type":"sort","hook":"Sort each online choice: spreads the put-down, or stops it?","items":[{"id":"a","text":"Forwarding a meme mocking househusbands"},{"id":"b","text":"Commenting genuine praise on the work"},{"id":"c","text":"Adding a laughing emoji to a pile-on"},{"id":"d","text":"Choosing not to reshare a cruel clip"},{"id":"e","text":"Reporting a video that's truly hateful"},{"id":"f","text":"Tagging friends to join the mockery"}],"bins":[{"id":"stops","label":"Stops it","valence":"pos"},{"id":"spreads","label":"Spreads it","valence":"neg"}],"key":{"a":"spreads","b":"stops","c":"spreads","d":"stops","e":"stops","f":"spreads"},"relearn":"You can choose online actions that stop a put-down, not spread it.","persona":"any","source":"voice / online"},
  {"id":"fs-975","cat":"call-it-out","type":"sort","hook":"Sort what you might tell a younger cousin being gender-shamed.","items":[{"id":"a","text":"\"Feeling scared is okay\""},{"id":"b","text":"\"Stop crying, you'll embarrass us\""},{"id":"c","text":"\"Like any colour you want\""},{"id":"d","text":"\"Toughen up, boys don't whine\""},{"id":"e","text":"\"Play with any toy you love\""},{"id":"f","text":"\"That's a girls' thing, drop it\""}],"bins":[{"id":"frees","label":"Frees them","valence":"pos"},{"id":"shames","label":"Shames them","valence":"neg"}],"key":{"a":"frees","b":"shames","c":"frees","d":"shames","e":"frees","f":"shames"},"relearn":"You can be the voice that frees a younger kid, not one that shames them.","persona":"any","source":"voice / mentoring"},
  {"id":"fs-976","cat":"call-it-out","type":"sort","hook":"Sort each reason for not speaking up: a real safety reason, or just a fear to flip?","items":[{"id":"a","text":"\"I might seem rude\""},{"id":"b","text":"\"They're being violent right now\""},{"id":"c","text":"\"Friends might tease me\""},{"id":"d","text":"\"It feels unsafe, I'll get a grown-up\""},{"id":"e","text":"\"I don't have perfect words\""},{"id":"f","text":"\"One voice won't matter\""}],"bins":[{"id":"safety","label":"Real safety call","valence":"uhoh"},{"id":"fear","label":"A fear to flip","valence":"tell"}],"key":{"a":"fear","b":"safety","c":"fear","d":"safety","e":"fear","f":"fear"},"relearn":"Most reasons to stay quiet are fears you can flip; real danger means get help.","persona":"any","source":"voice / values"},
  {"id":"fs-977","cat":"call-it-out","type":"sort","hook":"Sort each reply to a sexist joke: keeps the fun fairly, or joins the put-down?","items":[{"id":"a","text":"\"That one's not really fair, na?\""},{"id":"b","text":"\"Haha, do another on girls\""},{"id":"c","text":"\"Let's joke without picking on anyone\""},{"id":"d","text":"\"Good one, so true about women\""},{"id":"e","text":"\"Funny, but that's a put-down\""},{"id":"f","text":"\"Forward that, all will laugh\""}],"bins":[{"id":"fair","label":"Fair fun","valence":"pos"},{"id":"join","label":"Joins the put-down","valence":"neg"}],"key":{"a":"fair","b":"join","c":"fair","d":"join","e":"fair","f":"join"},"relearn":"You can keep the fun while calling out a joke that demeans a group.","persona":"any","source":"voice / humour"},
  {"id":"fs-990","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Crying is for babies and girls.\"","myth":{"un":"Crying is only for babies and girls.","re":"Crying is how anyone lets big feelings out.","why":"Tears ease stress; everyone's body does it."},"relearn":"Crying is healthy for any person, any age.","persona":"Aarav","source":"emotions / gender"},
  {"id":"fs-991","cat":"feelings-strength","type":"strike-rewrite","hook":"\"A boy who hugs his friends is soft.\"","myth":{"un":"Boys who hug friends are soft or weird.","re":"Showing warmth to friends is normal for anyone.","why":"Closeness and care aren't owned by a gender."},"relearn":"Boys can hug and show warmth; it's not weakness.","persona":"Aarav","source":"emotions / friendship"},
  {"id":"fs-992","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Don't be a sissy, hide that you're scared.\"","myth":{"un":"A real boy hides that he's scared.","re":"Saying you're scared takes real courage.","why":"Naming fear helps you face it; hiding it doesn't."},"relearn":"Admitting fear is brave, not weak.","persona":"Aarav","source":"emotions / courage"},
  {"id":"fs-993","cat":"feelings-strength","type":"strike-rewrite","hook":"\"She's so dramatic; girls overreact.\"","myth":{"un":"Girls are just dramatic and overreact.","re":"Feeling things strongly isn't 'drama'; it's being human.","why":"Calling a girl 'dramatic' silences real feelings."},"relearn":"Strong feelings aren't 'drama'; they're valid for anyone.","persona":"Diya","source":"emotions / gender"},
  {"id":"fs-994","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Boys must shake off pain and never wince.\"","myth":{"un":"A real boy never shows he's in pain.","re":"Everyone feels pain; saying it hurts is sensible.","why":"Hiding pain can stop you getting help in time."},"relearn":"Boys can say when something hurts; that's smart.","persona":"Aarav","source":"emotions / strength"},
  {"id":"fs-995","cat":"feelings-strength","type":"strike-rewrite","hook":"\"A good girl stays calm and never argues back.\"","myth":{"un":"A good girl never gets upset or argues.","re":"A girl can disagree and stand her ground.","why":"Always staying quiet buries what she really thinks."},"relearn":"Girls can speak up and disagree; that's healthy.","persona":"Diya","source":"emotions / voice"},
  {"id":"fs-996","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Boys can be loud and angry, but girls can't.\"","myth":{"un":"Anger is fine for boys but not for girls.","re":"Anger is a normal feeling for every gender.","why":"It's what you DO with anger that matters, not who feels it."},"relearn":"Everyone feels anger; no gender owns it.","persona":"Diya","source":"emotions / gender"},
  {"id":"fs-997","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Talking about your worries is unmanly.\"","myth":{"un":"Real men keep worries to themselves.","re":"Talking about worries is a smart way to cope.","why":"Sharing lightens a load; bottling it adds strain."},"relearn":"Sharing worries is healthy for everyone.","persona":"Aarav","source":"help-seeking / masculinity"},
  {"id":"fs-998","cat":"feelings-strength","type":"strike-rewrite","hook":"\"You hit like a girl, that's pathetic.\"","myth":{"un":"'Like a girl' means feeble.","re":"Mary Kom hits 'like a girl' and she's a world champion.","why":"Using 'girl' as an insult is the stereotype itself."},"relearn":"'Like a girl' can mean powerful and skilled.","persona":"Diya","source":"language / sport"},
  {"id":"fs-999","cat":"feelings-strength","type":"strike-rewrite","hook":"\"She's not leader material; she's too soft-hearted.\"","myth":{"un":"A kind, soft-hearted girl can't be a leader.","re":"Caring about people makes a leader people trust.","why":"Empathy helps a leader understand her team."},"relearn":"Kindness is a leadership strength, not a flaw.","persona":"any","source":"leadership / emotions"},
  {"id":"fs-1000","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Boys shouldn't comfort a crying friend; let an adult do it.\"","myth":{"un":"Comforting someone is not a boy's job.","re":"Any kid can comfort a friend who's upset.","why":"Caring for others is a skill, not a girl-only role."},"relearn":"Boys can comfort and care for friends too.","persona":"Aarav","source":"emotions / care"},
  {"id":"fs-1001","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Strong people never need anyone.\"","myth":{"un":"Truly strong people never need help.","re":"Even the strongest people lean on others sometimes.","why":"Knowing when to ask for help is its own strength."},"relearn":"Needing others isn't weakness; it's human.","persona":"any","source":"help-seeking / strength"},
  {"id":"fs-1002","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Girls who get angry are just being moody.\"","myth":{"un":"An angry girl is only being moody.","re":"Anger can mean something is unfair and worth fixing.","why":"Dismissing it as 'moody' ignores a real signal."},"relearn":"A girl's anger can point to real unfairness.","persona":"Diya","source":"emotions / fairness"},
  {"id":"fs-1003","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Men feel less than women; that's just nature.\"","myth":{"un":"Boys and men feel less than girls do.","re":"All genders feel the same range of emotions.","why":"Boys are often just taught to hide them, not spared them."},"relearn":"Everyone feels deeply; some are just told to hide it.","persona":"Aarav","source":"emotions / gender"},
  {"id":"fs-1004","cat":"feelings-strength","type":"strike-rewrite","hook":"\"A leader can't show nerves before a big match.\"","myth":{"un":"A real captain never feels nervous.","re":"Even India's captains feel nerves before a big game.","why":"Nerves are normal; courage is acting despite them."},"relearn":"Feeling nervous doesn't make you a weak leader.","persona":"any","source":"leadership / emotions"},
  {"id":"fs-1005","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Boys shouldn't keep a diary of their feelings.\"","myth":{"un":"Writing about feelings is a girl thing.","re":"Writing feelings down helps anyone think clearly.","why":"A diary is a private tool, not a gendered one."},"relearn":"Any kid can journal feelings; it's just a helpful habit.","persona":"Aarav","source":"emotions / coping"},
  {"id":"fs-1006","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Tough boys don't say sorry.\"","myth":{"un":"Apologising makes a boy look weak.","re":"Saying sorry when you're wrong takes real strength.","why":"It mends friendships; pride alone never does."},"relearn":"Apologising is a strong, caring thing to do.","persona":"Aarav","source":"emotions / character"},
  {"id":"fs-1007","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Girls should smile even when they feel awful.\"","myth":{"un":"A girl should always look happy and smile.","re":"Nobody has to fake a smile when they feel low.","why":"Hiding real feelings behind a smile is exhausting."},"relearn":"Girls don't owe anyone a fake smile.","persona":"Diya","source":"emotions / pressure"},
  {"id":"fs-1008","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Real men solve every problem alone.\"","myth":{"un":"A real man fixes everything by himself.","re":"Asking a friend or elder is a sign of good sense.","why":"Two heads beat one; teamwork isn't a weakness."},"relearn":"Asking for help is smart, not unmanly.","persona":"Aarav","source":"help-seeking / masculinity"},
  {"id":"fs-1009","cat":"feelings-strength","type":"strike-rewrite","hook":"\"A boy who's gentle with a pet is being girly.\"","myth":{"un":"Being gentle is a girly thing.","re":"Gentleness is just care, and anyone can have it.","why":"How softly you treat others isn't about gender."},"relearn":"Gentleness suits everyone, every gender.","persona":"Aarav","source":"traits / gender"},
  {"id":"fs-1010","cat":"feelings-strength","type":"strike-rewrite","hook":"\"She cried, so she can't handle the captain's armband.\"","myth":{"un":"A girl who cries can't be trusted to lead.","re":"Feeling deeply and leading well go together.","why":"Crying once says nothing about her judgement."},"relearn":"Tears don't disqualify anyone from leading.","persona":"any","source":"leadership / emotions"},
  {"id":"fs-1011","cat":"feelings-strength","type":"strike-rewrite","hook":"\"Boys must bottle it up and 'be strong' for the family.\"","myth":{"un":"A boy must hide feelings to be strong for others.","re":"You can be there for family AND show your feelings.","why":"Bottling up doesn't help anyone; it just hurts you."},"relearn":"Being strong and showing feelings go together.","persona":"Aarav","source":"emotions / family"},
  {"id":"fs-1012","cat":"feelings-strength","type":"branch","hook":"Your cousin (a boy) is scared of the dark and asks to leave a lamp on. An uncle calls him a 'sissy'.","options":[{"text":"Tell your cousin quietly that feeling scared is normal and okay","consequence":"He feels less ashamed and keeps his lamp on.","outcome":"ally","best":true},{"text":"Laugh along with the uncle","consequence":"Fear is normal; mocking it just teaches him to hide it."}],"debrief":"Mocking a boy for fear enforces a harmful stereotype.","relearn":"Feeling scared is normal; reassure, don't shame.","persona":"Aarav","source":"emotions / family"},
  {"id":"fs-1013","cat":"feelings-strength","type":"branch","hook":"In a group project, a girl gives clear instructions. A boy mutters she's 'too bossy'.","options":[{"text":"Say \"she's organising us well, that's leading\"","consequence":"The group refocuses and the project goes smoothly.","outcome":"fair","best":true},{"text":"Agree she should let a boy lead instead","consequence":"Leading well isn't 'bossy'; back her, don't sideline her."}],"debrief":"A girl who directs a team is leading, not 'bossy'.","relearn":"Calling a girl leader 'bossy' is the stereotype; name it.","persona":"Diya","source":"leadership / gender"},
  {"id":"fs-1014","cat":"feelings-strength","type":"branch","hook":"You lost the inter-house match and feel like crying, but classmates are watching.","options":[{"text":"Let yourself feel it; tears are okay even here","consequence":"You feel lighter and a teammate says they felt it too.","outcome":"healthy","best":true},{"text":"Force it down and act like you don't care","consequence":"Bottling it up adds strain; feelings need a way out."}],"debrief":"Showing disappointment isn't weak; it's honest and human.","relearn":"You can show feelings even when others are watching.","persona":"Aarav","source":"emotions / coping"},
  {"id":"fs-1015","cat":"feelings-strength","type":"branch","hook":"Your sister wins a debate and is buzzing with excitement. A relative says \"girls shouldn't be so loud and proud\".","options":[{"text":"Cheer for her: \"she earned it, let her be proud\"","consequence":"She keeps celebrating and feels backed up.","outcome":"ally","best":true},{"text":"Tell her to quieten down","consequence":"Pride in a real win is healthy; don't dim it for her gender."}],"debrief":"Girls are allowed to be loud, proud and confident.","relearn":"Back a girl's pride in her wins; don't shush it.","persona":"Diya","source":"emotions / confidence"},
  {"id":"fs-1016","cat":"feelings-strength","type":"branch","hook":"A friend is overwhelmed before exams and says \"I feel like crying but boys can't\".","options":[{"text":"Tell him boys cry too, and offer to study together","consequence":"He relaxes a bit and you both revise calmer.","outcome":"ally","best":true},{"text":"Tell him to just toughen up","consequence":"'Toughen up' adds pressure; reassurance helps more."}],"debrief":"Boys feel exam stress too; support beats 'toughen up'.","relearn":"Reassure a stressed friend; don't tell him to bottle it.","persona":"Aarav","source":"emotions / help-seeking"},
  {"id":"fs-1017","cat":"feelings-strength","type":"branch","hook":"A boy in your class wants to be the one who comforts a crying junior, but others say that's a girl's job.","options":[{"text":"Say \"anyone can comfort someone; go ahead\"","consequence":"He helps the junior calm down kindly.","outcome":"fair","best":true},{"text":"Tell him to wait for a girl to do it","consequence":"Caring isn't a girl-only job; let him help."}],"debrief":"Comforting others is a human skill, not a gender role.","relearn":"Boys can comfort and care; it's not 'a girl's job'.","persona":"Aarav","source":"emotions / care"},
  {"id":"fs-1018","cat":"feelings-strength","type":"branch","hook":"You feel anxious before a stage performance. Someone says \"only girls get nervous like that\".","options":[{"text":"Say \"everyone gets nervous; it means I care\"","consequence":"You reframe nerves and go on stage steadier.","outcome":"healthy","best":true},{"text":"Pretend you feel nothing","consequence":"Nerves are normal for any gender; naming them helps."}],"debrief":"Nervousness isn't a gender thing; it's a sign you care.","relearn":"Anyone can feel nervous; it doesn't mean weakness.","persona":"any","source":"emotions / pressure"},
  {"id":"fs-1019","cat":"feelings-strength","type":"branch","hook":"Your team captain (a girl) tears up after a tough loss. A teammate says she's 'too emotional to lead'.","options":[{"text":"Say \"she cares deeply, that's why she leads well\"","consequence":"The team rallies around her for the next match.","outcome":"fair","best":true},{"text":"Agree she should hand the armband to a boy","consequence":"Feeling deeply and leading go together; back her."}],"debrief":"Understanding emotions makes a leader stronger, not weaker.","relearn":"A leader's emotions aren't a reason to replace her.","persona":"any","source":"leadership / emotions"},
  {"id":"fs-1020","cat":"feelings-strength","type":"branch","hook":"A younger boy is teased for keeping a soft toy he loves. He looks ready to give it up.","options":[{"text":"Tell him liking a soft toy is totally fine","consequence":"He keeps his toy and feels okay about it.","outcome":"ally","best":true},{"text":"Suggest he hide it so no one teases him","consequence":"He shouldn't have to hide what he loves to please others."}],"debrief":"What a kid loves isn't a 'weakness' to mock.","relearn":"Reassure a kid teased for soft feelings; don't make him hide.","persona":"Aarav","source":"emotions / identity"},
  {"id":"fs-1021","cat":"feelings-strength","type":"branch","hook":"Your friend feels low for days but says \"asking a counsellor is for weak people\".","options":[{"text":"Say \"asking for help is a strong, smart move\"","consequence":"He's more open to talking to a trusted adult.","outcome":"fair","best":true},{"text":"Agree he should just deal with it alone","consequence":"'Tough it out alone' is a harmful myth; help-seeking is healthy."}],"debrief":"Reaching out for help is brave, not weak.","relearn":"Help-seeking is a strength; encourage it.","persona":"any","source":"help-seeking / emotions"},
  {"id":"fs-1022","cat":"feelings-strength","type":"role-play","hook":"At a family gathering, an uncle says \"boys in this house don't cry\".","setup":"Flip it gently. Say:","yourLine":[{"text":"\"Crying's just feelings coming out; that's okay, na?\"","best":true},{"text":"\"Okay, I'll stop crying.\""}],"relearn":"You can question 'boys don't cry' kindly; crying is okay.","persona":"Aarav","source":"emotions / family"},
  {"id":"fs-1023","cat":"feelings-strength","type":"role-play","hook":"A classmate says \"you're a girl, so stop being so angry about it\".","setup":"Stand your ground. Say:","yourLine":[{"text":"\"I'm angry because it's unfair, not because I'm a girl.\"","best":true},{"text":"\"You're right, I'll just stay quiet.\""}],"relearn":"Girls can name anger; it doesn't make it less valid.","persona":"Diya","source":"emotions / fairness"},
  {"id":"fs-1024","cat":"feelings-strength","type":"role-play","hook":"A friend mocks a boy for admitting he's scared of a school trek.","setup":"Back him up. Say:","yourLine":[{"text":"\"Saying you're scared takes guts, honestly.\"","best":true},{"text":"\"Yeah, what a scaredy-cat.\""}],"relearn":"Admitting fear is brave; back people who do.","persona":"Aarav","source":"emotions / courage"},
  {"id":"fs-1025","cat":"feelings-strength","type":"role-play","hook":"Someone tells your friend \"stop being so soft, harden up\".","setup":"Reframe softness. Say:","yourLine":[{"text":"\"Being kind isn't soft; it's a good thing.\"","best":true},{"text":"\"Yeah, you should toughen up.\""}],"relearn":"Kindness isn't weakness; it's a strength.","persona":"any","source":"traits / gender"},
  {"id":"fs-1026","cat":"feelings-strength","type":"role-play","hook":"A relative tells your sister \"good girls don't raise their voice\".","setup":"Flip it warmly. Say:","yourLine":[{"text":"\"She's just saying what she thinks; that's allowed, na?\"","best":true},{"text":"\"True, she should be quiet.\""}],"relearn":"Girls can speak up; that's healthy, not 'bad behaviour'.","persona":"Diya","source":"emotions / voice"},
  {"id":"fs-1027","cat":"feelings-strength","type":"role-play","hook":"A teammate says \"crying after a loss means you're not a real player\".","setup":"Push back kindly. Say:","yourLine":[{"text":"\"It means I care about the game; that's a good thing.\"","best":true},{"text":"\"You're right, I shouldn't have cried.\""}],"relearn":"Caring enough to cry doesn't make you less of a player.","persona":"Aarav","source":"emotions / sport"},
  {"id":"fs-1028","cat":"feelings-strength","type":"role-play","hook":"A friend says \"asking the teacher for help is embarrassing; men figure it out alone\".","setup":"Reframe it. Say:","yourLine":[{"text":"\"Asking is smart; that's how you actually learn.\"","best":true},{"text":"\"Fine, I won't ask anyone.\""}],"relearn":"Asking for help is smart for anyone.","persona":"Aarav","source":"help-seeking / masculinity"},
  {"id":"fs-1029","cat":"feelings-strength","type":"role-play","hook":"Someone calls a calm, caring boy \"too gentle to be a real boy\".","setup":"Own it for him. Say:","yourLine":[{"text":"\"Being gentle is just being kind; nothing wrong with it.\"","best":true},{"text":"\"Yeah, he should be tougher.\""}],"relearn":"Gentleness is fine for any boy; it's not a flaw.","persona":"Aarav","source":"traits / gender"},
  {"id":"fs-1030","cat":"feelings-strength","type":"role-play","hook":"A girl is told \"you're too sensitive to be the team captain\".","setup":"Reframe sensitivity. Say:","yourLine":[{"text":"\"Noticing how people feel makes a better captain, na?\"","best":true},{"text":"\"Maybe, she should step down.\""}],"relearn":"Sensitivity helps leadership; it doesn't block it.","persona":"any","source":"leadership / emotions"},
  {"id":"fs-1031","cat":"feelings-strength","type":"role-play","hook":"A cousin says \"you smiled even though you're upset; that's what good girls do\".","setup":"Be honest instead. Say:","yourLine":[{"text":"\"I don't have to fake a smile; it's okay to feel low.\"","best":true},{"text":"\"You're right, I'll keep smiling.\""}],"relearn":"You don't owe anyone a fake smile; real feelings are okay.","persona":"Diya","source":"emotions / pressure"},
  {"id":"fs-1032","cat":"feelings-strength","type":"reflect","hook":"Lensy: when you feel scared, what helps you most?","prompt":"There's no wrong answer.","options":["Telling a friend","Taking deep breaths","A grown-up I trust","Just sitting with it a bit"],"affirm":"Feeling scared is normal; finding what helps you is wise.","relearn":"Fear is normal for everyone; coping with it is a skill.","persona":"any","source":"emotions / coping"},
  {"id":"fs-1033","cat":"feelings-strength","type":"reflect","hook":"Lensy: a boy who shows his feelings and a girl who leads a team, both strong?","prompt":"What do you think?","options":["Yes","Both are strong","Definitely"],"affirm":"Strength shows up as feeling AND as leading, for any gender.","relearn":"Showing feelings and leading are both forms of strength.","persona":"any","source":"strength / gender"},
  {"id":"fs-1034","cat":"feelings-strength","type":"reflect","hook":"Lensy: which feeling do you find hardest to show out loud?","prompt":"Be honest with yourself.","options":["Sadness","Fear","Anger","I show them pretty freely"],"affirm":"Every feeling is allowed; none is off-limits for your gender.","relearn":"No feeling belongs to one gender; all are allowed.","persona":"any","source":"emotions / gender"},
  {"id":"fs-1035","cat":"feelings-strength","type":"reflect","hook":"Lensy: anger can tell you something is unfair. Useful to listen to it?","prompt":"What do you think?","options":["Yes","It's a signal","Makes sense"],"affirm":"Anger handled well can push you to fix what's unfair.","relearn":"Anger is a normal signal for any gender; listen to it.","persona":"Diya","source":"emotions / fairness"},
  {"id":"fs-1036","cat":"feelings-strength","type":"reflect","hook":"Lensy: asking for help when you're stuck, smart or weak?","prompt":"What do you think?","options":["Smart","A strength","Definitely smart"],"affirm":"Knowing when to ask for help is one of the strongest moves there is.","relearn":"Asking for help is a strength for everyone.","persona":"any","source":"help-seeking / strength"},
  {"id":"fs-1037","cat":"feelings-strength","type":"reflect","hook":"Lensy: a friend who comforts others, is that a kind of strong?","prompt":"What do you think?","options":["Yes","Caring is strong","For sure"],"affirm":"Caring for others is its own quiet strength, for any gender.","relearn":"Caring and comforting are strengths, not weaknesses.","persona":"any","source":"traits / strength"},
  {"id":"fs-1038","cat":"feelings-strength","type":"reflect","hook":"Lensy: when a friend is upset, what do you usually do?","prompt":"There's no wrong answer.","options":["Sit and listen","Cheer them up","Ask if they want help","Just be there quietly"],"affirm":"Whatever you choose, being there for a friend matters.","relearn":"Comforting a friend is something any kid can do.","persona":"any","source":"emotions / care"},
  {"id":"fs-1039","cat":"feelings-strength","type":"reflect","hook":"Lensy: nervous before something big usually means you care about it. Ring true?","prompt":"What do you think?","options":["Yes","I think so","Makes sense"],"affirm":"Nerves often mean it matters to you; that's nothing to hide.","relearn":"Nervousness is normal for anyone; it shows you care.","persona":"any","source":"emotions / pressure"},
  {"id":"fs-1040","cat":"feelings-strength","type":"reflect","hook":"Lensy: would a world where everyone could show their feelings be kinder?","prompt":"What do you think?","options":["Yes","Much kinder","I think so"],"affirm":"When everyone can feel freely, no one carries it alone.","relearn":"Letting all genders feel openly makes things kinder for everyone.","persona":"any","source":"equality / emotions"},
  {"id":"fs-1041","cat":"feelings-strength","type":"reflect","hook":"Lensy: 'be a man' and 'be a lady' both tell you to hide things. Worth questioning?","prompt":"What do you think?","options":["Yes","Worth questioning","Good point"],"affirm":"Both scripts box people in; questioning them frees everyone.","relearn":"'Be a man' and 'be a lady' both pressure people to hide feelings.","persona":"any","source":"emotions / gender"},
  {"id":"fs-1042","cat":"feelings-strength","type":"spot","hook":"A cartoon scene. Spot what's stereotyped.","scene":[{"id":"a","text":"The hero boy is told \"big boys don't cry\" after he gets hurt","trick":true},{"id":"b","text":"The girl is only allowed to look pretty and worried","trick":true},{"id":"c","text":"There's a tall castle in the background","trick":false},{"id":"d","text":"A friend brings the hero some water","trick":false},{"id":"e","text":"It's a sunny morning","trick":false}],"why":"'Big boys don't cry' and 'girls just look pretty' are stereotypes, not truths.","relearn":"Cartoons often stereotype boys as tough and girls as pretty; spot it.","persona":"any","source":"media literacy / emotions"},
  {"id":"fs-1043","cat":"feelings-strength","type":"spot","hook":"A school skit. Spot what's stereotyped.","scene":[{"id":"a","text":"The girl playing captain is told she's 'too emotional to lead'","trick":true},{"id":"b","text":"A boy who cries on stage is laughed at by the script","trick":true},{"id":"c","text":"The skit is set in a classroom","trick":false},{"id":"d","text":"There's a whistle for the match scene","trick":false},{"id":"e","text":"The teacher claps at the end","trick":false}],"why":"Mocking a boy's tears and doubting a girl leader are both stereotypes.","relearn":"Stereotypes say girls can't lead and boys can't cry; spot both.","persona":"any","source":"media literacy / emotions"},
  {"id":"fs-1044","cat":"feelings-strength","type":"spot","hook":"A greeting card aisle. Spot what's stereotyped.","scene":[{"id":"a","text":"\"For a brave boy who never cries\"","trick":true},{"id":"b","text":"\"For a calm, sweet girl who never gets cross\"","trick":true},{"id":"c","text":"\"Happy birthday!\"","trick":false},{"id":"d","text":"A picture of a cake","trick":false},{"id":"e","text":"A pack of colourful balloons","trick":false}],"why":"Cards that say boys can't cry and girls can't be cross box kids into false rules.","relearn":"Cards often stereotype boys as never crying, girls as never angry; spot it.","persona":"any","source":"media literacy / products"},
  {"id":"fs-1045","cat":"feelings-strength","type":"spot","hook":"A film fight scene. Spot what's stereotyped.","scene":[{"id":"a","text":"The hero says \"real men feel no fear\" before the fight","trick":true},{"id":"b","text":"The girl is told to wait quietly and not 'fuss'","trick":true},{"id":"c","text":"There's loud background music","trick":false},{"id":"d","text":"The fight happens at night","trick":false},{"id":"e","text":"A crowd is watching","trick":false}],"why":"'Real men feel no fear' and 'girls shouldn't fuss' are stereotypes, not facts.","relearn":"Films stereotype men as fearless and girls as silent; spot it.","persona":"any","source":"media literacy / film"},
  {"id":"fs-1046","cat":"feelings-strength","type":"spot","hook":"A sports ad. Spot what's stereotyped.","scene":[{"id":"a","text":"\"Champions don't show weakness\" over a boy hiding pain","trick":true},{"id":"b","text":"A girl athlete is shown only smiling, never competing hard","trick":true},{"id":"c","text":"\"New running shoes\"","trick":false},{"id":"d","text":"There's a stadium track","trick":false},{"id":"e","text":"A stopwatch on screen","trick":false}],"why":"Hiding pain isn't strength, and girls compete hard too; both are stereotypes.","relearn":"Ads stereotype boys as hiding pain and girls as just smiling; spot it.","persona":"any","source":"media literacy / sport"},
  {"id":"fs-1047","cat":"feelings-strength","type":"spot","hook":"A storybook page. Spot what's stereotyped.","scene":[{"id":"a","text":"The prince is brave; the princess only waits and worries","trick":true},{"id":"b","text":"The prince is teased for hugging his friend goodbye","trick":true},{"id":"c","text":"They live near a forest","trick":false},{"id":"d","text":"There's a friendly dog in the story","trick":false},{"id":"e","text":"The book has a blue cover","trick":false}],"why":"Brave-prince/worried-princess and teasing a hug are both old stereotypes.","relearn":"Books stereotype boys as brave-only and mock warmth; spot it.","persona":"any","source":"media literacy / books"},
  {"id":"fs-1048","cat":"feelings-strength","type":"spot","hook":"A TV family drama. Spot what's stereotyped.","scene":[{"id":"a","text":"The son is told \"men of this house don't break down\"","trick":true},{"id":"b","text":"The daughter is praised only for being quiet and sweet","trick":true},{"id":"c","text":"They're having dinner together","trick":false},{"id":"d","text":"There's a ceiling fan running","trick":false},{"id":"e","text":"A neighbour drops by","trick":false}],"why":"'Men don't break down' and 'be quiet and sweet' are scripts, not truths.","relearn":"Dramas stereotype sons as stoic and daughters as quiet; spot it.","persona":"any","source":"media literacy / film"},
  {"id":"fs-1049","cat":"feelings-strength","type":"spot","hook":"A coaching advert. Spot what's stereotyped.","scene":[{"id":"a","text":"\"Toughen up your son; tears won't get him ahead\"","trick":true},{"id":"b","text":"\"Keep your daughter calm and agreeable\"","trick":true},{"id":"c","text":"\"Classes from Monday\"","trick":false},{"id":"d","text":"A photo of a chalkboard","trick":false},{"id":"e","text":"The centre's address line","trick":false}],"why":"Telling sons to hide tears and daughters to stay agreeable are stereotypes.","relearn":"Ads stereotype sons as tearless and daughters as agreeable; spot it.","persona":"any","source":"media literacy / ads"},
  {"id":"fs-1050","cat":"feelings-strength","type":"match","hook":"Match the feeling-myth to its fair flip.","pairs":[{"left":"\"Boys don't cry\"","right":"Everyone cries; it's healthy"},{"left":"\"Girls can't be angry\"","right":"Anger is okay for any gender"},{"left":"\"Real men feel no fear\"","right":"Admitting fear is brave too"},{"left":"\"Asking help is weak\"","right":"Help-seeking is a strength"},{"left":"\"Girls are too emotional to lead\"","right":"Empathy makes a better leader"}],"relearn":"Each feeling-myth has a fair flip; no feeling belongs to one gender.","persona":"any","source":"emotions / gender"},
  {"id":"fs-1051","cat":"feelings-strength","type":"match","hook":"Match the situation to the kind, fair response.","pairs":[{"left":"A boy cries after a loss","right":"\"It's okay, you cared\""},{"left":"A girl gets angry at unfairness","right":"\"Your anger makes sense\""},{"left":"A friend is scared to speak","right":"\"Saying you're scared is brave\""},{"left":"A captain feels nervous","right":"\"Nerves mean you care\""},{"left":"A mate won't ask for help","right":"\"Asking is the smart move\""}],"relearn":"Kind responses honour real feelings instead of shaming them.","persona":"any","source":"emotions / care"},
  {"id":"fs-1052","cat":"feelings-strength","type":"match","hook":"Match the feeling to what it can quietly tell you.","pairs":[{"left":"Anger","right":"Something feels unfair"},{"left":"Fear","right":"Be careful, this matters"},{"left":"Sadness","right":"You've lost something you value"},{"left":"Nerves","right":"You care about doing well"},{"left":"Loneliness","right":"You'd like to feel connected"}],"relearn":"Feelings are signals for everyone, whatever your gender.","persona":"any","source":"emotions / awareness"},
  {"id":"fs-1053","cat":"feelings-strength","type":"match","hook":"Match the strength to who can have it.","pairs":[{"left":"Lifting heavy things","right":"Any gender, with training"},{"left":"Staying calm under pressure","right":"Any gender, with practice"},{"left":"Comforting a friend","right":"Any gender, with care"},{"left":"Leading a team","right":"Any gender, with skill"},{"left":"Speaking up bravely","right":"Any gender, with courage"}],"relearn":"Every kind of strength is open to every gender.","persona":"any","source":"strength / gender"},
  {"id":"fs-1054","cat":"feelings-strength","type":"match","hook":"Match the 'man up' line to a fairer one.","pairs":[{"left":"\"Man up\"","right":"\"Feel it; that's human\""},{"left":"\"Don't be a girl about it\"","right":"\"Feelings aren't a gender\""},{"left":"\"Toughen up\"","right":"\"It's okay to find this hard\""},{"left":"\"Stop whining\"","right":"\"Tell me what's wrong\""},{"left":"\"Boys don't break down\"","right":"\"Anyone can break down sometimes\""}],"relearn":"Each harsh 'man up' line has a kinder, fairer flip.","persona":"Aarav","source":"masculinity / language"},
  {"id":"fs-1055","cat":"feelings-strength","type":"match","hook":"Match the leadership strength to its real Indian example.","pairs":[{"left":"Staying calm under huge pressure","right":"A woman captaining India in cricket"},{"left":"Courage despite fear","right":"Mary Kom in the boxing ring"},{"left":"Curiosity and grit","right":"Kalpana Chawla reaching space"},{"left":"Caring about your team","right":"A coach who checks on players"},{"left":"Speaking up for fairness","right":"A student leader raising an issue"}],"relearn":"Real Indian role models show emotional strengths in leadership.","persona":"any","source":"leadership / role models"},
  {"id":"fs-1056","cat":"feelings-strength","type":"match","hook":"Match the comforting line to the friend who needs it.","pairs":[{"left":"Friend crying after a loss","right":"\"You played your heart out\""},{"left":"Friend scared of a test","right":"\"We'll prepare together\""},{"left":"Friend angry at being teased","right":"\"That wasn't fair on you\""},{"left":"Friend nervous before a speech","right":"\"You'll be great; breathe\""},{"left":"Friend feeling left out","right":"\"Come sit with us\""}],"relearn":"Comforting friends well is a skill any kid can grow.","persona":"any","source":"emotions / care"},
  {"id":"fs-1057","cat":"feelings-strength","type":"match","hook":"Match the false 'rule' to the fair truth that flips it.","pairs":[{"left":"\"Boys must never cry\"","right":"Tears are healthy for anyone"},{"left":"\"Girls must always be sweet\"","right":"Girls can speak up and disagree"},{"left":"\"Boys must hide all fear\"","right":"Admitting fear is brave too"},{"left":"\"Girls must not get angry\"","right":"Anger is okay for any gender"},{"left":"\"Boys must sort it out alone\"","right":"Asking for help is smart"}],"relearn":"These rules box in both boys and girls; each has a fair flip.","persona":"any","source":"emotions / gender"},
  {"id":"fs-1058","cat":"feelings-strength","type":"sort","hook":"Sort: a healthy way to handle a feeling, or an uh-oh way?","items":[{"id":"a","text":"Telling a friend you feel low"},{"id":"b","text":"Crying when you're sad"},{"id":"c","text":"Bottling everything up till you burst"},{"id":"d","text":"Asking a trusted adult for help"},{"id":"e","text":"Pretending you feel nothing for days"},{"id":"f","text":"Taking a few deep breaths"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"uhoh","label":"Uh-oh","valence":"uhoh"}],"key":{"a":"healthy","b":"healthy","c":"uhoh","d":"healthy","e":"uhoh","f":"healthy"},"relearn":"Letting feelings out healthily beats bottling them up, for anyone.","persona":"any","source":"emotions / coping"},
  {"id":"fs-1059","cat":"feelings-strength","type":"sort","hook":"Sort: a true thing about feelings, or a stereotype?","items":[{"id":"a","text":"\"Everyone feels fear sometimes\""},{"id":"b","text":"\"Boys don't really feel sad\""},{"id":"c","text":"\"Girls are too emotional to lead\""},{"id":"d","text":"\"Crying can help you feel better\""},{"id":"e","text":"\"Anger is okay for any gender\""},{"id":"f","text":"\"Real men never need help\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"stereo","label":"Stereotype","valence":"neg"}],"key":{"a":"true","b":"stereo","c":"stereo","d":"true","e":"true","f":"stereo"},"relearn":"Stereotypes about who can feel what aren't facts.","persona":"any","source":"emotions / concept"},
  {"id":"fs-1060","cat":"feelings-strength","type":"sort","hook":"Sort: a feeling anyone can have, or a stereotype about who's allowed to feel it?","items":[{"id":"a","text":"A boy feeling afraid"},{"id":"b","text":"\"Only girls get scared\""},{"id":"c","text":"A girl feeling proud and loud"},{"id":"d","text":"\"Boys shouldn't feel like crying\""},{"id":"e","text":"A boy feeling gentle and caring"},{"id":"f","text":"\"Anger isn't for girls\""}],"bins":[{"id":"feeling","label":"A feeling anyone can have","valence":"pos"},{"id":"stereo","label":"Stereotype","valence":"neg"}],"key":{"a":"feeling","b":"stereo","c":"feeling","d":"stereo","e":"feeling","f":"stereo"},"relearn":"Every feeling here is open to every gender; the 'only/shouldn't' rules are stereotypes.","persona":"any","source":"emotions / gender"},
  {"id":"fs-1061","cat":"feelings-strength","type":"sort","hook":"Sort: a kind response to feelings, or one that shames?","items":[{"id":"a","text":"\"It's okay to cry\""},{"id":"b","text":"\"Stop being such a baby\""},{"id":"c","text":"\"Tell me what's wrong\""},{"id":"d","text":"\"Don't be a girl about it\""},{"id":"e","text":"\"Your anger makes sense\""},{"id":"f","text":"\"Real men don't whine\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"shames","label":"Shames","valence":"neg"}],"key":{"a":"kind","b":"shames","c":"kind","d":"shames","e":"kind","f":"shames"},"relearn":"Kind responses honour feelings; shaming ones bury them.","persona":"any","source":"emotions / care"},
  {"id":"fs-1062","cat":"feelings-strength","type":"sort","hook":"Sort: a real kind of strength, or a fake 'rule' about strength?","items":[{"id":"a","text":"Staying calm and helping in a crisis"},{"id":"b","text":"\"Strength means never showing feelings\""},{"id":"c","text":"Owning up when you're wrong"},{"id":"d","text":"\"Strong people never ask for help\""},{"id":"e","text":"Comforting a friend who's upset"},{"id":"f","text":"\"Real strength means hiding fear\""}],"bins":[{"id":"real","label":"Real strength","valence":"pos"},{"id":"fake","label":"Fake rule","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Real strength includes feeling, owning up and asking for help.","persona":"any","source":"strength / concept"},
  {"id":"fs-1063","cat":"feelings-strength","type":"sort","hook":"Sort: speaking up kindly about feelings, or staying silent?","items":[{"id":"a","text":"\"It's okay to feel scared, na?\""},{"id":"b","text":"Laughing along when a boy is mocked for crying"},{"id":"c","text":"\"She's not bossy, she's leading\""},{"id":"d","text":"Saying nothing when a girl is told to 'be sweet'"},{"id":"e","text":"\"Asking for help is smart\""},{"id":"f","text":"Letting 'man up' slide without a word"}],"bins":[{"id":"speakup","label":"Speak up","valence":"tell"},{"id":"silent","label":"Stay silent","valence":"uhoh"}],"key":{"a":"speakup","b":"silent","c":"speakup","d":"silent","e":"speakup","f":"silent"},"relearn":"Speaking up kindly for feelings beats staying silent.","persona":"any","source":"emotions / voice"},
  {"id":"fs-1064","cat":"feelings-strength","type":"sort","hook":"Sort: a good way to support an upset friend, or one to avoid?","items":[{"id":"a","text":"Listening without judging"},{"id":"b","text":"Telling them to 'just get over it'"},{"id":"c","text":"Asking if they want company"},{"id":"d","text":"Teasing them for being sensitive"},{"id":"e","text":"Sitting with them quietly"},{"id":"f","text":"Telling everyone what they shared"}],"bins":[{"id":"good","label":"Supportive","valence":"pos"},{"id":"avoid","label":"Avoid","valence":"neg"}],"key":{"a":"good","b":"avoid","c":"good","d":"avoid","e":"good","f":"avoid"},"relearn":"Supporting a friend means listening, not teasing or telling.","persona":"any","source":"emotions / care"},
  {"id":"fs-1065","cat":"feelings-strength","type":"sort","hook":"Sort: which 'be a man'/'be a lady' lines push people to hide feelings?","items":[{"id":"a","text":"\"Boys don't cry\""},{"id":"b","text":"\"Tell me how you really feel\""},{"id":"c","text":"\"Good girls don't get angry\""},{"id":"d","text":"\"It's okay to be upset\""},{"id":"e","text":"\"Man up and hide it\""},{"id":"f","text":"\"Your feelings are valid\""}],"bins":[{"id":"hide","label":"Pushes hiding","valence":"neg"},{"id":"open","label":"Invites feeling","valence":"pos"}],"key":{"a":"hide","b":"open","c":"hide","d":"open","e":"hide","f":"open"},"relearn":"'Be a man'/'be a lady' lines pressure people to hide real feelings.","persona":"any","source":"emotions / gender"},
  {"id":"fs-1080","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls can't play cricket.\"","myth":{"un":"Girls can't play cricket.","re":"Girls play cricket brilliantly; a woman captains India.","why":"Skill on the pitch comes from practice, not gender."},"relearn":"Flip 'girls can't play cricket' to 'girls captain India'.","persona":"Diya","source":"flip / sport"},
  {"id":"fs-1082","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys can't braid hair or help with a baby.\"","myth":{"un":"Boys can't braid hair or look after a baby.","re":"Boys learn to braid, feed and soothe a baby just fine.","why":"Caring is a skill you practise, not a gender."},"relearn":"Flip 'boys can't care for a baby' to 'boys learn caring too'.","persona":"Rohit","source":"flip / caregiving"},
  {"id":"fs-1083","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Dads can't change nappies.\"","myth":{"un":"Dads can't change nappies.","re":"Dads change nappies, do night feeds and burp the baby.","why":"Hands learn the job; care isn't owned by one parent."},"relearn":"Flip 'dads can't change nappies' to 'dads do the baby care'.","persona":"Rohit","source":"flip / caregiving"},
  {"id":"fs-1084","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"The class monitor should be a boy.\"","myth":{"un":"The class monitor should always be a boy.","re":"The fairest, most organised kid leads, any gender.","why":"Leadership is care plus vision, not a boy badge."},"relearn":"Flip 'monitor should be a boy' to 'the best leader leads'.","persona":"any","source":"flip / leadership"},
  {"id":"fs-1085","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls who lead are bossy.\"","myth":{"un":"A girl who takes charge is just bossy.","re":"A girl who takes charge is a leader, plain and simple.","why":"We call the same behaviour 'leading' in a boy."},"relearn":"Flip 'she's bossy' to 'she's a leader'.","persona":"Diya","source":"flip / leadership"},
  {"id":"fs-1086","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"A girl's dream should fit at home.\"","myth":{"un":"A girl should keep her dreams small and close to home.","re":"A girl can dream as big as the sky, even space.","why":"Kalpana Chawla flew to space; no dream is off-limits."},"relearn":"Flip 'keep her dreams small' to 'she can dream as big as space'.","persona":"Diya","source":"flip / aspiration"},
  {"id":"fs-1087","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls shouldn't travel far to study.\"","myth":{"un":"Girls shouldn't go far away to study or work.","re":"Girls go wherever their studies and work take them.","why":"A girl belongs anywhere she chooses to be."},"relearn":"Flip 'girls shouldn't go far' to 'girls go wherever they choose'.","persona":"Diya","source":"flip / aspiration"},
  {"id":"fs-1088","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Cooking at home is mum's job.\"","myth":{"un":"Cooking for the family is the mother's job.","re":"Everyone in the house can cook and share the meals.","why":"A home runs happier when the kitchen is shared."},"relearn":"Flip 'cooking is mum's job' to 'everyone shares the kitchen'.","persona":"Rohit","source":"flip / chores"},
  {"id":"fs-1089","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Sweeping and mopping is girls' work.\"","myth":{"un":"Sweeping and mopping is girls' work.","re":"Cleaning the home is everyone's work to share.","why":"A fair home shares chores between all who live there."},"relearn":"Flip 'cleaning is girls' work' to 'chores are shared by all'.","persona":"any","source":"flip / chores"},
  {"id":"fs-1090","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls are weak at maths.\"","myth":{"un":"Girls are naturally weak at maths.","re":"Girls do brilliantly at maths and science.","why":"Ability grows from effort, not from being a girl."},"relearn":"Flip 'girls are weak at maths' to 'girls do brilliantly at maths'.","persona":"Diya","source":"flip / ability"},
  {"id":"fs-1092","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"A girl should care most about being pretty.\"","myth":{"un":"The most important thing for a girl is looking pretty.","re":"A girl matters for her ideas, courage and kindness.","why":"Worth isn't a beauty score you have to win."},"relearn":"Flip 'pretty matters most' to 'her ideas and courage matter'.","persona":"Diya","source":"flip / worth"},
  {"id":"fs-1094","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys who paint or dance are weird.\"","myth":{"un":"Boys who like painting or dancing are weird.","re":"Boys who paint and dance are just enjoying their thing.","why":"An interest has no gender; it's just something you love."},"relearn":"Flip 'art and dance are weird for boys' to 'any interest fits any kid'.","persona":"Aarav","source":"flip / interests"},
  {"id":"fs-1095","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls shouldn't like cars or building things.\"","myth":{"un":"Girls shouldn't be into cars or building things.","re":"Girls love engines, blocks and building, no problem.","why":"Curiosity about how things work has no gender."},"relearn":"Flip 'girls shouldn't build' to 'girls love building and engines'.","persona":"Diya","source":"flip / interests"},
  {"id":"fs-1096","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Real men don't cry.\"","myth":{"un":"Real men don't cry.","re":"Everyone cries; letting tears out is healthy, not weak.","why":"Bottling feelings up is strain, not strength."},"relearn":"Flip 'real men don't cry' to 'crying is healthy for everyone'.","persona":"Aarav","source":"flip / feelings"},
  {"id":"fs-1097","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys shouldn't admit they're scared.\"","myth":{"un":"Boys shouldn't admit when they're scared.","re":"Boys feel fear like anyone, and saying so is brave.","why":"Naming a feeling is braver than hiding it."},"relearn":"Flip 'boys can't be scared' to 'saying you're scared is brave'.","persona":"Aarav","source":"flip / feelings"},
  {"id":"fs-1098","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Don't throw like a girl.\"","myth":{"un":"'You throw like a girl' means you throw badly.","re":"Throwing 'like a girl' can mean fast, strong and skilled.","why":"Using a gender as an insult is the real stereotype."},"relearn":"Flip 'like a girl means weak' to 'like a girl means skilled'.","persona":"any","source":"flip / feelings"},
  {"id":"fs-1099","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls shouldn't get angry.\"","myth":{"un":"Girls shouldn't get angry; they should stay sweet.","re":"Girls are allowed to feel and show anger, fairly.","why":"Asking for only 'sweet' silences real feelings."},"relearn":"Flip 'girls shouldn't be angry' to 'girls can feel anger too'.","persona":"Diya","source":"flip / feelings"},
  {"id":"fs-1100","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls should wear only soft, girly colours.\"","myth":{"un":"Girls should wear only soft, girly colours.","re":"A girl can wear any colour she likes, bold or soft.","why":"There's no such thing as a 'girl' colour; the rule was made up."},"relearn":"Flip 'girls wear only girly colours' to 'a girl can wear any colour'.","persona":"any","source":"flip / looks"},
  {"id":"fs-1101","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys can't have long hair.\"","myth":{"un":"Boys can't have long hair.","re":"Boys can wear their hair long or short, their choice.","why":"Across history all genders wore long hair; it's just style."},"relearn":"Flip 'boys can't have long hair' to 'hair length is your choice'.","persona":"any","source":"flip / looks"},
  {"id":"fs-1102","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls should only wear dresses.\"","myth":{"un":"Girls should only wear dresses, not trousers.","re":"Girls wear trousers, shorts or a dress, whatever's comfy.","why":"Clothes are about comfort and choice, not rules."},"relearn":"Flip 'girls only wear dresses' to 'clothes are about comfort'.","persona":"Diya","source":"flip / looks"},
  {"id":"fs-1103","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys shouldn't play with kitchen sets.\"","myth":{"un":"Boys shouldn't play with kitchen sets.","re":"A boy can play cooking and pretend just like anyone.","why":"Pretend cooking builds skills every child can use at home."},"relearn":"Flip 'boys shouldn't play kitchen' to 'a boy can play cooking too'.","persona":"any","source":"flip / looks"},
  {"id":"fs-1104","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Driving big vehicles is a man's job.\"","myth":{"un":"Only men can drive buses, trucks and big vehicles.","re":"Women drive scooters, buses, trucks and planes too.","why":"Driving is a skill you train for, not a gender."},"relearn":"Flip 'driving is a man's job' to 'driving is a skill anyone learns'.","persona":"any","source":"flip / jobs"},
  {"id":"fs-1105","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Nursing is a woman's job.\"","myth":{"un":"Nursing is a job only for women.","re":"Men are nurses too; care work isn't owned by one gender.","why":"Looking after sick people is a skill, not a girl thing."},"relearn":"Flip 'nursing is for women' to 'men are caring nurses too'.","persona":"any","source":"flip / jobs"},
  {"id":"fs-1107","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Driving a train is a man's job.\"","myth":{"un":"Driving a train is a man's job.","re":"Women drive trains too; India has women loco pilots.","why":"Running an engine needs skill and focus, not a gender."},"relearn":"Flip 'driving a train is a man's job' to 'women drive trains too'.","persona":"any","source":"flip / jobs"},
  {"id":"fs-1108","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls can't be in the army.\"","myth":{"un":"Girls can't be soldiers or join the army.","re":"Women serve as soldiers and officers in India's forces.","why":"Courage and training make a soldier, not gender."},"relearn":"Flip 'girls can't be soldiers' to 'women serve as soldiers'.","persona":"Diya","source":"flip / jobs"},
  {"id":"fs-1109","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boxing is too rough for girls.\"","myth":{"un":"Boxing is too rough for girls.","re":"Girls box and win medals; Mary Kom is a world champion.","why":"Toughness is trained in the ring, not handed out by gender."},"relearn":"Flip 'boxing is too rough for girls' to 'girls box and win'.","persona":"Diya","source":"flip / sport"},
  {"id":"fs-1110","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"A stay-at-home parent must be the mum.\"","myth":{"un":"The parent who stays home must be the mum.","re":"A dad can be the stay-at-home parent too.","why":"Who stays home is the family's choice, not a rule."},"relearn":"Flip 'home parent must be mum' to 'a dad can stay home too'.","persona":"Rohit","source":"flip / caregiving"},
  {"id":"fs-1111","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Boys should toughen up alone.\"","myth":{"un":"A real boy sorts his problems out alone.","re":"Asking for help when you're stuck is smart and brave.","why":"'Tough it out alone' is itself a harmful stereotype."},"relearn":"Flip 'boys cope alone' to 'asking for help is brave'.","persona":"Aarav","source":"flip / feelings"},
  {"id":"fs-1114","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Cooking as a job is for women.\"","myth":{"un":"Being a cook or chef is a job for women.","re":"Many top chefs are men; cooking is a craft for anyone.","why":"A great dish comes from skill, not the cook's gender."},"relearn":"Flip 'chefs should be women' to 'cooking is a craft for anyone'.","persona":"Rohit","source":"flip / jobs"},
  {"id":"fs-1115","cat":"flip-it","type":"strike-rewrite","hook":"Flip it: \"Girls should let the boys win to keep peace.\"","myth":{"un":"Girls should let the boys win to keep the peace.","re":"Everyone plays their best; a fair game is the fun part.","why":"Letting someone win on purpose isn't kindness, it's unfair."},"relearn":"Flip 'let the boys win' to 'everyone plays their best'.","persona":"Diya","source":"flip / sport"},
  {"id":"fs-1120","cat":"flip-it","type":"branch","hook":"You're making a poster: 'Future jobs'. Your first sketch shows only men.","options":[{"text":"Redraw it with women pilots, men nurses and mixed teams","consequence":"Your poster shows every job open to everyone.","outcome":"creative","best":true},{"text":"Leave the men-only version","consequence":"Flipping it to a mixed cast shows jobs aren't gendered."}],"debrief":"Remaking a one-sided poster into a fair one is flipping the script.","relearn":"You can redraw media so every job looks open to everyone.","persona":"any","source":"flip / media-making"},
  {"id":"fs-1121","cat":"flip-it","type":"branch","hook":"Your group is filming a skit. The script has the girl only waiting to be saved.","options":[{"text":"Rewrite so she solves the problem herself","consequence":"Your skit gives her a real, active role.","outcome":"creative","best":true},{"text":"Keep her just waiting","consequence":"Giving her something to do flips the helpless-girl trope."}],"debrief":"Stories don't have to make girls helpless and boys the heroes.","relearn":"You can rewrite a story so girls act, not just wait.","persona":"any","source":"flip / storytelling"},
  {"id":"fs-1122","cat":"flip-it","type":"branch","hook":"You're writing a birthday-party invite and start to split games 'for boys' and 'for girls'.","options":[{"text":"List all the games as open to every guest","consequence":"Every kid gets to pick whatever they enjoy.","outcome":"creative","best":true},{"text":"Keep the boys/girls split","consequence":"One open list flips the made-up party-theme divide."}],"debrief":"Splitting party games by gender is a made-up divide you can flip.","relearn":"You can plan a party where every game is open to everyone.","persona":"any","source":"flip / media-making"},
  {"id":"fs-1123","cat":"flip-it","type":"branch","hook":"You're designing a comic hero and your default is a strong, silent boy.","options":[{"text":"Give him real feelings he talks about, and add a brave girl too","consequence":"Your heroes feel real and break the tired mould.","outcome":"creative","best":true},{"text":"Keep the strong-silent default","consequence":"Letting heroes feel, and adding a girl, flips the script."}],"debrief":"Heroes can have feelings and come in any gender.","relearn":"You can design heroes who feel, of any gender.","persona":"Aarav","source":"flip / storytelling"},
  {"id":"fs-1124","cat":"flip-it","type":"branch","hook":"A song you like has a line saying a girl's only goal is to look pretty.","options":[{"text":"Rewrite the line about her dreams and skills","consequence":"Your version sings about who she is, not just her looks.","outcome":"creative","best":true},{"text":"Sing it as-is","consequence":"Rewriting the line flips the 'looks are everything' message."}],"debrief":"You can flip a lyric that says looks are all a girl is for.","relearn":"You can rewrite lyrics so a girl is more than her looks.","persona":"Diya","source":"flip / media-making"},
  {"id":"fs-1125","cat":"flip-it","type":"branch","hook":"You're labelling a class display: 'Strong = boys, Pretty = girls'.","options":[{"text":"Change it to 'Everyone can be strong, kind and creative'","consequence":"Your display lets every kid be all of those.","outcome":"creative","best":true},{"text":"Leave the boxed labels","consequence":"One open label flips the boys-strong, girls-pretty box."}],"debrief":"Greeting-card labels box kids in; you can flip them open.","relearn":"You can relabel a display so every trait fits every kid.","persona":"any","source":"flip / media-making"},
  {"id":"fs-1126","cat":"flip-it","type":"branch","hook":"You're picking a read-aloud and the only one left makes mum cook while dad reads the paper.","options":[{"text":"Read it, then ask the class to flip who does what","consequence":"The class reimagines a home where chores are shared.","outcome":"creative","best":true},{"text":"Read it without comment","consequence":"Asking the class to flip it turns the book into a lesson."}],"debrief":"Even an old book becomes a flip if you question its script together.","relearn":"You can use an old story to practise flipping the script.","persona":"any","source":"flip / storytelling"},
  {"id":"fs-1127","cat":"flip-it","type":"branch","hook":"You're picking emojis for a chat and reach for cooking-mum, briefcase-dad.","options":[{"text":"Pick a mix: dad cooking, mum with a briefcase, both doing both","consequence":"Your emojis show parents sharing every role.","outcome":"creative","best":true},{"text":"Use the default mum-cooks, dad-earns set","consequence":"Mixing them flips the 'mums care, dads earn' default."}],"debrief":"Even emoji defaults stereotype; you can flip what you pick.","relearn":"You can pick emojis that show parents sharing roles.","persona":"any","source":"flip / media-making"},
  {"id":"fs-1128","cat":"flip-it","type":"role-play","hook":"A classmate says \"baking is girly, drop out of the cooking club\".","setup":"Flip the script. Say:","yourLine":[{"text":"\"Cooking's a skill, and some top chefs are men, I'm staying.\"","best":true},{"text":"\"Maybe you're right, I'll quit.\""}],"relearn":"You can flip 'cooking is girly' on the spot, kindly.","persona":"Aarav","source":"flip / voice"},
  {"id":"fs-1129","cat":"flip-it","type":"role-play","hook":"Someone tells your sister \"girls can't fix bikes, ask a boy\".","setup":"Flip it for her. Say:","yourLine":[{"text":"\"She's brilliant with tools, watch her sort it.\"","best":true},{"text":"\"Yeah, better get a boy.\""}],"relearn":"You can flip 'girls can't fix things' for someone else.","persona":"any","source":"flip / voice"},
  {"id":"fs-1130","cat":"flip-it","type":"role-play","hook":"A friend laughs \"only girls cry over a sad film\".","setup":"Flip it calmly. Say:","yourLine":[{"text":"\"Everyone cries at sad bits, that's just being human.\"","best":true},{"text":"\"Ha, yeah, so soft.\""}],"relearn":"You can flip 'only girls cry' into 'everyone feels'.","persona":"Aarav","source":"flip / voice"},
  {"id":"fs-1131","cat":"flip-it","type":"role-play","hook":"At play your team says \"girls go in goal, that's the easy spot\".","setup":"Flip it on the pitch. Say:","yourLine":[{"text":"\"Let's pick by who plays best, not by gender.\"","best":true},{"text":"\"Fine, I'll just stand in goal.\""}],"relearn":"You can flip 'girls get the easy spot' to 'pick by skill'.","persona":"Diya","source":"flip / voice"},
  {"id":"fs-1132","cat":"flip-it","type":"role-play","hook":"A cousin says \"boys shouldn't dance on stage\".","setup":"Flip it kindly. Say:","yourLine":[{"text":"\"Loads of brilliant dancers are boys, I love it up there.\"","best":true},{"text":"\"Okay, I won't go up.\""}],"relearn":"You can flip 'boys shouldn't dance' with confidence.","persona":"Aarav","source":"flip / voice"},
  {"id":"fs-1133","cat":"flip-it","type":"role-play","hook":"A shopkeeper says \"that toy car is for boys, pick a doll instead\".","setup":"Flip it for yourself. Say:","yourLine":[{"text":"\"Toys aren't boy or girl, I'll take the car, thanks.\"","best":true},{"text":"\"Oh okay, I'll take the doll.\""}],"relearn":"You can flip 'that toy is for boys' at the shop.","persona":"Diya","source":"flip / voice"},
  {"id":"fs-1134","cat":"flip-it","type":"role-play","hook":"A teammate jeers \"you run like a girl\" as an insult.","setup":"Flip the insult. Say:","yourLine":[{"text":"\"Girls run fast and strong, so thanks for that.\"","best":true},{"text":"\"Sorry, I'll try harder.\""}],"relearn":"You can flip 'like a girl' from insult to compliment.","persona":"any","source":"flip / voice"},
  {"id":"fs-1135","cat":"flip-it","type":"role-play","hook":"Your aunt says \"don't make him help in the kitchen, that's not for boys\".","setup":"Flip it gently. Say:","yourLine":[{"text":"\"I like helping, na, and cooking's a great skill to have.\"","best":true},{"text":"\"Okay, I'll go play instead.\""}],"relearn":"You can flip 'kitchen's not for boys' kindly with elders.","persona":"Aarav","source":"flip / voice"},
  {"id":"fs-1136","cat":"flip-it","type":"spot","hook":"You're checking your own 'jobs of the future' drawing for sneaky defaults. Spot them.","scene":[{"id":"a","text":"Every pilot you drew is a man","trick":true},{"id":"b","text":"Your scientist team is mixed and fair","trick":false},{"id":"c","text":"The only nurse is a woman","trick":true},{"id":"d","text":"A girl is shown driving the bus","trick":false},{"id":"e","text":"A dad is shown caring for the baby","trick":false}],"why":"Even when flipping, old defaults sneak back; check your own work.","relearn":"Check even your own drawing for stereotypes that slip in.","persona":"any","source":"flip / self-check"},
  {"id":"fs-1137","cat":"flip-it","type":"spot","hook":"You rewrote a story to be fairer. Spot where the old script crept back.","scene":[{"id":"a","text":"The boy is still the only one who solves things","trick":true},{"id":"b","text":"The girl now leads the rescue too","trick":false},{"id":"c","text":"Both kids show fear and courage","trick":false},{"id":"d","text":"The crying character is still only the girl","trick":true},{"id":"e","text":"A dad is shown cooking dinner","trick":false}],"why":"Flipping is a muscle; catching a sneaky default makes it stronger.","relearn":"Even a rewrite can hide an old script; spot and re-flip it.","persona":"any","source":"flip / self-check"},
  {"id":"fs-1138","cat":"flip-it","type":"spot","hook":"In your remixed advert, spot the lines that still carry a stereotype.","scene":[{"id":"a","text":"Only mum is shown scrubbing the floor","trick":true},{"id":"b","text":"Dad and the kids tidy up together","trick":false},{"id":"c","text":"'For real men only' is stamped on the car","trick":true},{"id":"d","text":"A girl is shown winning the race","trick":false},{"id":"e","text":"Everyone in the kitchen shares the cooking","trick":false}],"why":"A remix isn't fair until the leftover stereotype lines are flipped too.","relearn":"Spot the stereotype lines that survived your remix and flip them.","persona":"any","source":"flip / self-check"},
  {"id":"fs-1139","cat":"flip-it","type":"spot","hook":"You flipped a sports report. Spot the bits still treating one gender as the 'real' one.","scene":[{"id":"a","text":"The women's match is called 'just a warm-up'","trick":true},{"id":"b","text":"Both teams get full, fair coverage","trick":false},{"id":"c","text":"The girl captain is named and praised","trick":false},{"id":"d","text":"Only the boys' scores are on the board","trick":true},{"id":"e","text":"A woman commentator calls the game","trick":false}],"why":"Fair coverage treats every team as a real game, not a sideshow.","relearn":"Spot where a report sidelines women's sport, and flip it.","persona":"any","source":"flip / self-check"},
  {"id":"fs-1140","cat":"flip-it","type":"spot","hook":"You redrew a toy-shop flyer. Spot the panels still split by gender.","scene":[{"id":"a","text":"A 'pink girls' aisle' label is still on the dolls","trick":true},{"id":"b","text":"Toys are grouped by what they do, not gender","trick":false},{"id":"c","text":"A 'blue boys only' sign sits over the blocks","trick":true},{"id":"d","text":"A girl and a boy build the same robot","trick":false},{"id":"e","text":"Every toy is open to every kid","trick":false}],"why":"Pink-girl, blue-boy aisles are a made-up divide to flip.","relearn":"Spot the gendered aisle labels and flip them open.","persona":"any","source":"flip / self-check"},
  {"id":"fs-1141","cat":"flip-it","type":"spot","hook":"You rewrote a school play. Spot the casting that kept the old script.","scene":[{"id":"a","text":"The leader role is still written for a boy only","trick":true},{"id":"b","text":"Any kid can audition for any part","trick":false},{"id":"c","text":"The brave explorer can be a girl","trick":false},{"id":"d","text":"The 'pretty, quiet' part is still girls only","trick":true},{"id":"e","text":"The caring nurse role is open to boys too","trick":false}],"why":"A fair script opens every role to every kid.","relearn":"Spot the parts your play locks by gender, and open them.","persona":"any","source":"flip / self-check"},
  {"id":"fs-1142","cat":"flip-it","type":"spot","hook":"You redesigned a cereal box. Spot the bits that still stereotype.","scene":[{"id":"a","text":"Only the boy is shown as 'strong and active'","trick":true},{"id":"b","text":"Kids of every gender play sport on the back","trick":false},{"id":"c","text":"The girl is only there to look pretty","trick":true},{"id":"d","text":"A dad is shown serving breakfast","trick":false},{"id":"e","text":"The puzzle is for every kid to try","trick":false}],"why":"A fair pack shows every kid active and capable, not boxed in.","relearn":"Spot the packaging that still boxes kids in, and flip it.","persona":"any","source":"flip / self-check"},
  {"id":"fs-1143","cat":"flip-it","type":"reflect","hook":"Lensy: when you flip a script, what's the very first step you take?","prompt":"What do you think?","options":["Spot the stereotype","Ask 'is this fair?'","Picture a fairer version"],"affirm":"Spotting it first is what lets you flip it; you noticed, that's the start.","relearn":"Flipping starts with spotting the stereotype first.","persona":"any","source":"reflect / process"},
  {"id":"fs-1144","cat":"flip-it","type":"reflect","hook":"Lensy: which flip do you most want to try out in real life?","prompt":"Pick one:","options":["Boys can cry","Girls can lead","Chores are shared"],"affirm":"Any of these is a brilliant flip to carry into your day; pick what fits.","relearn":"You can choose a real flip to practise this week.","persona":"any","source":"reflect / choice"},
  {"id":"fs-1145","cat":"flip-it","type":"reflect","hook":"Lensy: a flip you tried didn't land the first time. What now?","prompt":"What feels right?","options":["Try again later","Say it a kinder way","Ask a friend to help"],"affirm":"Every one of these keeps you going; a flip can take more than one go.","relearn":"A flip that doesn't land first time is worth a second try.","persona":"any","source":"reflect / persistence"},
  {"id":"fs-1146","cat":"flip-it","type":"reflect","hook":"Lensy: which of your own habits would you most like to check for old defaults?","prompt":"What comes to mind?","options":["Who I pick first","The words I use","The toys I assume"],"affirm":"Noticing your own defaults is brave; whatever you picked, that's real growth.","relearn":"Checking your own defaults is part of flipping the script.","persona":"any","source":"reflect / self-check"},
  {"id":"fs-1147","cat":"flip-it","type":"reflect","hook":"Lensy: who's someone you could help see a fairer script?","prompt":"Picture them:","options":["A younger cousin","A friend","Someone in my class"],"affirm":"Sharing a flip helps it spread; whoever you pictured is a great place to start.","relearn":"You can pass a fairer script on to someone else.","persona":"any","source":"reflect / sharing"},
  {"id":"fs-1148","cat":"flip-it","type":"reflect","hook":"Lensy: how does flipping a tired script make a story feel?","prompt":"What do you think?","options":["Fresher","Fairer","More like real life"],"affirm":"All true; a flipped story feels new and looks more like the real world.","relearn":"Flipping a script makes a story fresher and fairer.","persona":"any","source":"reflect / story"},
  {"id":"fs-1149","cat":"flip-it","type":"reflect","hook":"Lensy: what's a sign you've truly flipped a script, not just half-flipped it?","prompt":"What feels right?","options":["Every role is open","No one's boxed in","It works both ways"],"affirm":"Spot on; a real flip frees every gender, not just one direction.","relearn":"A true flip frees all genders, not only one side.","persona":"any","source":"reflect / check"},
  {"id":"fs-1150","cat":"flip-it","type":"match","hook":"Match each tired script to its fair flip.","pairs":[{"left":"Girls are bad at sports","right":"Girls are champions with practice"},{"left":"Boys can't mind a baby","right":"Boys make caring parents"},{"left":"Leaders are men","right":"Leaders are people of any gender"},{"left":"A girl's place is at home","right":"A girl belongs wherever she chooses"},{"left":"Real men don't do housework","right":"Fair partners share the chores"}],"relearn":"Every tired script has a fair flip you can name.","persona":"any","source":"flip / match"},
  {"id":"fs-1151","cat":"flip-it","type":"match","hook":"Match the stereotype to the truth that flips it.","pairs":[{"left":"Boys are naturally smarter","right":"Brains aren't 'boy' or 'girl'"},{"left":"Pretty matters most for girls","right":"Minds and kindness matter most"},{"left":"Boys who read are weird","right":"Any interest fits any kid"},{"left":"Girls can't be pilots","right":"Women fly planes every day"},{"left":"Nursing is women's work","right":"Men are caring nurses too"}],"relearn":"You can pair each stereotype with the truth that flips it.","persona":"any","source":"flip / match"},
  {"id":"fs-1152","cat":"flip-it","type":"match","hook":"Match each old line to the fair line that replaces it.","pairs":[{"left":"Boys don't cry","right":"Everyone cries; it's healthy"},{"left":"Girls shouldn't get angry","right":"Girls can feel anger too"},{"left":"Like a girl means weak","right":"Like a girl means skilled"},{"left":"Boys can't be scared","right":"Saying you're scared is brave"},{"left":"Toughen up alone","right":"Asking for help is smart"}],"relearn":"Each feelings myth has a fair line ready to flip it.","persona":"any","source":"flip / match"},
  {"id":"fs-1153","cat":"flip-it","type":"match","hook":"Match the made-up rule to what it really flips to.","pairs":[{"left":"Pink is for girls","right":"Every colour is for everyone"},{"left":"Boys can't grow long hair","right":"Hair length is personal choice"},{"left":"Girls only wear dresses","right":"Clothes are about comfort"},{"left":"Dolls are only for girls","right":"Dolls are for any kid"},{"left":"Driving big trucks is for men","right":"Driving is a skill anyone learns"}],"relearn":"Made-up rules about stuff all have a fair flip.","persona":"any","source":"flip / match"},
  {"id":"fs-1154","cat":"flip-it","type":"match","hook":"Match each real Indian example to the script it flips.","pairs":[{"left":"Kalpana Chawla in space","right":"Girls' dreams aren't small"},{"left":"Mary Kom boxing champion","right":"Sport isn't too rough for girls"},{"left":"A woman captaining India","right":"Girls can lead a team"},{"left":"Women pilots in India","right":"Flying isn't a man's job"},{"left":"A dad who cooks at home","right":"Cooking isn't 'women's work'"}],"relearn":"Real Indian examples flip tired scripts on their head.","persona":"any","source":"flip / match"},
  {"id":"fs-1155","cat":"flip-it","type":"match","hook":"Match each remix job to the stereotype it fixes.","pairs":[{"left":"Show the family cooking together","right":"Only mum cooks"},{"left":"Make either kid the hero","right":"Boys rescue, girls wait"},{"left":"Open every party game to all","right":"Games split by gender"},{"left":"Cast any kid as the leader","right":"Leaders must be boys"},{"left":"Cover both teams fairly","right":"Only men's sport is 'real'"}],"relearn":"Each remix has a clear stereotype it sets out to fix.","persona":"any","source":"flip / match"},
  {"id":"fs-1156","cat":"flip-it","type":"match","hook":"Match the praise word to the kid it's wrongly saved for, then flip it open.","pairs":[{"left":"Brave","right":"Wrongly saved for boys"},{"left":"Gentle","right":"Wrongly saved for girls"},{"left":"Clever","right":"Wrongly praised in boys"},{"left":"Pretty","right":"Wrongly praised in girls"},{"left":"Strong","right":"Belongs to every kid"}],"relearn":"Praise words get wrongly gendered; you can flip them open to all.","persona":"any","source":"flip / match"},
  {"id":"fs-1157","cat":"flip-it","type":"match","hook":"Match each 'who does it' job to the fair answer.","pairs":[{"left":"Who can be a scientist?","right":"Any gender"},{"left":"Who can cook dinner?","right":"Everyone at home"},{"left":"Who can captain a team?","right":"The best leader"},{"left":"Who can mind the baby?","right":"Mum or dad"},{"left":"Who can drive the bus?","right":"Anyone trained to"}],"relearn":"For every 'who does it', the fair answer is 'anyone who can'.","persona":"any","source":"flip / match"},
  {"id":"fs-1158","cat":"flip-it","type":"sort","hook":"Sort each line: does it still need flipping, or is it already a fair flip?","items":[{"id":"a","text":"Boys can't cry"},{"id":"b","text":"Girls can lead a team"},{"id":"c","text":"Driving is a man's job"},{"id":"d","text":"Anyone can cook dinner"},{"id":"e","text":"Pretty is all that matters for girls"},{"id":"f","text":"Dolls are for any kid"}],"bins":[{"id":"flip","label":"Still needs flipping","valence":"neg"},{"id":"fair","label":"Already a fair flip","valence":"pos"}],"key":{"a":"flip","b":"fair","c":"flip","d":"fair","e":"flip","f":"fair"},"relearn":"You can tell a tired script from one that's already flipped.","persona":"any","source":"flip / sort"},
  {"id":"fs-1159","cat":"flip-it","type":"sort","hook":"Sort each: a made-up rule to flip, or a real reason that stays?","items":[{"id":"a","text":"Pink is for girls only"},{"id":"b","text":"Wear a helmet on a bike"},{"id":"c","text":"Boys can't grow long hair"},{"id":"d","text":"Wash hands before eating"},{"id":"e","text":"Dolls are just for girls"},{"id":"f","text":"Slow down near the school gate"}],"bins":[{"id":"madeup","label":"Made-up rule, flip it","valence":"neg"},{"id":"real","label":"Real reason, keep it","valence":"pos"}],"key":{"a":"madeup","b":"real","c":"madeup","d":"real","e":"madeup","f":"real"},"relearn":"A made-up gender rule isn't the same as a real-reason rule.","persona":"any","source":"flip / sort"},
  {"id":"fs-1160","cat":"flip-it","type":"sort","hook":"Sort each fair flip into the part of life it belongs to.","items":[{"id":"a","text":"Girls captain the cricket team"},{"id":"b","text":"Dad sings the baby to sleep"},{"id":"c","text":"Boys cry and that's healthy"},{"id":"d","text":"Dad does the laundry"},{"id":"e","text":"Girls feel anger too"},{"id":"f","text":"The family shares the cooking"}],"bins":[{"id":"play","label":"Play & sport","valence":"neutral"},{"id":"home","label":"Home & care","valence":"neutral"},{"id":"feel","label":"Feelings","valence":"neutral"}],"key":{"a":"play","d":"home","b":"home","c":"feel","e":"feel","f":"home"},"relearn":"Fair flips show up in play, at home and in feelings alike.","persona":"any","source":"flip / sort"},
  {"id":"fs-1161","cat":"flip-it","type":"sort","hook":"You remixed a film. Sort each line: kept the stereotype, or flipped it fair?","items":[{"id":"a","text":"The boy still saves everyone alone"},{"id":"b","text":"The girl leads half the mission"},{"id":"c","text":"Only the girl is shown crying"},{"id":"d","text":"Both kids show fear and courage"},{"id":"e","text":"Mum is the only one cooking"},{"id":"f","text":"Dad cooks while mum fixes the car"}],"bins":[{"id":"kept","label":"Kept the stereotype","valence":"neg"},{"id":"flipped","label":"Flipped it fair","valence":"pos"}],"key":{"a":"kept","c":"kept","e":"kept","b":"flipped","d":"flipped","f":"flipped"},"relearn":"In a remix, some lines flip fair and some sneak the old script back.","persona":"any","source":"flip / sort"},
  {"id":"fs-1162","cat":"flip-it","type":"sort","hook":"Sort each remix idea: would it make the ad fairer, or keep it stereotyped?","items":[{"id":"a","text":"Show dad doing the laundry too"},{"id":"b","text":"Stamp 'for real men only' on it"},{"id":"c","text":"Cast a girl as the scientist"},{"id":"d","text":"Make the only carer a woman"},{"id":"e","text":"Show a mixed, fair team"},{"id":"f","text":"Put the girl there just to look pretty"}],"bins":[{"id":"fairer","label":"Makes it fairer","valence":"pos"},{"id":"keeps","label":"Keeps it stereotyped","valence":"neg"}],"key":{"a":"fairer","c":"fairer","e":"fairer","b":"keeps","d":"keeps","f":"keeps"},"relearn":"A real remix adds fair ideas, not more of the old stereotype.","persona":"any","source":"flip / sort"},
  {"id":"fs-1163","cat":"flip-it","type":"sort","hook":"Sort each: is it about who you are, or a made-up gender script to flip?","items":[{"id":"a","text":"You love painting"},{"id":"b","text":"Boys shouldn't paint"},{"id":"c","text":"You enjoy playing football"},{"id":"d","text":"Football is only for boys"},{"id":"e","text":"You like wearing bright colours"},{"id":"f","text":"Bright colours are only for girls"}],"bins":[{"id":"you","label":"Who you are","valence":"pos"},{"id":"script","label":"Made-up script, flip it","valence":"neg"}],"key":{"a":"you","c":"you","e":"you","b":"script","d":"script","f":"script"},"relearn":"Your tastes are yours; the gender rule around them is what you flip.","persona":"any","source":"flip / sort"},
  {"id":"fs-1164","cat":"flip-it","type":"sort","hook":"Sort each line: does it free every gender, or only flip one direction?","items":[{"id":"a","text":"Girls can lead, and boys can cry"},{"id":"b","text":"Girls can do anything, boys just toughen up"},{"id":"c","text":"Everyone shares the chores"},{"id":"d","text":"Only girls get to chase big dreams"},{"id":"e","text":"Any kid can play any sport"},{"id":"f","text":"Boys can cook, but girls still must"}],"bins":[{"id":"both","label":"Frees every gender","valence":"pos"},{"id":"half","label":"Only half-flipped","valence":"uhoh"}],"key":{"a":"both","c":"both","e":"both","b":"half","d":"half","f":"half"},"relearn":"A real flip frees all genders, not just one side of the script.","persona":"any","source":"flip / sort"},
  {"id":"fs-1165","cat":"flip-it","type":"sort","hook":"Sort each flip by who it sets free: mostly a boy-script or a girl-script?","items":[{"id":"a","text":"Boys are allowed to cry"},{"id":"b","text":"Girls can captain the team"},{"id":"c","text":"Boys can mind a baby"},{"id":"d","text":"Girls can be brilliant at maths"},{"id":"e","text":"Boys can love art and dance"},{"id":"f","text":"Girls can feel and show anger"}],"bins":[{"id":"boys","label":"Frees a boy-script","valence":"pos"},{"id":"girls","label":"Frees a girl-script","valence":"pos"}],"key":{"a":"boys","c":"boys","e":"boys","b":"girls","d":"girls","f":"girls"},"relearn":"Good flipping frees boy-scripts and girl-scripts in equal measure.","persona":"any","source":"flip / sort"},
  {"id":"fs-1170","cat":"jobs-roles","type":"sort","hook":"Sort each job: open to anyone, or a made-up 'one gender only' rule?","items":[{"id":"a","text":"Train driver"},{"id":"b","text":"Tailor stitching clothes"},{"id":"c","text":"\"Only men can be auto drivers\""},{"id":"d","text":"School principal"},{"id":"e","text":"\"Beauty parlour work is just for women\""},{"id":"f","text":"Bank manager"}],"bins":[{"id":"open","label":"Open to anyone","valence":"pos"},{"id":"madeup","label":"Made-up rule","valence":"neg"}],"key":{"a":"open","b":"open","c":"madeup","d":"open","e":"madeup","f":"open"},"relearn":"Skill decides who does a job, not gender; 'only one gender' rules are made up.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1171","cat":"jobs-roles","type":"sort","hook":"Sort: does this break a job stereotype, or repeat one?","items":[{"id":"a","text":"A woman driving a city bus"},{"id":"b","text":"\"Boys can't be cooks\""},{"id":"c","text":"A man teaching tiny kids"},{"id":"d","text":"\"Girls shouldn't fix machines\""},{"id":"e","text":"A girl captain of the maths club"},{"id":"f","text":"\"Cleaning is only mum's job\""}],"bins":[{"id":"breaks","label":"Breaks it","valence":"pos"},{"id":"repeats","label":"Repeats it","valence":"neg"}],"key":{"a":"breaks","b":"repeats","c":"breaks","d":"repeats","e":"breaks","f":"repeats"},"relearn":"Spotting who breaks a stereotype shows what's really possible for anyone.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1172","cat":"jobs-roles","type":"sort","hook":"Sort each line about chores: fair sharing, or a gender rule?","items":[{"id":"a","text":"Anyone can cook dinner"},{"id":"b","text":"\"Only mum folds clothes\""},{"id":"c","text":"Dad feeds the baby too"},{"id":"d","text":"\"Boys never carry bags\""},{"id":"e","text":"All take turns with chores"},{"id":"f","text":"\"Bulbs are a man's job\""}],"bins":[{"id":"anyone","label":"Fair sharing","valence":"pos"},{"id":"gendered","label":"Gender rule","valence":"neg"}],"key":{"a":"anyone","c":"anyone","e":"anyone","b":"gendered","d":"gendered","f":"gendered"},"relearn":"Chores can be shared by anyone; 'one gender only' chore rules are made up.","persona":"Rohit","source":"chores"},
  {"id":"fs-1173","cat":"jobs-roles","type":"sort","hook":"Sort each into: a skill you learn, or a 'gender' you're born with?","items":[{"id":"a","text":"Flying a plane"},{"id":"b","text":"Cooking a meal"},{"id":"c","text":"Being a boy"},{"id":"d","text":"Coding an app"},{"id":"e","text":"Being a girl"},{"id":"f","text":"Driving a truck"}],"bins":[{"id":"skill","label":"A learned skill","valence":"pos"},{"id":"born","label":"Just who you are","valence":"neutral"}],"key":{"a":"skill","b":"skill","c":"born","d":"skill","e":"born","f":"skill"},"relearn":"Jobs are learned skills; your gender is just you, and it doesn't pick your job.","persona":"any","source":"jobs / skills"},
  {"id":"fs-1174","cat":"jobs-roles","type":"sort","hook":"Sort: fair sharing at home, or an unfair 'her job' rule?","items":[{"id":"a","text":"Dad and mum both cook on different days"},{"id":"b","text":"\"Only girls clear the plates\""},{"id":"c","text":"Brother and sister both sweep"},{"id":"d","text":"\"Boys never do dishes\""},{"id":"e","text":"Everyone makes their own bed"},{"id":"f","text":"\"Washing clothes is mum's duty alone\""}],"bins":[{"id":"fair","label":"Fair sharing","valence":"pos"},{"id":"unfair","label":"Unfair rule","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"A happier home shares the work; 'only her job' chore rules are unfair and made up.","persona":"Rohit","source":"chores / fairness"},
  {"id":"fs-1175","cat":"jobs-roles","type":"sort","hook":"Sort each line: a real reason, or a made-up gender rule?","items":[{"id":"a","text":"Pilots train for years to fly safely"},{"id":"b","text":"\"Women can't be pilots\""},{"id":"c","text":"Surgeons wash hands before operating"},{"id":"d","text":"\"Girls can't be surgeons\""},{"id":"e","text":"Coders learn maths to build apps"},{"id":"f","text":"\"Coding is a boy thing\""}],"bins":[{"id":"real","label":"Real reason","valence":"pos"},{"id":"madeup","label":"Made-up rule","valence":"neg"}],"key":{"a":"real","b":"madeup","c":"real","d":"madeup","e":"real","f":"madeup"},"relearn":"A real job reason is about skill and safety; 'one gender only' is just made up.","persona":"Diya","source":"jobs / equality"},
  {"id":"fs-1176","cat":"jobs-roles","type":"sort","hook":"Sort: does this back a kid's dream, or wrongly block it?","items":[{"id":"a","text":"\"Go for it, be an astronaut!\""},{"id":"b","text":"\"Boys can't be nurses\""},{"id":"c","text":"\"Sure, a girl can be an engineer\""},{"id":"d","text":"\"Cooking's not a boy's career\""},{"id":"e","text":"\"You'd be a great captain\""},{"id":"f","text":"\"Teaching tots isn't for boys\""}],"bins":[{"id":"open","label":"Backs the dream","valence":"pos"},{"id":"blocked","label":"Wrongly blocks it","valence":"neg"}],"key":{"a":"open","c":"open","e":"open","b":"blocked","d":"blocked","f":"blocked"},"relearn":"No job is shut to a kid because of gender; backing the dream is fair.","persona":"any","source":"aspiration"},
  {"id":"fs-1177","cat":"jobs-roles","type":"sort","hook":"Sort each Indian role model by their job.","items":[{"id":"a","text":"Kalpana Chawla flew to space"},{"id":"b","text":"Mary Kom won boxing rings"},{"id":"c","text":"A woman flies fighter jets for India"},{"id":"d","text":"A man runs a popular cooking show"},{"id":"e","text":"A woman captains India at cricket"},{"id":"f","text":"A dad stays home to raise his kids"}],"bins":[{"id":"sky","label":"In the sky","valence":"neutral"},{"id":"sport","label":"In sport","valence":"neutral"},{"id":"home","label":"Care & home","valence":"neutral"}],"key":{"a":"sky","c":"sky","b":"sport","e":"sport","d":"home","f":"home"},"relearn":"Real people of every gender fill every kind of job, in the sky, in sport, at home.","persona":"any","source":"role models"},
  {"id":"fs-1178","cat":"jobs-roles","type":"sort","hook":"Sort each claim about women's jobs: fair fact, or stereotype?","items":[{"id":"a","text":"Women serve as soldiers"},{"id":"b","text":"\"Women can't drive autos\""},{"id":"c","text":"Women work as engineers"},{"id":"d","text":"\"Police work isn't for women\""},{"id":"e","text":"Women fly as airline pilots"},{"id":"f","text":"\"A woman can't umpire cricket\""}],"bins":[{"id":"yes","label":"Fair fact","valence":"pos"},{"id":"no","label":"Stereotype","valence":"neg"}],"key":{"a":"yes","c":"yes","e":"yes","b":"no","d":"no","f":"no"},"relearn":"Women already do all these jobs; the 'can't' claims are stereotypes.","persona":"Diya","source":"jobs / equality"},
  {"id":"fs-1179","cat":"jobs-roles","type":"sort","hook":"Sort each claim about men's jobs: fair fact, or stereotype?","items":[{"id":"a","text":"Men work as nurses"},{"id":"b","text":"\"Men can't teach tiny kids\""},{"id":"c","text":"Men become top cooks"},{"id":"d","text":"\"Tailoring is too fiddly for men\""},{"id":"e","text":"A man can be a stay-at-home dad"},{"id":"f","text":"\"Men can't do caring work\""}],"bins":[{"id":"yes","label":"Fair fact","valence":"pos"},{"id":"no","label":"Stereotype","valence":"neg"}],"key":{"a":"yes","c":"yes","e":"yes","b":"no","d":"no","f":"no"},"relearn":"Men already do all these caring jobs; the 'can't' claims are stereotypes.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1180","cat":"jobs-roles","type":"sort","hook":"Sort each saying: stereotype, or fair truth about jobs?","items":[{"id":"a","text":"\"Bosses should be men\""},{"id":"b","text":"Anyone with vision can lead a team"},{"id":"c","text":"\"Girls aren't built for science\""},{"id":"d","text":"Skill, not gender, decides who's hired"},{"id":"e","text":"\"Men shouldn't do care work\""},{"id":"f","text":"A good nurse can be any gender"}],"bins":[{"id":"stereotype","label":"Stereotype","valence":"neg"},{"id":"truth","label":"Fair truth","valence":"pos"}],"key":{"a":"stereotype","c":"stereotype","e":"stereotype","b":"truth","d":"truth","f":"truth"},"relearn":"Job stereotypes pick a gender; the fair truth picks skill, for any gender.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1181","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Boys should be engineers, girls should be teachers.\"","myth":{"un":"Boys should be engineers, girls should be teachers.","re":"Girls build bridges and boys teach classrooms; either job fits any kid.","why":"Interest and skill choose your job, not your gender."},"relearn":"Engineering and teaching are both open to every gender.","persona":"Diya","source":"jobs / education"},
  {"id":"fs-1182","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Girls can't be soldiers.\"","myth":{"un":"Girls can't be soldiers.","re":"Women serve in India's army, navy and air force, on land, sea and air.","why":"Courage and training make a soldier, not gender."},"relearn":"Women serve as soldiers; the armed forces aren't only for men.","persona":"Diya","source":"jobs / India"},
  {"id":"fs-1183","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Men can't look after small children.\"","myth":{"un":"Men can't look after small children.","re":"Dads and male teachers care for little kids gently and well every day.","why":"Caring is a skill anyone learns, not a 'mum only' job."},"relearn":"Men care for small children too; caring isn't owned by women.","persona":"Rohit","source":"care / roles"},
  {"id":"fs-1184","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Coding and computers are a boy thing.\"","myth":{"un":"Coding and computers are really a boy thing.","re":"Girls write code and build apps brilliantly; computing fits every mind.","why":"Logic and practice make a coder, not gender."},"relearn":"Girls code too; computing isn't a 'boy thing'.","persona":"Diya","source":"jobs / tech"},
  {"id":"fs-1185","cat":"jobs-roles","type":"strike-rewrite","hook":"\"A doctor is a man; a woman must be the nurse.\"","myth":{"un":"The doctor is a man and the woman must be the nurse.","re":"Women are doctors and men are nurses; either job fits either gender.","why":"Training, not gender, decides who's the doctor or nurse."},"relearn":"Women are doctors and men are nurses; both roles fit anyone.","persona":"any","source":"jobs / health"},
  {"id":"fs-1186","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Bosses and leaders should be men.\"","myth":{"un":"Bosses and leaders should be men.","re":"People of any gender lead teams, schools and companies well.","why":"Vision and fairness make a leader, not gender."},"relearn":"Leaders can be any gender; bossing isn't a 'man only' role.","persona":"any","source":"leadership"},
  {"id":"fs-1187","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Girls shouldn't play sport seriously, it's a boys' field.\"","myth":{"un":"Girls shouldn't play sport seriously; it's a boys' field.","re":"Girls win medals in boxing, cricket, hockey and wrestling.","why":"Practice builds a champion, not gender."},"relearn":"Girls compete and win in sport; the field isn't only for boys.","persona":"Diya","source":"sport / jobs"},
  {"id":"fs-1188","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Tailoring is men's work; girls just embroider.\"","myth":{"un":"Tailoring is men's work and girls just embroider.","re":"Tailors of every gender cut, stitch and design clothes.","why":"A steady hand and an eye make a tailor, not gender."},"relearn":"Anyone can be a tailor; stitching isn't split by gender.","persona":"any","source":"jobs / crafts"},
  {"id":"fs-1189","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Farming is a man's job; women just help.\"","myth":{"un":"Farming is a man's job and women just help.","re":"Women farm, drive tractors and run their own fields across India.","why":"Hard work and know-how grow a crop, not gender."},"relearn":"Women farm and lead fields; farming isn't a 'man's job'.","persona":"any","source":"jobs / India"},
  {"id":"fs-1190","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Boys can't be dancers or designers; that's girly.\"","myth":{"un":"Boys can't be dancers or designers; that's girly.","re":"Many celebrated dancers and designers are men; art has no gender.","why":"Talent and practice make an artist, not gender."},"relearn":"Boys dance and design too; the arts aren't 'girly'.","persona":"Aarav","source":"arts / jobs"},
  {"id":"fs-1191","cat":"jobs-roles","type":"strike-rewrite","hook":"\"A girl's main job is to marry and run a house.\"","myth":{"un":"A girl's main job is to marry and run a house.","re":"Girls choose any path: study, work, lead, travel, or run a home if they wish.","why":"A girl's future is hers to pick, like any boy's."},"relearn":"A girl can choose any future; her life isn't only home and marriage.","persona":"Diya","source":"roles / aspiration"},
  {"id":"fs-1192","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Men don't do housework once they earn.\"","myth":{"un":"Men don't do housework once they earn.","re":"Earning and housework go together; fair partners share both.","why":"A home runs on everyone pitching in, whatever they earn."},"relearn":"Men share housework too; earning doesn't excuse anyone from chores.","persona":"Rohit","source":"chores / fairness"},
  {"id":"fs-1193","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Girls can't drive trucks or autos; it's a man's wheel.\"","myth":{"un":"Girls can't drive trucks or autos; it's a man's wheel.","re":"Women drive autos, buses and trucks for a living across India.","why":"Driving is a skill you practise, not a gender."},"relearn":"Women drive autos and trucks; the wheel isn't a 'man's' thing.","persona":"any","source":"jobs / driving"},
  {"id":"fs-1194","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Science labs are no place for girls.\"","myth":{"un":"Science labs are no place for girls.","re":"Girls run experiments and become scientists, like Kalpana Chawla did.","why":"Curiosity and care make a scientist, not gender."},"relearn":"Girls belong in science labs; ability isn't decided by gender.","persona":"Diya","source":"science / jobs"},
  {"id":"fs-1195","cat":"jobs-roles","type":"strike-rewrite","hook":"\"A stay-at-home parent has to be the mum.\"","myth":{"un":"A stay-at-home parent has to be the mum.","re":"A dad can stay home to raise the kids while the mum works.","why":"Either parent can be the carer or the earner."},"relearn":"A stay-at-home parent can be a dad; the role isn't only mum's.","persona":"Rohit","source":"roles / family"},
  {"id":"fs-1196","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Girls who fix machines are unladylike.\"","myth":{"un":"Girls who fix machines are unladylike.","re":"Girls who repair bikes and gadgets are simply skilled and useful.","why":"Fixing things is a handy skill, open to any gender."},"relearn":"Girls can fix machines; tinkering isn't 'unladylike'.","persona":"any","source":"jobs / skills"},
  {"id":"fs-1197","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Boys can't be flight attendants or receptionists.\"","myth":{"un":"Boys can't be flight attendants or receptionists.","re":"Men welcome guests and look after flyers in these jobs every day.","why":"Friendliness and care make these roles, not gender."},"relearn":"Men do welcoming, caring service jobs too; they aren't 'girl jobs'.","persona":"Aarav","source":"jobs / service"},
  {"id":"fs-1198","cat":"jobs-roles","type":"strike-rewrite","hook":"\"A woman can't be the head of a company.\"","myth":{"un":"A woman can't be the head of a company.","re":"Women run big companies and small shops as the boss.","why":"Good decisions make a leader, not gender."},"relearn":"Women lead companies too; the top job isn't only for men.","persona":"any","source":"leadership / jobs"},
  {"id":"fs-1199","cat":"jobs-roles","type":"strike-rewrite","hook":"\"Only girls should learn to cook for the family.\"","myth":{"un":"Only girls should learn to cook for the family.","re":"Boys learn to cook too; it's a life skill everyone needs.","why":"Everyone eats, so everyone benefits from cooking."},"relearn":"Boys should learn cooking too; it isn't only a girl's lesson.","persona":"Rohit","source":"chores / skills"},
  {"id":"fs-1200","cat":"jobs-roles","type":"match","hook":"Match each India role model to their job.","pairs":[{"left":"Kalpana Chawla","right":"Astronaut in space"},{"left":"Mary Kom","right":"Champion boxer"},{"left":"Harmanpreet Kaur","right":"Cricket captain"},{"left":"A woman in the air force","right":"Fighter pilot"},{"left":"A celebrated chef on TV","right":"Cook (often a man)"}],"relearn":"Real people of every gender lead in space, sport, the sky and the kitchen.","persona":"any","source":"role models"},
  {"id":"fs-1201","cat":"jobs-roles","type":"match","hook":"Match each job to the true fact about who can do it.","pairs":[{"left":"Pilot","right":"Women fly too"},{"left":"Nurse","right":"Men care too"},{"left":"Scientist","right":"Any gender, like Kalpana"},{"left":"Truck driver","right":"Women drive too"},{"left":"Stay-at-home parent","right":"Can be a dad"}],"relearn":"Every job here is open to more than one gender; the fact proves it.","persona":"any","source":"jobs / roles"},
  {"id":"fs-1202","cat":"jobs-roles","type":"match","hook":"Match the stereotype to the fair flip.","pairs":[{"left":"\"Cooking is women's work\"","right":"Anyone can cook"},{"left":"\"Bosses must be men\"","right":"Leaders are any gender"},{"left":"\"Girls can't do maths\"","right":"Girls excel at maths"},{"left":"\"Men can't nurse\"","right":"Men care too"},{"left":"\"Driving is a man's thing\"","right":"Women drive everything"}],"relearn":"Every job stereotype has a fair flip that opens it to all genders.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1203","cat":"jobs-roles","type":"match","hook":"Match each home chore to who can do it.","pairs":[{"left":"Cooking dinner","right":"Mum or dad"},{"left":"Fixing the fan","right":"Anyone who learns how"},{"left":"Feeding the baby","right":"Either parent"},{"left":"Washing dishes","right":"Every family member"},{"left":"Paying bills","right":"Whoever handles money"}],"relearn":"No home chore belongs to one gender; every one can be shared.","persona":"Rohit","source":"chores"},
  {"id":"fs-1204","cat":"jobs-roles","type":"match","hook":"Match the tool to a worker of any gender who uses it.","pairs":[{"left":"Stethoscope","right":"A doctor"},{"left":"Spanner","right":"A mechanic"},{"left":"Chalk and duster","right":"A teacher"},{"left":"Cricket bat","right":"A player"},{"left":"Cockpit controls","right":"A pilot"}],"relearn":"The tool fits the job, and the worker can be any gender.","persona":"any","source":"jobs / skills"},
  {"id":"fs-1205","cat":"jobs-roles","type":"match","hook":"Match the dream job to the skill that really matters for it.","pairs":[{"left":"Pilot","right":"Steady focus"},{"left":"Chef","right":"A good sense of taste"},{"left":"Coder","right":"Clear logic"},{"left":"Nurse","right":"Patient care"},{"left":"Captain","right":"Teamwork and vision"}],"relearn":"Jobs are won by skills like these, never by being a boy or a girl.","persona":"any","source":"jobs / skills"},
  {"id":"fs-1206","cat":"jobs-roles","type":"match","hook":"Match the false 'rule' to why it's actually made up.","pairs":[{"left":"\"Girls can't be pilots\"","right":"Women fly jets already"},{"left":"\"Men can't cook\"","right":"Top chefs are often men"},{"left":"\"Girls aren't good at science\"","right":"Girls top science classes"},{"left":"\"Boys can't dance\"","right":"Many great dancers are men"},{"left":"\"Women can't be soldiers\"","right":"Women serve in the forces"}],"relearn":"Each 'rule' falls apart the moment you name who already does that job.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1207","cat":"jobs-roles","type":"match","hook":"Match each kid's dream to a real person who already did it.","pairs":[{"left":"\"I want to box\"","right":"Mary Kom did"},{"left":"\"I want to fly to space\"","right":"Kalpana Chawla did"},{"left":"\"I want to captain India\"","right":"Harmanpreet Kaur did"},{"left":"\"I want to be a chef\"","right":"Many men cook on TV"},{"left":"\"I want to fly jets\"","right":"Women in the air force do"}],"relearn":"Whatever the dream, someone of that gender has already shown it can be done.","persona":"any","source":"role models"},
  {"id":"fs-1208","cat":"jobs-roles","type":"branch","hook":"A boy says \"science projects should be led by boys, they're smarter\".","options":[{"text":"Say \"let's pick whoever's keenest, not by gender\"","consequence":"The group picks fairly and the best idea wins.","outcome":"fair","best":true},{"text":"Agree so it moves fast","consequence":"Smarts aren't a boy thing; a keen girl is sidelined unfairly."}],"debrief":"Brains don't come in boy or girl versions; keenness should lead.","relearn":"Anyone can lead a science project; smarts aren't decided by gender.","persona":"Diya","source":"education / equality"},
  {"id":"fs-1209","cat":"jobs-roles","type":"branch","hook":"Your cousin wants to be a nurse; his uncle laughs, \"that's a girl's job\".","options":[{"text":"Tell your cousin men are great nurses and back him","consequence":"He feels proud of his dream again.","outcome":"fair","best":true},{"text":"Laugh along so the uncle isn't upset","consequence":"Nursing fits any gender; your cousin hears his dream is shameful."}],"debrief":"Nursing is skilled care work for anyone; backing a dream is kind and right.","relearn":"Men make excellent nurses; nursing isn't a 'girl's job'.","persona":"any","source":"care / call-out"},
  {"id":"fs-1210","cat":"jobs-roles","type":"branch","hook":"At a robotics fair, a friend says \"leave the girls on decorations\".","options":[{"text":"Say \"girls build robots too; let's share the work\"","consequence":"Everyone gets to build and the team is stronger.","outcome":"fair","best":true},{"text":"Put the girls on decorations to keep peace","consequence":"Skilled builders are wasted because of a made-up gender rule."}],"debrief":"Skill, not gender, should decide who builds; all deserve a real role.","relearn":"Girls build robots too; tasks shouldn't be split by gender.","persona":"any","source":"jobs / teamwork"},
  {"id":"fs-1211","cat":"jobs-roles","type":"branch","hook":"Your brother is told \"go play, cooking is your sister's job\".","options":[{"text":"Say \"cooking's a life skill; let's both help\"","consequence":"The work is shared and your brother learns to cook.","outcome":"fair","best":true},{"text":"Let him off so you finish faster","consequence":"He misses a skill everyone needs, and you carry it all."}],"debrief":"Cooking is for everyone; sharing it is fairer and teaches a real skill.","relearn":"Boys should help cook too; the kitchen isn't only a sister's job.","persona":"Rohit","source":"chores / fairness"},
  {"id":"fs-1212","cat":"jobs-roles","type":"branch","hook":"A careers poster shows only men as engineers and only women as cooks.","options":[{"text":"Ask the teacher to add women engineers and men chefs","consequence":"The poster is fixed and shows all jobs as open.","outcome":"fair","best":true},{"text":"Ignore it, it's just a poster","consequence":"Kids keep absorbing the made-up 'who does what' split."}],"debrief":"A kind suggestion can flip a stereotyped poster into a fair one.","relearn":"Engineers and cooks can be any gender; posters should show that.","persona":"Asha","source":"media / call-out"},
  {"id":"fs-1213","cat":"jobs-roles","type":"branch","hook":"Your friend won't run for monitor: \"girls don't get picked to lead\".","options":[{"text":"Encourage her: \"you'd lead well; one of us has to be first\"","consequence":"She tries out and others see a girl can lead.","outcome":"fair","best":true},{"text":"Agree it's pointless for her to try","consequence":"The made-up rule wins and a good leader stays hidden."}],"debrief":"Leadership is a skill, not a boy thing; one girl trying opens the door.","relearn":"Girls get picked to lead too; trying out flips the stereotype.","persona":"Diya","source":"leadership / equality"},
  {"id":"fs-1214","cat":"jobs-roles","type":"branch","hook":"A shopkeeper tells your sister \"tool-kits are for boys, pick a kitchen set\".","options":[{"text":"Say \"she likes tools; any kid can enjoy any toy\"","consequence":"Your sister gets the toy she actually wants.","outcome":"fair","best":true},{"text":"Swap it for the kitchen set to avoid fuss","consequence":"Her real interest is overruled by a shop's made-up gender rule."}],"debrief":"Toys teach skills, not gender; a tool-kit is for any curious kid.","relearn":"Tool-kits aren't only for boys; any kid can pick any toy.","persona":"any","source":"toys / call-out"},
  {"id":"fs-1215","cat":"jobs-roles","type":"branch","hook":"On a trip, the teacher says \"boys carry the bags, girls mind the lunch\".","options":[{"text":"Ask \"can we pick by who wants which job?\"","consequence":"Tasks are shared by choice, not by gender.","outcome":"fair","best":true},{"text":"Do as told; it's quicker","consequence":"A made-up split decides the work instead of fairness."}],"debrief":"Even well-meant habits can split work by gender; a kind question fixes it.","relearn":"Carrying or caring isn't a gender job; share tasks by choice.","persona":"Asha","source":"jobs / call-out"},
  {"id":"fs-1216","cat":"jobs-roles","type":"reflect","hook":"Lensy: picture a job you'd love to do one day. Does your gender stop you?","prompt":"What do you think?","options":["Nothing stops me","I just need to learn the skill","My gender has nothing to do with it"],"affirm":"Your dream job is about your skills and effort, never your gender. 💛","relearn":"Your gender doesn't decide the job you can dream of and reach.","persona":"any","source":"aspiration"},
  {"id":"fs-1217","cat":"jobs-roles","type":"reflect","hook":"Lensy: think of who does which chore at your home. Could the jobs be swapped?","prompt":"What do you think?","options":["Yes, anyone could do them","We could share more fairly","Chores aren't really gender jobs"],"affirm":"Home runs best when everyone shares the work, whatever their gender.","relearn":"Home chores can be swapped and shared; none belongs to one gender.","persona":"Rohit","source":"chores / fairness"},
  {"id":"fs-1218","cat":"jobs-roles","type":"reflect","hook":"Lensy: name a job you once thought was 'only for boys' or 'only for girls'.","prompt":"What do you think now?","options":["Anyone can do it","I was just repeating a script","Skill is what matters"],"affirm":"Noticing an old job-script is the first step to flipping it. Nice spotting.","relearn":"Jobs we thought were gendered are open to anyone; the rule was made up.","persona":"any","source":"jobs / self-check"},
  {"id":"fs-1219","cat":"jobs-roles","type":"reflect","hook":"Lensy: which job would you most love to try, and what skill would help you most?","prompt":"What do you think?","options":["Practice would get me there","I'd learn the skill step by step","Effort matters more than gender"],"affirm":"Skills grow with practice, and they're open to you whoever you are.","relearn":"Any job is reachable with the right skill and practice, not a gender.","persona":"any","source":"aspiration / skills"},
  {"id":"fs-1220","cat":"jobs-roles","type":"reflect","hook":"Lensy: when you see a woman pilot or a man nurse, what does it tell you?","prompt":"What do you think?","options":["Any job is open to anyone","Skill beats stereotypes","I could do that too"],"affirm":"Every real example proves a job belongs to skill, not a gender.","relearn":"Seeing people break job stereotypes shows what's truly possible.","persona":"any","source":"role models"},
  {"id":"fs-1221","cat":"jobs-roles","type":"reflect","hook":"Lensy: imagine your future home. Who cooks, earns and cares for the kids?","prompt":"What do you think?","options":["We'd share it all","Whoever's best or keenest","Both of us, fairly"],"affirm":"A fair home shares earning, cooking and caring, however it's made up.","relearn":"Earning, cooking and caring can all be shared, not split by gender.","persona":"Rohit","source":"roles / family"},
  {"id":"fs-1222","cat":"jobs-roles","type":"reflect","hook":"Lensy: a friend says a job is 'not for your gender'. How does that idea feel?","prompt":"What do you think?","options":["Unfair","Like a made-up rule","Something I'd want to question"],"affirm":"Questioning a 'not for your gender' rule is fair and brave, na?","relearn":"A 'job not for your gender' is a made-up rule worth questioning.","persona":"Diya","source":"jobs / fairness"},
  {"id":"fs-1223","cat":"jobs-roles","type":"reflect","hook":"Lensy: think of a grown-up you know who does a job people don't expect for their gender.","prompt":"What do you think of them?","options":["They're skilled","They're brave to do it","They show me it's possible"],"affirm":"People who flip job-scripts open doors for everyone who comes after.","relearn":"Grown-ups who break job stereotypes show others what's possible.","persona":"any","source":"role models"},
  {"id":"fs-1224","cat":"jobs-roles","type":"role-play","hook":"Speak up kindly when a job gets labelled by gender.","setup":"At the science fair, a kid tells your friend \"engineering's for boys, pick something easier\".","yourLine":[{"text":"\"Engineering's for anyone keen, na? She'd build something brilliant.\"","best":true},{"text":"\"Maybe just try the easy project to be safe.\""}],"relearn":"Engineering is open to any gender; backing a friend kindly flips the script.","persona":"Asha","source":"jobs / call-out"},
  {"id":"fs-1225","cat":"jobs-roles","type":"role-play","hook":"Stand up for a boy who wants a caring job.","setup":"Your cousin says he wants to be a kindergarten teacher and a relative scoffs, \"men don't do that\".","yourLine":[{"text":"\"Men make great teachers for little ones; it's caring, useful work.\"","best":true},{"text":"\"Yeah, maybe pick something more manly instead.\""}],"relearn":"Men teach and care for young kids well; the job isn't a 'woman's' one.","persona":"any","source":"care / call-out"},
  {"id":"fs-1226","cat":"jobs-roles","type":"role-play","hook":"Flip a 'whose job' comment about chores at home.","setup":"Your brother is told to relax while you're sent to wash up, \"that's the girls' work\".","yourLine":[{"text":"\"Washing up isn't girls' work, na? Let's split it and both finish faster.\"","best":true},{"text":"\"Fine, I'll just do it all myself again.\""}],"relearn":"Chores aren't 'girls' work'; sharing them is fairer for everyone.","persona":"Diya","source":"chores / call-out"},
  {"id":"fs-1227","cat":"jobs-roles","type":"role-play","hook":"Encourage a girl to aim high in sport.","setup":"Your friend says \"there's no point me trying cricket trials, girls don't really play\".","yourLine":[{"text":"\"Girls captain India at cricket! Let's go to the trials together.\"","best":true},{"text":"\"Yeah, maybe cricket's more of a boys' thing anyway.\""}],"relearn":"Girls play and lead in cricket; sport isn't only for boys.","persona":"Diya","source":"sport / call-out"},
  {"id":"fs-1228","cat":"jobs-roles","type":"role-play","hook":"Speak up when a woman's skill gets doubted at work.","setup":"At your aunt's garage, a customer mutters \"is there a man who can fix my bike instead?\".","yourLine":[{"text":"\"My aunt's the mechanic here and she's brilliant with bikes.\"","best":true},{"text":"\"Um, I'll see if someone else is around.\""}],"relearn":"Women are skilled mechanics; doubting them by gender is the stereotype.","persona":"any","source":"jobs / call-out"},
  {"id":"fs-1229","cat":"jobs-roles","type":"role-play","hook":"Back a friend's dream that breaks a job-script.","setup":"Your friend whispers she wants to be a pilot but \"everyone says girls can't fly\".","yourLine":[{"text":"\"Women fly jets for India, na? You'd be a great pilot, go for it.\"","best":true},{"text":"\"Hmm, maybe pick something girls usually do.\""}],"relearn":"Women are pilots; 'girls can't fly' is a made-up rule worth flipping.","persona":"Diya","source":"aspiration / call-out"},
  {"id":"fs-1230","cat":"jobs-roles","type":"role-play","hook":"Flip a 'who's the boss' assumption kindly.","setup":"A visitor assumes your mum is the helper and asks \"where's the owner, the sir?\".","yourLine":[{"text":"\"My mum owns this shop, actually, she's the boss here.\"","best":true},{"text":"\"Oh, um, I'll go and find a sir for you.\""}],"relearn":"Women own and run businesses; the boss isn't always a man.","persona":"any","source":"leadership / call-out"},
  {"id":"fs-1231","cat":"jobs-roles","type":"role-play","hook":"Stand up for sharing care work at home.","setup":"A relative tells your dad to \"leave the baby to the women and go sit down\".","yourLine":[{"text":"\"Dad's great with the baby, na? Sharing care is good for all of us.\"","best":true},{"text":"\"Okay Dad, you go relax, we'll manage the baby.\""}],"relearn":"Dads care for babies well; care work isn't only 'for the women'.","persona":"Rohit","source":"care / call-out"},
  {"id":"fs-1232","cat":"jobs-roles","type":"spot","hook":"Spot the two made-up job rules in this careers talk.","scene":[{"id":"a","text":"Women fly planes for Indian airlines","trick":false},{"id":"b","text":"\"Engineering is only for boys\"","trick":true},{"id":"c","text":"Men work as nurses and carers","trick":false},{"id":"d","text":"\"Girls aren't smart enough for science\"","trick":true},{"id":"e","text":"Anyone can train to be a chef","trick":false}],"why":"Engineering and science fit every gender; ability and training decide, not gender.","relearn":"Engineering and science are open to all genders; the limits are made up.","persona":"Diya","source":"jobs / equality"},
  {"id":"fs-1233","cat":"jobs-roles","type":"spot","hook":"Spot the two unfair lines a careers leaflet should never print.","scene":[{"id":"a","text":"Pilots need steady focus and training","trick":false},{"id":"b","text":"\"Driving big trucks is a man's job\"","trick":true},{"id":"c","text":"Nurses give skilled, caring help","trick":false},{"id":"d","text":"Coders solve problems with logic","trick":false},{"id":"e","text":"\"Cooking professionally suits only women\"","trick":true}],"why":"Women drive trucks and many top chefs are men; these jobs aren't gendered.","relearn":"Truck driving and cooking aren't owned by one gender; skill decides.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1234","cat":"jobs-roles","type":"spot","hook":"Spot the two job stereotypes hiding among the fair facts.","scene":[{"id":"a","text":"A woman can captain India at cricket","trick":false},{"id":"b","text":"\"Boys shouldn't take up dance as a career\"","trick":true},{"id":"c","text":"A dad can stay home to raise kids","trick":false},{"id":"d","text":"\"A woman can't really run a big company\"","trick":true},{"id":"e","text":"Scientists can be any gender","trick":false}],"why":"Boys dance professionally and women lead companies; neither rule is true.","relearn":"Boys can dance and women can lead companies; both stereotypes are false.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1235","cat":"jobs-roles","type":"spot","hook":"This chore chart has two unfair 'gender' rules. Tap them.","scene":[{"id":"a","text":"Everyone makes their own bed","trick":false},{"id":"b","text":"\"Dishes: girls only\"","trick":true},{"id":"c","text":"Dad and mum take turns cooking","trick":false},{"id":"d","text":"\"Repairs: boys only\"","trick":true},{"id":"e","text":"The whole family tidies on Sunday","trick":false}],"why":"No chore belongs to one gender; dishes and repairs can be shared by anyone.","relearn":"Dishes and repairs aren't 'girls only' or 'boys only'; chores are shared.","persona":"Rohit","source":"chores / fairness"},
  {"id":"fs-1236","cat":"jobs-roles","type":"spot","hook":"Spot the two false claims in this 'who does what job' poster.","scene":[{"id":"a","text":"Women serve as soldiers in India","trick":false},{"id":"b","text":"\"Only men can be auto drivers\"","trick":true},{"id":"c","text":"Men can be skilled tailors","trick":false},{"id":"d","text":"\"Teaching small kids is women's work only\"","trick":true},{"id":"e","text":"A scientist can be any gender","trick":false}],"why":"Women drive autos and men teach young kids; neither job is owned by a gender.","relearn":"Auto driving and teaching small kids are open to any gender.","persona":"any","source":"jobs / equality"},
  {"id":"fs-1237","cat":"jobs-roles","type":"spot","hook":"Spot the two lines that wrongly limit a girl's future.","scene":[{"id":"a","text":"A girl can grow up to be an astronaut","trick":false},{"id":"b","text":"\"A girl's only real job is to marry\"","trick":true},{"id":"c","text":"A girl can run her own business","trick":false},{"id":"d","text":"\"Girls shouldn't bother studying maths\"","trick":true},{"id":"e","text":"A girl can lead a team or a class","trick":false}],"why":"A girl can choose any future and excels at maths; both limits are made up.","relearn":"A girl's future and her maths are hers; neither limit is real.","persona":"Diya","source":"aspiration / equality"},
  {"id":"fs-1238","cat":"jobs-roles","type":"spot","hook":"Spot the two put-downs aimed at boys who want caring jobs.","scene":[{"id":"a","text":"Men can be gentle, skilled nurses","trick":false},{"id":"b","text":"\"Boys who want to be carers are soft\"","trick":true},{"id":"c","text":"Dads can cook for the whole family","trick":false},{"id":"d","text":"\"Caring jobs make a boy less of a man\"","trick":true},{"id":"e","text":"Men teach kindergarten with patience","trick":false}],"why":"Caring is strong, useful work for anyone; it never makes a boy 'less'.","relearn":"Boys can take caring jobs; caring work never makes a boy 'less'.","persona":"Aarav","source":"care / equality"},
  {"id":"fs-1239","cat":"jobs-roles","type":"spot","hook":"Spot the two myths in this chat about 'natural' jobs for each gender.","scene":[{"id":"a","text":"Practice, not gender, builds a champion","trick":false},{"id":"b","text":"\"Girls are naturally bad at sport\"","trick":true},{"id":"c","text":"Anyone can learn to code well","trick":false},{"id":"d","text":"\"Boys are naturally smarter at maths\"","trick":true},{"id":"e","text":"Skill comes from effort and learning","trick":false}],"why":"Sport and maths come from practice, not gender; both 'natural' claims are false.","relearn":"Sport and maths skill come from practice, not from being a boy or girl.","persona":"Diya","source":"jobs / equality"},
  {"id":"fs-1260","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Mehndi and bangles are only for girls.\"","myth":{"un":"Mehndi and bangles are only for girls.","re":"Anyone can wear mehndi or bangles if they like them.","why":"Decorations are choices, not gender rules."},"relearn":"Mehndi and bangles aren't owned by one gender.","persona":"any","source":"clothing / festivals"},
  {"id":"fs-1261","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Boys can't wear earrings.\"","myth":{"un":"Boys shouldn't wear earrings.","re":"Earrings are a style choice for anyone.","why":"In many Indian cultures, men have worn earrings for ages."},"relearn":"Earrings are a personal style, not a gender rule.","persona":"Aarav","source":"appearance / culture"},
  {"id":"fs-1262","cat":"looks-stuff","type":"strike-rewrite","hook":"\"That's a girl's colour, you can't pick it.\"","myth":{"un":"Some colours belong to one gender.","re":"No colour belongs to a gender; pick what you love.","why":"Colour-gender links are invented and keep changing."},"relearn":"No colour belongs to a gender; pick what you love.","persona":"any","source":"colours"},
  {"id":"fs-1263","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Girls can't keep their hair short.\"","myth":{"un":"Girls must keep their hair long.","re":"Girls can keep hair short, long or any way they like.","why":"Hair length is comfort and choice, not a gender rule."},"relearn":"Girls choose any hair length; it isn't a rule.","persona":"Diya","source":"appearance"},
  {"id":"fs-1264","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Toy kitchens are for girls only.\"","myth":{"un":"Toy kitchens are just for girls.","re":"Any kid can play cooking; it builds real skills.","why":"Toys teach skills, not gender; everyone eats and cooks."},"relearn":"Toy kitchens build skills for any child.","persona":"any","source":"toys"},
  {"id":"fs-1265","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Building blocks and cars are boys' toys.\"","myth":{"un":"Blocks and toy cars are only for boys.","re":"Any kid can build and zoom; it grows real skills.","why":"Toys are about play and learning, not gender."},"relearn":"Blocks and cars are for any child who enjoys them.","persona":"Diya","source":"toys"},
  {"id":"fs-1266","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Nail polish isn't for boys.\"","myth":{"un":"Nail polish is only for girls.","re":"Nail polish is a fun choice anyone can try.","why":"Decorating yourself is a taste, not a gender rule."},"relearn":"Nail polish is a free choice for anyone.","persona":"any","source":"appearance"},
  {"id":"fs-1267","cat":"looks-stuff","type":"strike-rewrite","hook":"\"A boy in a kurta-pyjama can't like glittery slippers.\"","myth":{"un":"Sparkly, pretty things are only for girls.","re":"Anyone can enjoy sparkle and pretty things.","why":"Liking how something looks isn't a gender rule."},"relearn":"Liking sparkle or pretty things suits anyone.","persona":"any","source":"appearance"},
  {"id":"fs-1268","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Girls can't wear shorts to play.\"","myth":{"un":"Girls shouldn't wear shorts.","re":"Girls wear shorts, salwar, trousers, whatever's comfy.","why":"Clothes are about comfort and play, not rules."},"relearn":"Girls wear whatever is comfortable to play in.","persona":"Diya","source":"clothing"},
  {"id":"fs-1269","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Pink water bottles are only for girls.\"","myth":{"un":"A pink bottle means it's a girl's bottle.","re":"A bottle is for whoever likes it; colour means nothing.","why":"Putting a gender on a colour is a made-up rule."},"relearn":"A colour on an item doesn't give it a gender.","persona":"any","source":"stuff / colours"},
  {"id":"fs-1270","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Headbands and clips look silly on boys.\"","myth":{"un":"Hair clips and bands are only for girls.","re":"Clips keep anyone's hair tidy; they suit everyone.","why":"A hair clip has a job, not a gender."},"relearn":"Hair clips and bands are for anyone.","persona":"Aarav","source":"appearance"},
  {"id":"fs-1271","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Soft toys are babyish for a boy.\"","myth":{"un":"Boys shouldn't keep soft toys.","re":"A soft toy comforts any kid; that's not babyish.","why":"Comfort isn't owned by a gender or an age."},"relearn":"Soft toys comfort any child; that's okay.","persona":"any","source":"toys"},
  {"id":"fs-1272","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Girls' shoes must have heels or sparkles.\"","myth":{"un":"Girls' shoes should be fancy, not comfy.","re":"Comfy sports shoes suit girls running and playing.","why":"Shoes are for moving well, not for following a look-rule."},"relearn":"Girls pick comfy shoes for play, not just fancy ones.","persona":"Diya","source":"clothing"},
  {"id":"fs-1273","cat":"looks-stuff","type":"strike-rewrite","hook":"\"A boy can't carry a purple school bag.\"","myth":{"un":"Boys can't use purple or pink bags.","re":"A bag's colour is just a colour; carry what you like.","why":"Colours on objects have no gender."},"relearn":"Any colour bag is fine for any kid.","persona":"any","source":"stuff / colours"},
  {"id":"fs-1274","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Only girls can have a tidy, decorated room.\"","myth":{"un":"Decorating your room is a girl thing.","re":"Anyone can make their space cosy and nice.","why":"Caring how your room looks isn't a gender rule."},"relearn":"Decorating your space is for anyone.","persona":"any","source":"identity"},
  {"id":"fs-1275","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Boys shouldn't care how they look.\"","myth":{"un":"Boys shouldn't bother about their appearance.","re":"Anyone can enjoy looking neat and feeling good.","why":"Liking how you look isn't owned by a gender."},"relearn":"Caring about your look is okay for anyone.","persona":"Aarav","source":"appearance"},
  {"id":"fs-1276","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Skipping ropes are for girls; cricket bats for boys.\"","myth":{"un":"Some play things belong to one gender.","re":"Any kid can skip rope or swing a bat for fun.","why":"Play gear is for the game, not for a gender."},"relearn":"Skipping and cricket gear are for any kid.","persona":"any","source":"toys / play"},
  {"id":"fs-1277","cat":"looks-stuff","type":"strike-rewrite","hook":"\"Boys can't tie their hair in a bun or braid.\"","myth":{"un":"Buns and braids aren't for boys.","re":"Anyone can tie hair in a bun or braid to keep it tidy.","why":"How you wear your hair is your choice, not a gender rule."},"relearn":"Buns and braids are for anyone who likes them.","persona":"Aarav","source":"appearance"},
  {"id":"fs-1278","cat":"looks-stuff","type":"sort","hook":"Sort each line: a fair idea, or a made-up gender rule?","items":[{"id":"a","text":"\"A doctor kit is for any kid\""},{"id":"b","text":"\"Only girls can skip rope\""},{"id":"c","text":"\"Crayons are for everyone\""},{"id":"d","text":"\"Toy planes are just for boys\""},{"id":"e","text":"\"Anyone can wear bangles\""},{"id":"f","text":"\"Footballs aren't for girls\""}],"bins":[{"id":"fair","label":"Fair idea","valence":"pos"},{"id":"rule","label":"Made-up gender rule","valence":"neg"}],"key":{"a":"fair","b":"rule","c":"fair","d":"rule","e":"fair","f":"rule"},"relearn":"Every toy and item is for any kid; gender rules on them are made up.","persona":"any","source":"stuff / gender"},
  {"id":"fs-1279","cat":"looks-stuff","type":"sort","hook":"Sort: a made-up look-rule, or a real reason?","items":[{"id":"a","text":"\"Boys can't wear yellow\""},{"id":"b","text":"\"Tie long hair back near a stove\""},{"id":"c","text":"\"Girls can't wear caps\""},{"id":"d","text":"\"Wear shoes on a rocky path\""},{"id":"e","text":"\"Pink bags are only for girls\""},{"id":"f","text":"\"Wear your school uniform on school days\""}],"bins":[{"id":"madeup","label":"Made-up rule","valence":"neg"},{"id":"real","label":"Real reason","valence":"pos"}],"key":{"a":"madeup","b":"real","c":"madeup","d":"real","e":"madeup","f":"real"},"relearn":"Gendered look-rules are made up; safety and uniform rules have real reasons.","persona":"any","source":"rules / gender"},
  {"id":"fs-1280","cat":"looks-stuff","type":"sort","hook":"Sort each statement: true or made up?","items":[{"id":"a","text":"Anyone can like any colour"},{"id":"b","text":"Wearing blue makes you a boy"},{"id":"c","text":"Hair length is a personal choice"},{"id":"d","text":"Dolls turn boys into girls"},{"id":"e","text":"Comfort decides good clothes"},{"id":"f","text":"Liking pink changes who you are"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"madeup","label":"Made up","valence":"neg"}],"key":{"a":"true","b":"madeup","c":"true","d":"madeup","e":"true","f":"madeup"},"relearn":"Colours, clothes and toys don't change who you are.","persona":"any","source":"colours / identity"},
  {"id":"fs-1281","cat":"looks-stuff","type":"sort","hook":"Sort: is each clothing choice about comfort, or a gender rule?","items":[{"id":"a","text":"\"Wear shorts because it's hot\""},{"id":"b","text":"\"Only girls wear leggings\""},{"id":"c","text":"\"Pick warm clothes for winter\""},{"id":"d","text":"\"Boys can't wear bright kurtas\""},{"id":"e","text":"\"Choose comfy shoes to run\""},{"id":"f","text":"\"Girls must wear dupattas to play\""}],"bins":[{"id":"comfort","label":"About comfort","valence":"pos"},{"id":"rule","label":"A made-up gender rule","valence":"neg"}],"key":{"a":"comfort","b":"rule","c":"comfort","d":"rule","e":"comfort","f":"rule"},"relearn":"Clothes are about comfort and choice, not gender rules.","persona":"any","source":"clothing"},
  {"id":"fs-1282","cat":"looks-stuff","type":"sort","hook":"Sort each hair fact: true or made up?","items":[{"id":"a","text":"Long hair has been worn by all genders"},{"id":"b","text":"Short hair makes a girl less of a girl"},{"id":"c","text":"Hair length is a personal choice"},{"id":"d","text":"Boys with long hair did something wrong"},{"id":"e","text":"A braid suits anyone who likes it"},{"id":"f","text":"Only girls are allowed plaits"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"madeup","label":"Made up","valence":"neg"}],"key":{"a":"true","b":"madeup","c":"true","d":"madeup","e":"true","f":"madeup"},"relearn":"Hair length and style are personal choices for everyone.","persona":"any","source":"appearance / history"},
  {"id":"fs-1283","cat":"looks-stuff","type":"sort","hook":"Sort each line: open to anyone, or a made-up 'locked' rule?","items":[{"id":"a","text":"\"Anyone can wear a flower in their hair\""},{"id":"b","text":"\"Toy trains are only for boys\""},{"id":"c","text":"\"A green tiffin suits any kid\""},{"id":"d","text":"\"Nail art is just for girls\""},{"id":"e","text":"\"Any child can keep a doll\""},{"id":"f","text":"\"Caps aren't for girls\""}],"bins":[{"id":"free","label":"Open to anyone","valence":"pos"},{"id":"locked","label":"Made-up 'locked' rule","valence":"neg"}],"key":{"a":"free","b":"locked","c":"free","d":"locked","e":"free","f":"locked"},"relearn":"These choices are open to anyone; 'locked to a gender' rules are made up.","persona":"any","source":"stuff / choice"},
  {"id":"fs-1284","cat":"looks-stuff","type":"sort","hook":"Sort: a real reason for a clothing rule, or a made-up gender one?","items":[{"id":"a","text":"\"Wear a helmet on a cycle\""},{"id":"b","text":"\"Boys can't wear anklets\""},{"id":"c","text":"\"Cover up in strong sun\""},{"id":"d","text":"\"Girls must always wear pink\""},{"id":"e","text":"\"Slip off shoes inside the temple\""},{"id":"f","text":"\"Only boys can wear shorts\""}],"bins":[{"id":"real","label":"Real reason","valence":"pos"},{"id":"madeup","label":"Made-up gender rule","valence":"neg"}],"key":{"a":"real","b":"madeup","c":"real","d":"madeup","e":"real","f":"madeup"},"relearn":"Safety and respect rules are real; gender look-rules are made up.","persona":"any","source":"rules / culture"},
  {"id":"fs-1285","cat":"looks-stuff","type":"sort","hook":"Sort each toy line: fair, or a made-up gender rule?","items":[{"id":"a","text":"\"Puzzles are for any kid\""},{"id":"b","text":"\"Toy cars are just for boys\""},{"id":"c","text":"\"Any kid can have a baby doll\""},{"id":"d","text":"\"Cricket sets aren't for girls\""},{"id":"e","text":"\"Toy kitchens suit everyone\""},{"id":"f","text":"\"Paints are a girls' thing\""}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"rule","label":"Made-up gender rule","valence":"neg"}],"key":{"a":"fair","b":"rule","c":"fair","d":"rule","e":"fair","f":"rule"},"relearn":"Every toy is for any kid; gender rules on toys are made up.","persona":"any","source":"toys"},
  {"id":"fs-1286","cat":"looks-stuff","type":"sort","hook":"Sort each line: true about colours, or a made-up gender rule?","items":[{"id":"a","text":"\"Anyone can pick a pink cycle\""},{"id":"b","text":"\"Purple raincoats are for girls\""},{"id":"c","text":"\"Any kid can carry a blue lunchbox\""},{"id":"d","text":"\"Yellow caps aren't for boys\""},{"id":"e","text":"\"A red kite is for whoever likes it\""},{"id":"f","text":"\"Boys must pick dark colours\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"rule","label":"Made-up gender rule","valence":"neg"}],"key":{"a":"true","b":"rule","c":"true","d":"rule","e":"true","f":"rule"},"relearn":"Colours on things have no gender; pick what you like.","persona":"any","source":"colours"},
  {"id":"fs-1287","cat":"looks-stuff","type":"sort","hook":"Sort each idea about clothes: true or made up?","items":[{"id":"a","text":"Comfort is what makes clothes good"},{"id":"b","text":"Only girls can wear bright colours"},{"id":"c","text":"Anyone can wear trousers"},{"id":"d","text":"Frilly clothes change who you are"},{"id":"e","text":"You choose clothes for the weather"},{"id":"f","text":"Boys who wear yellow look wrong"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"madeup","label":"Made up","valence":"neg"}],"key":{"a":"true","b":"madeup","c":"true","d":"madeup","e":"true","f":"madeup"},"relearn":"Good clothes are about comfort and weather, not gender.","persona":"any","source":"clothing"},
  {"id":"fs-1288","cat":"looks-stuff","type":"sort","hook":"Sort: free choice, or a made-up gender rule?","items":[{"id":"a","text":"\"I'll grow my hair long\""},{"id":"b","text":"\"Boys can't keep long hair\""},{"id":"c","text":"\"I like my blue dupatta\""},{"id":"d","text":"\"Dolls aren't for boys\""},{"id":"e","text":"\"I'll wear my comfy shorts\""},{"id":"f","text":"\"Pink isn't a boy colour\""}],"bins":[{"id":"choice","label":"Free choice","valence":"pos"},{"id":"rule","label":"Made-up rule","valence":"neg"}],"key":{"a":"choice","b":"rule","c":"choice","d":"rule","e":"choice","f":"rule"},"relearn":"Your looks are your free choice; gender look-rules are made up.","persona":"any","source":"identity / rules"},
  {"id":"fs-1289","cat":"looks-stuff","type":"sort","hook":"Sort each shop sign: fair, or a made-up split?","items":[{"id":"a","text":"\"Toys, this way\""},{"id":"b","text":"\"Girls' aisle: pink only\""},{"id":"c","text":"\"School shoes here\""},{"id":"d","text":"\"Boys' toys: no dolls\""},{"id":"e","text":"\"Raincoats in all colours\""},{"id":"f","text":"\"Pink bikes for girls\""}],"bins":[{"id":"fair","label":"Fair sign","valence":"pos"},{"id":"split","label":"Made-up gender split","valence":"neg"}],"key":{"a":"fair","b":"split","c":"fair","d":"split","e":"fair","f":"split"},"relearn":"Splitting shops by pink-girl, blue-boy is a made-up divide.","persona":"any","source":"media literacy / retail"},
  {"id":"fs-1290","cat":"looks-stuff","type":"sort","hook":"Sort: does each rule have a real reason or just a gender one?","items":[{"id":"a","text":"\"Wear a raincoat in the rain\""},{"id":"b","text":"\"Girls can't wear caps\""},{"id":"c","text":"\"Tie shoelaces so you don't trip\""},{"id":"d","text":"\"Boys can't carry pink\""},{"id":"e","text":"\"Wear warm socks in winter\""},{"id":"f","text":"\"Only girls can have soft toys\""}],"bins":[{"id":"real","label":"Real reason","valence":"pos"},{"id":"gender","label":"Just a gender rule","valence":"neg"}],"key":{"a":"real","b":"gender","c":"real","d":"gender","e":"real","f":"gender"},"relearn":"Safety and weather rules are real; gender look-rules aren't.","persona":"any","source":"rules"},
  {"id":"fs-1291","cat":"looks-stuff","type":"sort","hook":"Sort each line: open to all, or a made-up 'boxed' rule?","items":[{"id":"a","text":"\"Anyone can wear a watch\""},{"id":"b","text":"\"Sparkly pencil boxes are for girls\""},{"id":"c","text":"\"Any kid can carry a guitar\""},{"id":"d","text":"\"Friendship bands aren't for boys\""},{"id":"e","text":"\"A green schoolbag suits anyone\""},{"id":"f","text":"\"Only girls keep neat nails\""}],"bins":[{"id":"all","label":"Open to all","valence":"pos"},{"id":"boxed","label":"Made-up 'boxed' rule","valence":"neg"}],"key":{"a":"all","b":"boxed","c":"all","d":"boxed","e":"all","f":"boxed"},"relearn":"These are open to anyone; 'boxed by gender' rules are made up.","persona":"any","source":"stuff / choice"},
  {"id":"fs-1292","cat":"looks-stuff","type":"spot","hook":"A toy shop banner. Spot the made-up splits.","scene":[{"id":"a","text":"\"Dolls and kitchens: Girls' corner\"","trick":true},{"id":"b","text":"\"Trains and tools: Boys' corner\"","trick":true},{"id":"c","text":"\"New toys arrived this week\"","trick":false},{"id":"d","text":"\"Sale on all puzzles\"","trick":false},{"id":"e","text":"\"Toys for ages 9 to 12\"","trick":false}],"why":"Splitting toys into girls' and boys' corners is a made-up divide; any kid can play with any toy.","relearn":"Toy shops often split toys by gender; spot the made-up corners.","persona":"any","source":"media literacy / retail"},
  {"id":"fs-1293","cat":"looks-stuff","type":"spot","hook":"A clothing rack's signs. Spot the gender look-rules.","scene":[{"id":"a","text":"\"Pink frocks only for girls\"","trick":true},{"id":"b","text":"\"No bright colours for boys\"","trick":true},{"id":"c","text":"\"All sizes available\"","trick":false},{"id":"d","text":"\"Cotton clothes for summer\"","trick":false},{"id":"e","text":"\"Wash in cold water\"","trick":false}],"why":"Locking colours and styles to a gender is a made-up rule; clothes are about comfort and choice.","relearn":"Clothing signs often push gender look-rules; spot the made-up ones.","persona":"any","source":"media literacy / retail"},
  {"id":"fs-1294","cat":"looks-stuff","type":"spot","hook":"A school noticeboard. Spot the made-up gender rules.","scene":[{"id":"a","text":"\"Girls only: keep hair long\"","trick":true},{"id":"b","text":"\"Boys can't wear coloured bands\"","trick":true},{"id":"c","text":"\"Tie hair back in the science lab\"","trick":false},{"id":"d","text":"\"Wear school shoes daily\"","trick":false},{"id":"e","text":"\"Sports day is on Friday\"","trick":false}],"why":"Hair length and colour bands aren't gender rules; tying hair back near equipment is a real safety reason.","relearn":"Spot the made-up gender rules among the real safety ones.","persona":"any","source":"media literacy / school"},
  {"id":"fs-1295","cat":"looks-stuff","type":"spot","hook":"A party invite. Spot the gender splits.","scene":[{"id":"a","text":"\"Boys: come as superheroes\"","trick":true},{"id":"b","text":"\"Girls: come as princesses\"","trick":true},{"id":"c","text":"\"Games start at four\"","trick":false},{"id":"d","text":"\"Cake and snacks for all\"","trick":false},{"id":"e","text":"\"Bring your dancing shoes\"","trick":false}],"why":"Splitting costumes by gender is made up; any kid can be a superhero or a princess.","relearn":"Party invites often split themes by gender; spot the made-up split.","persona":"any","source":"media literacy / products"},
  {"id":"fs-1296","cat":"looks-stuff","type":"spot","hook":"An online toy advert. Spot the stereotype lines.","scene":[{"id":"a","text":"\"Real boys build, they don't cuddle dolls\"","trick":true},{"id":"b","text":"\"Sweet girls love tea sets, not tools\"","trick":true},{"id":"c","text":"\"Free delivery this week\"","trick":false},{"id":"d","text":"\"Safe, sturdy and easy to clean\"","trick":false},{"id":"e","text":"\"Loved by kids everywhere\"","trick":false}],"why":"Telling boys not to cuddle dolls and girls not to use tools is a made-up script; any kid can do both.","relearn":"Ads often slip in gender scripts; spot the stereotype lines.","persona":"any","source":"media literacy / ads"},
  {"id":"fs-1297","cat":"looks-stuff","type":"spot","hook":"A stationery shop wall. Spot the gendered splits.","scene":[{"id":"a","text":"\"Glitter pens: for girls\"","trick":true},{"id":"b","text":"\"Plain pencils: boys' side\"","trick":true},{"id":"c","text":"\"Notebooks half price\"","trick":false},{"id":"d","text":"\"Erasers in every shape\"","trick":false},{"id":"e","text":"\"Open till eight today\"","trick":false}],"why":"Glitter pens and plain pencils aren't gendered; any kid can pick what they like.","relearn":"Even stationery gets split by gender; spot the made-up sides.","persona":"any","source":"media literacy / retail"},
  {"id":"fs-1298","cat":"looks-stuff","type":"spot","hook":"A cousin's comments at a family lunch. Spot the look-rule jabs.","scene":[{"id":"a","text":"\"Pink? That's a girl's plate, swap it\"","trick":true},{"id":"b","text":"\"Boys shouldn't wear those beads\"","trick":true},{"id":"c","text":"\"Pass the dal, please\"","trick":false},{"id":"d","text":"\"This sabzi is really tasty\"","trick":false},{"id":"e","text":"\"Let's play after lunch\"","trick":false}],"why":"A plate's colour and a string of beads have no gender; these jabs push made-up look-rules.","relearn":"Look-rule jabs sneak into everyday talk; spot them kindly.","persona":"any","source":"everyday / family"},
  {"id":"fs-1299","cat":"looks-stuff","type":"spot","hook":"A kids' magazine page. Spot the made-up gender lines.","scene":[{"id":"a","text":"\"Style tips: girls, always look pretty\"","trick":true},{"id":"b","text":"\"Boys, rough and tough only\"","trick":true},{"id":"c","text":"\"Puzzle of the month inside\"","trick":false},{"id":"d","text":"\"Meet a young chess champ\"","trick":false},{"id":"e","text":"\"Send us your drawings\"","trick":false}],"why":"\"Always look pretty\" and \"rough and tough only\" are made-up scripts; kids are all sorts of things.","relearn":"Magazines slip in gender scripts; spot the made-up lines.","persona":"any","source":"media literacy / print"},
  {"id":"fs-1300","cat":"looks-stuff","type":"spot","hook":"A footwear shop sign. Spot the gender look-rules.","scene":[{"id":"a","text":"\"Heels and bows: girls only\"","trick":true},{"id":"b","text":"\"No pink shoes for boys\"","trick":true},{"id":"c","text":"\"Sports shoes, all sizes\"","trick":false},{"id":"d","text":"\"Try before you buy\"","trick":false},{"id":"e","text":"\"Rain boots in stock\"","trick":false}],"why":"Locking shoe styles and colours to a gender is made up; shoes are about comfort and the task.","relearn":"Shoe shops push gender look-rules too; spot the made-up ones.","persona":"any","source":"media literacy / retail"},
  {"id":"fs-1301","cat":"looks-stuff","type":"match","hook":"Match each item to the truth about it.","pairs":[{"left":"A pink t-shirt","right":"A colour anyone can wear"},{"left":"A doctor toy kit","right":"Play that suits any kid"},{"left":"Long hair","right":"A personal style choice"},{"left":"A pair of trousers","right":"Comfy clothing for everyone"},{"left":"A set of bangles","right":"A decoration anyone may like"}],"relearn":"Colours, toys, hair and clothes aren't owned by one gender.","persona":"any","source":"stuff / gender"},
  {"id":"fs-1302","cat":"looks-stuff","type":"match","hook":"Match each made-up look-rule to the fair flip.","pairs":[{"left":"\"Pink is only for girls\"","right":"Colours are for everyone"},{"left":"\"Boys can't have long hair\"","right":"Hair length is a free choice"},{"left":"\"Dolls aren't for boys\"","right":"Any kid can play with dolls"},{"left":"\"Girls must wear dresses\"","right":"Wear whatever is comfy"},{"left":"\"Sparkle is girly\"","right":"Anyone can enjoy sparkle"}],"relearn":"Every made-up look-rule has a fair flip; the choice is yours.","persona":"any","source":"flips / looks"},
  {"id":"fs-1303","cat":"looks-stuff","type":"match","hook":"Match each item to who it's really for.","pairs":[{"left":"A skipping rope","right":"Any kid who wants to play"},{"left":"A toy aeroplane","right":"Any kid who loves to fly it"},{"left":"A hair clip","right":"Anyone keeping hair tidy"},{"left":"A friendship band","right":"Anyone who likes wearing it"},{"left":"A green water bottle","right":"Whoever picks that colour"}],"relearn":"None of these belongs to one gender; they're for anyone.","persona":"any","source":"stuff / gender"},
  {"id":"fs-1304","cat":"looks-stuff","type":"match","hook":"Match the clothing choice to its real reason.","pairs":[{"left":"Wearing a cap outdoors","right":"To block the strong sun"},{"left":"Choosing comfy shorts","right":"To run and play freely"},{"left":"Tying hair back","right":"To stay safe near a stove"},{"left":"Wearing warm socks","right":"To keep cosy in winter"},{"left":"Slipping off shoes inside","right":"To respect the home"}],"relearn":"Clothing choices have real reasons, never a gender rule.","persona":"any","source":"clothing / reasons"},
  {"id":"fs-1305","cat":"looks-stuff","type":"match","hook":"Match each kid's choice to a fair way to see it.","pairs":[{"left":"A boy keeps a soft toy","right":"Comfort is for everyone"},{"left":"A girl plays cricket","right":"Sport is for everyone"},{"left":"A boy paints his nails","right":"A fun choice anyone can make"},{"left":"A girl cuts her hair short","right":"Her hair, her choice"},{"left":"A boy wears a yellow shirt","right":"Colours are for everyone"}],"relearn":"Each choice is fair and free; none breaks a real rule.","persona":"any","source":"choice / fairness"},
  {"id":"fs-1306","cat":"looks-stuff","type":"match","hook":"Match each colour myth to what's actually true.","pairs":[{"left":"\"Blue means a boy\"","right":"Colours don't decide gender"},{"left":"\"Pink was always for girls\"","right":"Pink was once a 'boy' colour"},{"left":"\"Colours have a gender\"","right":"Colour rules are made up"},{"left":"\"Liking purple is girly\"","right":"Anyone can love any colour"},{"left":"\"Boys must pick dark shades\"","right":"Bright or dark, your choice"}],"relearn":"Colour-gender links are invented and they keep changing.","persona":"any","source":"colours / history"},
  {"id":"fs-1307","cat":"looks-stuff","type":"match","hook":"Match each shop split to the fair truth.","pairs":[{"left":"\"Girls' pink aisle\"","right":"Colours suit any kid"},{"left":"\"Boys' toys: no dolls\"","right":"Dolls are for any kid"},{"left":"\"Princess party for girls\"","right":"Any kid can pick any theme"},{"left":"\"Tools for boys only\"","right":"Tools are for everyone"},{"left":"\"Sparkly stuff for girls\"","right":"Sparkle is for anyone"}],"relearn":"Shop splits by gender are made up; any kid can pick anything.","persona":"any","source":"media literacy / retail"},
  {"id":"fs-1308","cat":"looks-stuff","type":"reflect","hook":"Lensy: think of a colour you love. Does it change who you are? (No.)","prompt":"What do you think?","options":["No, I'm still me","It's just a colour I like","A colour can't decide that"],"affirm":"A colour you love is yours to enjoy; it never changes who you are.","relearn":"Loving a colour is yours; it doesn't decide who you are.","persona":"any","source":"colours / identity"},
  {"id":"fs-1309","cat":"looks-stuff","type":"reflect","hook":"Lensy: picture a toy box with no 'girls'/'boys' labels. What would you grab?","prompt":"What do you think?","options":["Whatever looks fun","A bit of everything","The one I always wanted"],"affirm":"Without labels, every toy is open to you; grab whatever sparks joy.","relearn":"Drop the labels and every toy is yours to try.","persona":"any","source":"toys / freedom"},
  {"id":"fs-1310","cat":"looks-stuff","type":"reflect","hook":"Lensy: who does it really hurt if you wear what feels comfy? (No one.)","prompt":"What do you think?","options":["No one at all","It's my comfort","Just me, and I'm happy"],"affirm":"Wearing what feels comfy harms no one; comfort is a fair reason.","relearn":"Comfy clothes hurt no one; comfort is a good enough reason.","persona":"any","source":"clothing / choice"},
  {"id":"fs-1311","cat":"looks-stuff","type":"reflect","hook":"Lensy: your hair, your way. Long, short or tied, how do you like it?","prompt":"What do you think?","options":["Long and free","Short and easy","Tied up neatly"],"affirm":"Your hair is yours to wear any way; every choice here is fair.","relearn":"Hair length and style are yours to choose, freely.","persona":"any","source":"appearance"},
  {"id":"fs-1312","cat":"looks-stuff","type":"reflect","hook":"Lensy: a kid keeps a soft toy for comfort. Is that okay for anyone?","prompt":"What do you think?","options":["Yes, comfort is for all","Of course it is","Anyone can, sure"],"affirm":"Comfort isn't owned by a gender or an age; a soft toy is fine for anyone.","relearn":"Soft toys comfort anyone; that's always okay.","persona":"any","source":"toys / comfort"},
  {"id":"fs-1313","cat":"looks-stuff","type":"reflect","hook":"Lensy: imagine telling a younger cousin all colours are theirs. How might they feel?","prompt":"What do you think?","options":["Free to choose","Happy and relaxed","Like nothing's off-limits"],"affirm":"Telling a younger kid all colours are theirs can free them; that's a kind gift.","relearn":"Sharing that colours are for everyone frees a younger kid.","persona":"any","source":"call-out / kindness"},
  {"id":"fs-1314","cat":"looks-stuff","type":"reflect","hook":"Lensy: think of one item you were told 'wasn't for you'. Want to try it anyway?","prompt":"What do you think?","options":["Yes, why not","I'd give it a go","It's my choice to make"],"affirm":"If you like it, it can be for you; the 'wasn't for you' rule was made up.","relearn":"An item is yours to try if you like it; the rule was invented.","persona":"any","source":"identity / choice"},
  {"id":"fs-1315","cat":"looks-stuff","type":"reflect","hook":"Lensy: if a friend likes a colour you don't, is that fine?","prompt":"What do you think?","options":["Totally fine","Their taste, their choice","Yes, we're different"],"affirm":"Different tastes are great; a friend's colour choice is theirs to enjoy.","relearn":"Friends can like different things; every taste is fair.","persona":"any","source":"friendship / choice"},
  {"id":"fs-1316","cat":"looks-stuff","type":"reflect","hook":"Lensy: picture a world where shops don't split toys by gender. Better?","prompt":"What do you think?","options":["Yes, much fairer","Everyone's welcome then","I'd explore it all"],"affirm":"A shop that doesn't split toys by gender lets every kid explore freely; that's fairer.","relearn":"Shops without gender splits free every kid to explore.","persona":"any","source":"retail / fairness"},
  {"id":"fs-1317","cat":"looks-stuff","type":"branch","hook":"A friend says, \"Drop that pink pencil, it's a girls' colour.\" What do you do?","options":[{"text":"Say, \"Colours are for everyone, na? I like this one.\"","consequence":"Calm and kind; your friend rethinks it.","best":true},{"text":"Quietly swap it to avoid teasing.","consequence":"The made-up rule wins this time."}],"debrief":"Colours are for everyone; a kind line flips the rule without a fight.","relearn":"Saying colours are for everyone, kindly, flips the rule.","persona":"any","source":"call-out / colours"},
  {"id":"fs-1318","cat":"looks-stuff","type":"branch","hook":"A shopkeeper says, \"Dolls are in the girls' aisle, beta.\" You want one. What now?","options":[{"text":"Say, \"Dolls are for any kid, I'll take this one.\"","consequence":"Friendly and clear; you get your doll.","best":true},{"text":"Leave the doll, feeling embarrassed.","consequence":"You miss the toy; the split stands."}],"debrief":"Any kid can play with dolls; a calm line gets the toy and questions the split.","relearn":"A calm line questions the split and gets you the toy.","persona":"any","source":"call-out / toys"},
  {"id":"fs-1319","cat":"looks-stuff","type":"branch","hook":"Cousins laugh that you, a boy, grew your hair long. How do you handle it?","options":[{"text":"Smile: \"My hair, my choice, I like it long.\"","consequence":"You stay relaxed; the teasing loses its sting.","best":true},{"text":"Rush to cut it so they stop.","consequence":"You drop a choice you liked for a made-up rule."}],"debrief":"Hair length is a personal choice; a calm reply keeps your choice and your cool.","relearn":"A calm reply keeps your hair choice and your cool.","persona":"Aarav","source":"call-out / appearance"},
  {"id":"fs-1320","cat":"looks-stuff","type":"branch","hook":"A classmate teases a girl for wearing trousers, not a skirt. What do you do?","options":[{"text":"Say, \"Trousers are comfy and fine, na? Let her be.\"","consequence":"You back her up; the teasing stops.","best":true},{"text":"Stay silent to avoid being teased.","consequence":"She stands alone; the rule sticks."}],"debrief":"Clothes are about comfort and choice; speaking up kindly for her helps flip it.","relearn":"Speaking up kindly for someone helps flip a clothing rule.","persona":"any","source":"call-out / clothing"},
  {"id":"fs-1321","cat":"looks-stuff","type":"branch","hook":"You spot an ad: \"Tool kits for boys, tea sets for girls.\" What might you do?","options":[{"text":"Tell a friend, \"Both are for any kid, na? That split's made up.\"","consequence":"You name it calmly; your friend spots it too.","best":true},{"text":"Believe it; pick only the 'boy' toy.","consequence":"The split decides; your choice shrinks."}],"debrief":"Ads often split toys by gender; naming it kindly helps others see the rule.","relearn":"Naming an ad's gender split helps others spot it.","persona":"any","source":"call-out / ads"},
  {"id":"fs-1322","cat":"looks-stuff","type":"branch","hook":"At a party, a host says, \"Boys this side, girls that side, by costume.\" What now?","options":[{"text":"Ask kindly, \"Can we pick any costume we like?\"","consequence":"A gentle question opens it up; kids mix and enjoy more.","best":true},{"text":"Go where you're told, wrong costume.","consequence":"You follow the split and miss your costume."}],"debrief":"Any kid can pick any theme; a kind question can open the whole party up.","relearn":"A kind question can open a gender-split party up.","persona":"any","source":"call-out / parties"},
  {"id":"fs-1323","cat":"looks-stuff","type":"branch","hook":"Your little brother says, \"I can't like purple, it's a girls' colour.\" What do you say?","options":[{"text":"\"Purple's for anyone. Pick it if you love it.\"","consequence":"You free him from the rule; he keeps his purple.","best":true},{"text":"\"Yeah, better pick blue to be safe.\"","consequence":"You pass the rule down; he drops it."}],"debrief":"Colours are for everyone; reassuring a younger kid flips the rule for them too.","relearn":"Reassuring a younger kid flips a colour rule for them.","persona":"any","source":"call-out / colours"},
  {"id":"fs-1324","cat":"looks-stuff","type":"branch","hook":"A friend wants to share a meme mocking a boy for his pink shoes. Join in?","options":[{"text":"Say, \"I'd rather not, pink shoes are totally fine.\"","consequence":"You don't spread it; your friend rethinks sharing it.","best":true},{"text":"Forward it for a quick laugh.","consequence":"The mocking spreads and gets louder."}],"debrief":"You can refuse to spread stereotype-mocking; pink shoes are for anyone.","relearn":"You can refuse to spread a meme that mocks a look.","persona":"any","source":"call-out / online"},
  {"id":"fs-1325","cat":"looks-stuff","type":"role-play","hook":"A shopkeeper steers you to the 'right' aisle by gender.","setup":"You want a toy kitchen, but the shopkeeper points you to the 'boys' aisle. Say it kindly.","yourLine":[{"text":"\"I'd like this toy kitchen, please, cooking's fun for any kid.\"","best":true},{"text":"\"Oh... okay, I'll just look over there then.\""}],"persona":"any","source":"call-out / toys","relearn":"Any kid can play cooking; a kind line gets you the toy you want."},
  {"id":"fs-1326","cat":"looks-stuff","type":"role-play","hook":"A cousin laughs at your friend's long hair.","setup":"Your cousin says boys shouldn't have long hair. Stand up for your friend, kindly.","yourLine":[{"text":"\"His hair, his choice, na? It looks great and that's all that matters.\"","best":true},{"text":"\"Heh, yeah, maybe he should cut it.\""}],"persona":"Asha","source":"call-out / appearance","relearn":"Hair length is a personal choice; a kind line backs your friend up."},
  {"id":"fs-1327","cat":"looks-stuff","type":"role-play","hook":"A classmate teases you, a girl, for short hair.","setup":"They say short hair means you're 'not really a girl'. Reply, calm and clear.","yourLine":[{"text":"\"It's my hair and I like it short, that doesn't change who I am.\"","best":true},{"text":"\"Maybe I'll grow it back so you stop.\""}],"persona":"Diya","source":"call-out / appearance","relearn":"Short hair doesn't change who a girl is; her hair, her choice."},
  {"id":"fs-1328","cat":"looks-stuff","type":"role-play","hook":"A friend says your purple bag is 'too girly'.","setup":"They tease you about the colour of your school bag. Say your line, easy and sure.","yourLine":[{"text":"\"It's just a colour I like, na? Purple's for anyone.\"","best":true},{"text":"\"Ugh, fine, I'll ask for a different one.\""}],"persona":"any","source":"call-out / colours","relearn":"Colours on things have no gender; pick the one you like."},
  {"id":"fs-1329","cat":"looks-stuff","type":"role-play","hook":"Someone mocks a boy at the party for his sparkly slippers.","setup":"A kid laughs at your friend's sparkly slippers. Speak up, kindly.","yourLine":[{"text":"\"They're cool, na? Anyone can like a bit of sparkle.\"","best":true},{"text":"\"Heh, yeah, they are a bit much.\""}],"persona":"Asha","source":"call-out / appearance","relearn":"Anyone can enjoy sparkle; a kind line backs a friend up."},
  {"id":"fs-1330","cat":"looks-stuff","type":"role-play","hook":"A relative tells your little sister to swap her 'boyish' toy car.","setup":"They want her to pick a doll instead. Speak up for her, gently.","yourLine":[{"text":"\"She loves her car, na? Any kid can play with cars.\"","best":true},{"text":"\"Okay, maybe she'll like the doll more.\""}],"persona":"any","source":"call-out / toys","relearn":"Any kid can play with toy cars; back a younger kid kindly."},
  {"id":"fs-1331","cat":"looks-stuff","type":"role-play","hook":"A shop has a 'pink for girls, blue for boys' bottle stand.","setup":"The seller says you must pick the 'boys' colour. Choose freely, kindly.","yourLine":[{"text":"\"I'll take the pink one, please, colours are for anyone.\"","best":true},{"text":"\"Oh, alright, I'll just take the blue then.\""}],"persona":"any","source":"call-out / retail","relearn":"A colour on a bottle has no gender; pick the one you want."},
  {"id":"fs-1332","cat":"looks-stuff","type":"role-play","hook":"A friend says boys can't wear the friendship band you made.","setup":"They claim the colourful band is 'just for girls'. Reply, light and sure.","yourLine":[{"text":"\"It's a friendship band, na? Anyone who likes it can wear it.\"","best":true},{"text":"\"Hmm, maybe I'll make a plainer one for boys.\""}],"persona":"any","source":"call-out / stuff","relearn":"Friendship bands are for anyone; a kind line flips the rule."},
  {"id":"fs-1350","type":"spot","hook":"A washing-powder ad. Spot the stereotype.","scene":[{"id":"a","text":"Only the mother and daughter do the laundry","trick":true},{"id":"b","text":"\"Mummy makes everything spotless\"","trick":true},{"id":"c","text":"\"Removes ten kinds of stains\"","trick":false},{"id":"d","text":"A school shirt comes out clean","trick":false},{"id":"e","text":"The advert lasts thirty seconds","trick":false}],"why":"Laundry ads often show only women washing, as if it's not the whole family's job.","relearn":"Detergent ads often stereotype washing as only women's work; spot it.","persona":"Rohit","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-1351","type":"spot","hook":"A kids' cartoon. Spot the stereotype.","scene":[{"id":"a","text":"The girl character only cooks and cleans","trick":true},{"id":"b","text":"The boy character goes on every adventure","trick":true},{"id":"c","text":"They live in a treehouse","trick":false},{"id":"d","text":"There's a talking parrot","trick":false},{"id":"e","text":"The theme song is catchy","trick":false}],"why":"Cartoons often give boys the adventures and girls the chores; both can do both.","relearn":"Cartoons often stereotype boys as adventurers, girls as helpers; spot it.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1352","type":"spot","hook":"A festival sweets ad. Spot the stereotype.","scene":[{"id":"a","text":"\"A good wife makes the perfect laddoo\"","trick":true},{"id":"b","text":"Only the women cook for the whole family","trick":true},{"id":"c","text":"The kitchen smells of cardamom","trick":false},{"id":"d","text":"Diyas glow in the background","trick":false},{"id":"e","text":"\"Made with pure ghee\"","trick":false}],"why":"Festival ads often say women must cook for everyone; cooking is for anyone.","relearn":"Festival ads often stereotype cooking as a wife's duty; spot it.","persona":"Rohit","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-1353","type":"spot","hook":"A back-to-school flyer. Spot the stereotype.","scene":[{"id":"a","text":"The science kit is shown only with boys","trick":true},{"id":"b","text":"The art and craft set is shown only with girls","trick":true},{"id":"c","text":"There's a festive discount on now","trick":false},{"id":"d","text":"School reopens next week","trick":false},{"id":"e","text":"Free delivery is offered","trick":false}],"why":"Flyers often hand science to boys and craft to girls; any kid enjoys either.","relearn":"School ads often stereotype science as 'for boys', craft as 'for girls'; spot it.","persona":"Diya","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-1354","type":"spot","hook":"A perfume advert. Spot the stereotype.","scene":[{"id":"a","text":"\"This scent makes a man irresistible\"","trick":true},{"id":"b","text":"Women instantly crowd around the man","trick":true},{"id":"c","text":"The bottle is shaped like a rocket","trick":false},{"id":"d","text":"The advert is set at night","trick":false},{"id":"e","text":"\"Lasts all day\"","trick":false}],"why":"These ads pretend a product makes a man 'powerful' and women just admirers.","relearn":"Perfume ads often stereotype men as conquerors, women as admirers; spot it.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1355","type":"spot","hook":"A talent-show clip. Spot the stereotype.","scene":[{"id":"a","text":"The judge says \"dancing isn't for boys\"","trick":true},{"id":"b","text":"The crowd laughs at the boy dancer","trick":true},{"id":"c","text":"The stage has bright lights","trick":false},{"id":"d","text":"A girl plays the tabla next","trick":false},{"id":"e","text":"There's a buzzer for each judge","trick":false}],"why":"Shows sometimes mock boys who dance; dance is a skill, not a gender thing.","relearn":"Calling dance 'not for boys' is a stereotype; anyone can dance.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1356","type":"spot","hook":"A bike advert. Spot the stereotype.","scene":[{"id":"a","text":"Only boys are shown riding the cool bike","trick":true},{"id":"b","text":"\"Built for tough lads\"","trick":true},{"id":"c","text":"The bike has a basket","trick":false},{"id":"d","text":"It comes in three colours","trick":false},{"id":"e","text":"\"Strong frame, smooth ride\"","trick":false}],"why":"Bike ads often show only boys riding, as if girls don't ride; everyone rides.","relearn":"Cycle ads often stereotype riding as a boys-only thing; spot it.","persona":"Diya","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1357","type":"spot","hook":"A shampoo advert. Spot the stereotype.","scene":[{"id":"a","text":"\"Long, silky hair is every girl's pride\"","trick":true},{"id":"b","text":"A boy with long hair is shown as 'untidy'","trick":true},{"id":"c","text":"The bottle is purple","trick":false},{"id":"d","text":"\"Fights dandruff\"","trick":false},{"id":"e","text":"A model flicks her hair","trick":false}],"why":"Hair-length rules are made up; long hair suits any kid, and so does short.","relearn":"Ads often stereotype long hair as 'girls only'; hair length is a free choice.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1358","type":"spot","hook":"A board-game box. Spot the stereotype.","scene":[{"id":"a","text":"\"A battle game for brave boys\"","trick":true},{"id":"b","text":"\"A tea-party game for sweet girls\"","trick":true},{"id":"c","text":"It says \"ages eight and up\"","trick":false},{"id":"d","text":"There are colourful counters","trick":false},{"id":"e","text":"Two to four players can play","trick":false}],"why":"Game boxes split play by gender; any kid can battle or host a tea party.","relearn":"Game boxes often stereotype games as 'for boys' or 'for girls'; spot it.","persona":"any","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-1359","type":"spot","hook":"A news report on a flood rescue. Spot the stereotype.","scene":[{"id":"a","text":"It only names the men who helped","trick":true},{"id":"b","text":"It calls the women rescuers \"just helpers\"","trick":true},{"id":"c","text":"Boats carry people to safety","trick":false},{"id":"d","text":"The water is chest-high","trick":false},{"id":"e","text":"Relief food is handed out","trick":false}],"why":"Reports often credit only men in a crisis; women rescue and lead too.","relearn":"News often stereotypes men as the 'real' rescuers; women lead too. Spot it.","persona":"Diya","source":"media literacy / news","cat":"spot-it"},
  {"id":"fs-1360","type":"spot","hook":"A wedding-card design. Spot the stereotype.","scene":[{"id":"a","text":"\"The groom: the family's strong protector\"","trick":true},{"id":"b","text":"\"The bride: a quiet, obedient girl\"","trick":true},{"id":"c","text":"Gold floral borders","trick":false},{"id":"d","text":"The date and venue are printed","trick":false},{"id":"e","text":"A peacock motif at the top","trick":false}],"why":"Cards script grooms as strong and brides as silent; both are full people.","relearn":"Wedding cards often stereotype grooms as strong, brides as quiet; spot it.","persona":"any","source":"media literacy / products","cat":"spot-it"},
  {"id":"fs-1361","type":"spot","hook":"A snack-packet mascot. Spot the stereotype.","scene":[{"id":"a","text":"The 'adventure' snack mascot is only a boy","trick":true},{"id":"b","text":"The 'pretty pink' snack mascot is only a girl","trick":true},{"id":"c","text":"Both packets are crunchy","trick":false},{"id":"d","text":"There's a small free toy inside","trick":false},{"id":"e","text":"\"Baked, not fried\"","trick":false}],"why":"Brands split snacks by gender with their mascots; snacks are for any kid.","relearn":"Snack mascots often stereotype 'adventure for boys, pretty for girls'; spot it.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1362","type":"spot","hook":"A film poster. Spot the stereotype.","scene":[{"id":"a","text":"The hero saves the day with his fists","trick":true},{"id":"b","text":"The heroine only screams and waits","trick":true},{"id":"c","text":"Big bold title at the top","trick":false},{"id":"d","text":"A city skyline behind them","trick":false},{"id":"e","text":"\"In cinemas this Friday\"","trick":false}],"why":"Posters often make the man act and the woman wait; both can be heroes.","relearn":"Posters often stereotype men as action heroes, women as bystanders; spot it.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1363","type":"spot","hook":"A baby-product ad. Spot the stereotype.","scene":[{"id":"a","text":"Only the mother is ever shown feeding the baby","trick":true},{"id":"b","text":"\"A mother's touch is all baby needs\"","trick":true},{"id":"c","text":"The nappy keeps the baby dry","trick":false},{"id":"d","text":"The baby giggles","trick":false},{"id":"e","text":"\"Soft and gentle\"","trick":false}],"why":"Baby ads erase dads from caring; fathers feed and soothe babies too.","relearn":"Baby ads often stereotype care as mothers-only; dads care too. Spot it.","persona":"Rohit","source":"media literacy / defaults","cat":"spot-it"},
  {"id":"fs-1364","type":"spot","hook":"A school-play casting list. Spot the stereotype.","scene":[{"id":"a","text":"\"Doctor: boys only\"","trick":true},{"id":"b","text":"\"Nurse: girls only\"","trick":true},{"id":"c","text":"Rehearsals start Monday","trick":false},{"id":"d","text":"The play is thirty minutes long","trick":false},{"id":"e","text":"Costumes will be provided","trick":false}],"why":"Even a school play can lock roles by gender; any kid can play any role.","relearn":"Casting often stereotypes 'doctor for boys, nurse for girls'; spot it.","persona":"any","source":"media literacy / jobs","cat":"spot-it"},
  {"id":"fs-1365","type":"spot","hook":"A mobile-game ad. Spot the stereotype.","scene":[{"id":"a","text":"The cooking game is labelled \"for girls\"","trick":true},{"id":"b","text":"The racing game is labelled \"for boys\"","trick":true},{"id":"c","text":"Both games are free to start","trick":false},{"id":"d","text":"They have bright cartoon graphics","trick":false},{"id":"e","text":"You can play offline","trick":false}],"why":"App stores tag games by gender; cooking and racing are fun for any kid.","relearn":"Game ads often stereotype 'cooking for girls, racing for boys'; spot it.","persona":"any","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-1366","type":"spot","hook":"A stationery set. Spot the stereotype.","scene":[{"id":"a","text":"The 'engineer' pencil case is sold only to boys","trick":true},{"id":"b","text":"The 'fashion' pencil case is sold only to girls","trick":true},{"id":"c","text":"Both have a sharpener inside","trick":false},{"id":"d","text":"They come with a free eraser","trick":false},{"id":"e","text":"The zip is sturdy","trick":false}],"why":"Stationery gets split too: engineering for boys, fashion for girls. Made up.","relearn":"Stationery often stereotypes dreams by gender; any kid can be anything. Spot it.","persona":"Diya","source":"media literacy / products","cat":"spot-it"},
  {"id":"fs-1367","type":"spot","hook":"A serial scene. Spot the stereotype.","scene":[{"id":"a","text":"The mother-in-law says \"a girl's duty is the kitchen\"","trick":true},{"id":"b","text":"\"A real son never enters the kitchen\"","trick":true},{"id":"c","text":"There's dramatic background music","trick":false},{"id":"d","text":"Tea is being served","trick":false},{"id":"e","text":"The room is full of relatives","trick":false}],"why":"TV serials repeat 'kitchen is a girl's duty'; cooking belongs to everyone.","relearn":"Serials often stereotype the kitchen as a girl's duty; spot it.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1368","type":"spot","hook":"A 'jobs of India' poster. Spot the stereotype.","scene":[{"id":"a","text":"Every pilot drawn is a man","trick":true},{"id":"b","text":"Every teacher drawn is a woman","trick":true},{"id":"c","text":"There's a bus and a train","trick":false},{"id":"d","text":"The poster lists ten jobs","trick":false},{"id":"e","text":"It hangs in the classroom","trick":false}],"why":"Posters often draw pilots as men and teachers as women; both can be either.","relearn":"Job posters often stereotype pilots as men, teachers as women; spot it.","persona":"any","source":"media literacy / jobs","cat":"spot-it"},
  {"id":"fs-1369","type":"spot","hook":"A festival-clothes ad. Spot the stereotype.","scene":[{"id":"a","text":"\"Pink lehengas for our little princesses\"","trick":true},{"id":"b","text":"\"Boys must wear blue, never pink\"","trick":true},{"id":"c","text":"The fabric is described as soft","trick":false},{"id":"d","text":"There's a festive discount","trick":false},{"id":"e","text":"Sizes go from 2 to 12 years","trick":false}],"why":"Clothing ads push pink-for-girls, blue-for-boys; colours are for everyone.","relearn":"Clothing ads often stereotype colours by gender; colours are free. Spot it.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1370","type":"spot","hook":"A 'top scientists' magazine page. Spot the stereotype.","scene":[{"id":"a","text":"It only features male scientists","trick":true},{"id":"b","text":"It calls a woman scientist \"surprisingly clever\"","trick":true},{"id":"c","text":"There are photos of labs","trick":false},{"id":"d","text":"Each entry has a short bio","trick":false},{"id":"e","text":"The page number is at the bottom","trick":false}],"why":"Magazines often leave women scientists out or treat their skill as a surprise.","relearn":"Media often stereotypes science as a male field; girls excel too. Spot it.","persona":"Diya","source":"media literacy / jobs","cat":"spot-it"},
  {"id":"fs-1371","type":"spot","hook":"A reality cooking contest. Spot the stereotype.","scene":[{"id":"a","text":"The host says \"the boys will struggle with delicate work\"","trick":true},{"id":"b","text":"\"Girls are naturally neater cooks\"","trick":true},{"id":"c","text":"The clock counts down","trick":false},{"id":"d","text":"Judges taste each dish","trick":false},{"id":"e","text":"The kitchen has many stations","trick":false}],"why":"Even cooking shows guess by gender; skill in the kitchen isn't gendered.","relearn":"Shows often stereotype cooking skill by gender; it's about practice. Spot it.","persona":"Aarav","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1372","type":"spot","hook":"A toy-shop window. Spot the stereotype.","scene":[{"id":"a","text":"A pink aisle sign says \"Girls' toys\"","trick":true},{"id":"b","text":"A blue aisle sign says \"Boys' toys\"","trick":true},{"id":"c","text":"There's a giant teddy on display","trick":false},{"id":"d","text":"A \"Sale\" banner hangs above","trick":false},{"id":"e","text":"The shop opens at ten","trick":false}],"why":"Shops split aisles by colour and gender; any kid can love any toy.","relearn":"Toy shops often stereotype aisles by gender; toys are for everyone. Spot it.","persona":"any","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-1373","type":"spot","hook":"An action figure advert. Spot the stereotype.","scene":[{"id":"a","text":"\"Dolls are babyish. Real boys want soldiers\"","trick":true},{"id":"b","text":"A boy is teased for holding a doll","trick":true},{"id":"c","text":"The figure has movable arms","trick":false},{"id":"d","text":"It comes with a tiny shield","trick":false},{"id":"e","text":"Batteries are not included","trick":false}],"why":"Ads mock boys with dolls; playing with dolls builds caring in any kid.","relearn":"Ads often stereotype dolls as 'not for boys'; dolls teach care to all. Spot it.","persona":"Aarav","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-1374","type":"spot","hook":"A radio jingle. Spot the stereotype.","scene":[{"id":"a","text":"\"Strong dad earns, sweet mum cooks\"","trick":true},{"id":"b","text":"\"That's how every happy home runs\"","trick":true},{"id":"c","text":"It has a hummable tune","trick":false},{"id":"d","text":"It plays in the morning slot","trick":false},{"id":"e","text":"The advert is for a bank","trick":false}],"why":"Jingles repeat dad-earns, mum-cooks; in fair homes everyone shares the work.","relearn":"Jingles often stereotype dads as earners, mums as cooks; spot it.","persona":"Rohit","source":"media literacy / music","cat":"spot-it"},
  {"id":"fs-1375","type":"spot","hook":"A sports-shoe billboard. Spot the stereotype.","scene":[{"id":"a","text":"Only the boys' team gets the big photo","trick":true},{"id":"b","text":"The girls' team is shrunk to a corner","trick":true},{"id":"c","text":"The shoes are described as light","trick":false},{"id":"d","text":"\"Grip for any ground\"","trick":false},{"id":"e","text":"The brand logo is in the corner","trick":false}],"why":"Even billboards shrink girls' teams; girls compete just as hard.","relearn":"Sports ads often stereotype boys' teams as the main event; spot it.","persona":"Diya","source":"media literacy / sport","cat":"spot-it"},
  {"id":"fs-1376","type":"spot","hook":"A film trailer. Spot the stereotype.","scene":[{"id":"a","text":"\"A girl can't be the team's captain\"","trick":true},{"id":"b","text":"The boys laugh when she tries","trick":true},{"id":"c","text":"There's a football match","trick":false},{"id":"d","text":"The trailer ends on a cliff-hanger","trick":false},{"id":"e","text":"Loud drums play throughout","trick":false}],"why":"Trailers sometimes say girls can't lead a team; leadership is a skill, not a gender.","relearn":"Trailers often stereotype captains as boys; any kid can lead. Spot it.","persona":"Diya","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1377","type":"spot","hook":"A 'gift ideas' webpage. Spot the stereotype.","scene":[{"id":"a","text":"\"For him: tools and gadgets\"","trick":true},{"id":"b","text":"\"For her: kitchenware and jewellery\"","trick":true},{"id":"c","text":"Free gift-wrapping is offered","trick":false},{"id":"d","text":"Prices are listed in rupees","trick":false},{"id":"e","text":"Delivery takes two days","trick":false}],"why":"Gift lists split tools for men and kitchen for women; gifts have no gender.","relearn":"Gift guides often stereotype 'tools for him, kitchen for her'; spot it.","persona":"any","source":"media literacy / defaults","cat":"spot-it"},
  {"id":"fs-1378","type":"spot","hook":"A children's storybook. Spot the stereotype.","scene":[{"id":"a","text":"Only the prince gets to be the clever, brave one","trick":true},{"id":"b","text":"The princess only looks pretty and waits","trick":true},{"id":"c","text":"There's a magic forest","trick":false},{"id":"d","text":"The book has big pictures","trick":false},{"id":"e","text":"It ends with a feast","trick":false}],"why":"Old storybooks make princes act and princesses wait; both can be brave.","relearn":"Storybooks often stereotype princes as brave, princesses as passive; spot it.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1379","type":"spot","hook":"A mobile advert. Spot the stereotype.","scene":[{"id":"a","text":"\"The powerful phone: for the man who leads\"","trick":true},{"id":"b","text":"\"The cute phone: for the girl who shops\"","trick":true},{"id":"c","text":"Both phones have good cameras","trick":false},{"id":"d","text":"There's a one-year warranty","trick":false},{"id":"e","text":"The screens are bright","trick":false}],"why":"Even phones get gendered: 'powerful for men, cute for girls'. Made up.","relearn":"Phone ads often stereotype 'powerful for men, cute for girls'; spot it.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1380","type":"spot","hook":"A talent reel online. Spot the stereotype.","scene":[{"id":"a","text":"\"Girls shouldn't do martial arts\"","trick":true},{"id":"b","text":"Commenters mock a girl breaking a brick","trick":true},{"id":"c","text":"She wears a white uniform","trick":false},{"id":"d","text":"A coach counts the moves","trick":false},{"id":"e","text":"The mat is blue","trick":false}],"why":"Comments say martial arts aren't for girls; strength and skill aren't gendered.","relearn":"People often stereotype martial arts as boys-only; girls are strong too. Spot it.","persona":"Diya","source":"media literacy / news","cat":"spot-it"},
  {"id":"fs-1381","type":"spot","hook":"A diaper-bag advert. Spot the stereotype.","scene":[{"id":"a","text":"It's only ever shown on a mother's shoulder","trick":true},{"id":"b","text":"\"Because caring is a mother's job\"","trick":true},{"id":"c","text":"It has many handy pockets","trick":false},{"id":"d","text":"The strap is adjustable","trick":false},{"id":"e","text":"It wipes clean easily","trick":false}],"why":"Ads pin baby care on mothers alone; fathers carry the bag and care too.","relearn":"Ads often stereotype baby care as mothers-only; dads care too. Spot it.","persona":"Rohit","source":"media literacy / defaults","cat":"spot-it"},
  {"id":"fs-1382","type":"spot","hook":"A music-video scene. Spot the stereotype.","scene":[{"id":"a","text":"The lyric brags \"crying is for the weak\"","trick":true},{"id":"b","text":"A boy hides his tears to look tough","trick":true},{"id":"c","text":"There's a rooftop at sunset","trick":false},{"id":"d","text":"The beat is slow","trick":false},{"id":"e","text":"Lights flash in time","trick":false}],"why":"Songs sell 'crying is weak'; everyone cries, and it's healthy, not weak.","relearn":"Songs often stereotype crying as weak; tears are human for all. Spot it.","persona":"Aarav","source":"media literacy / music","cat":"spot-it"},
  {"id":"fs-1383","type":"spot","hook":"A 'career day' brochure. Spot the stereotype.","scene":[{"id":"a","text":"\"Engineering: a boy's path\"","trick":true},{"id":"b","text":"\"Nursing: a girl's path\"","trick":true},{"id":"c","text":"It lists ten careers","trick":false},{"id":"d","text":"There's a map to the venue","trick":false},{"id":"e","text":"Entry is free for students","trick":false}],"why":"Brochures funnel boys to engineering and girls to nursing; both fit anyone.","relearn":"Career guides often stereotype paths by gender; skill decides, not gender. Spot it.","persona":"any","source":"media literacy / jobs","cat":"spot-it"},
  {"id":"fs-1384","type":"spot","hook":"A festival decoration ad. Spot the stereotype.","scene":[{"id":"a","text":"\"Let the ladies handle the rangoli and rotis\"","trick":true},{"id":"b","text":"\"Men just sit and enjoy the feast\"","trick":true},{"id":"c","text":"Marigold garlands hang up","trick":false},{"id":"d","text":"Lamps are being lit","trick":false},{"id":"e","text":"\"Festive offers inside\"","trick":false}],"why":"Ads say women do festival work while men relax; sharing makes a happier home.","relearn":"Festival ads often stereotype women as the workers; chores are shared. Spot it.","persona":"Rohit","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-1385","type":"reflect","hook":"Lensy: think of the last advert you watched. Did it split jobs or chores by gender?","prompt":"What did you notice?","options":["Yes, it did","Not sure now","I'll watch closely next time"],"affirm":"Noticing the pattern is the first flip: your spotting radar is switched on.","relearn":"Spotting gendered patterns in everyday media is a skill that grows.","persona":"any","source":"media literacy","cat":"spot-it"},
  {"id":"fs-1386","type":"reflect","hook":"Lensy: who usually cooks and cleans in the ads you see at home?","prompt":"What comes to mind?","options":["Mostly women","Sometimes everyone","I never noticed"],"affirm":"There's no wrong answer: just noticing who's shown is real media literacy.","relearn":"Ads often show chores done by women; noticing it is the first step.","persona":"Rohit","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-1387","type":"reflect","hook":"Lensy: a stereotype quietly says 'this is for that kind of person'. Spotted any today?","prompt":"Your thoughts?","options":["A few","Maybe one","Looking harder now"],"affirm":"Every one you catch is a script you no longer have to believe.","relearn":"A stereotype is a too-simple rule about a whole group; spotting it weakens it.","persona":"any","source":"concept","cat":"spot-it"},
  {"id":"fs-1388","type":"reflect","hook":"Lensy: when a film makes the girl wait and the boy act, how does that sit with you?","prompt":"What do you feel?","options":["A bit unfair","I'd flip it","Hadn't thought about it"],"affirm":"Your sense that something's off is exactly the radar this game builds.","relearn":"Films often give boys action and girls waiting; noticing it is the flip.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1389","type":"reflect","hook":"Lensy: ads often pick a colour 'for boys' and one 'for girls'. Noticed which?","prompt":"What do you think?","options":["Blue and pink","It varies","I'll look next time"],"affirm":"Colour rules are invented, and you just caught one in the wild.","relearn":"Ads often code colours by gender, though colours are for everyone.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1390","type":"reflect","hook":"Lensy: once you spot one stereotype on screen, do you start seeing more?","prompt":"How's your radar?","options":["Yes, everywhere","Getting sharper","Still warming up"],"affirm":"That growing radar is media literacy, and it only gets stronger.","relearn":"Spotting media stereotypes is a muscle that strengthens with practice.","persona":"any","source":"media literacy","cat":"spot-it"},
  {"id":"fs-1391","type":"strike-rewrite","hook":"\"If an ad shows it, that's just how families really are.\"","myth":{"un":"Ads show how families really are.","re":"Ads are scripted to sell, and often repeat tired stereotypes.","why":"Adverts are made by writers choosing what to show, not real life."},"relearn":"Ads are made to sell; they often repeat stereotypes, not reality.","persona":"any","source":"media literacy","cat":"spot-it"},
  {"id":"fs-1392","type":"strike-rewrite","hook":"\"Spotting stereotypes in films just spoils the fun.\"","myth":{"un":"Noticing stereotypes spoils the film.","re":"Noticing them lets you enjoy stories and choose what to believe.","why":"Spotting a script means it no longer shapes you without your say."},"relearn":"Spotting stereotypes adds to the fun; you watch with open eyes.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1393","type":"strike-rewrite","hook":"\"Adverts only show women cleaning because women just like it more.\"","myth":{"un":"Only women are shown cleaning because they prefer it.","re":"Ads choose to show women cleaning; chores belong to the whole family.","why":"What an ad shows is a choice, not proof of what people prefer."},"relearn":"Ads choosing women for chores is a stereotype, not a real preference.","persona":"Rohit","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-1394","type":"strike-rewrite","hook":"\"Pink toys for girls and blue for boys. That's just normal.\"","myth":{"un":"Pink-for-girls, blue-for-boys aisles are just normal.","re":"Those colour aisles are a made-up rule shops invented to sell more.","why":"Colour codes are recent and change; they aren't a fact of nature."},"relearn":"Gendered toy aisles are an invented rule, not a natural fact.","persona":"any","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-1395","type":"strike-rewrite","hook":"\"Boys in films do the rescuing because boys are just braver.\"","myth":{"un":"Film boys rescue because boys are braver.","re":"Writers hand boys the heroics; bravery isn't decided by gender.","why":"A story's choices aren't proof about real boys and girls."},"relearn":"Films giving boys the heroics is a script, not proof of who's brave.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1396","type":"strike-rewrite","hook":"\"It's only a song lyric, words like that don't really matter.\"","myth":{"un":"Stereotype lyrics don't really matter.","re":"Repeated lines shape what feels 'normal' to listeners over time.","why":"Hearing a message again and again quietly teaches it as a rule."},"relearn":"Lyrics repeat stereotypes that shape what feels normal; they matter.","persona":"any","source":"media literacy / music","cat":"spot-it"},
  {"id":"fs-1397","type":"sort","hook":"Sort each ad line: a stereotype, or a fair message?","items":[{"id":"a","text":"\"Only mums can keep a home clean\""},{"id":"b","text":"\"Everyone in the family can help cook\""},{"id":"c","text":"\"Dolls are just for girls\""},{"id":"d","text":"\"Any kid can love any toy\""},{"id":"e","text":"\"Real boys don't cry\""},{"id":"f","text":"\"Feelings are for everyone\""}],"bins":[{"id":"stereo","label":"Stereotype","valence":"neg"},{"id":"fair","label":"Fair message","valence":"pos"}],"key":{"a":"stereo","b":"fair","c":"stereo","d":"fair","e":"stereo","f":"fair"},"relearn":"Media mixes stereotypes with fair messages; learn to tell them apart.","persona":"any","source":"media literacy","cat":"spot-it"},
  {"id":"fs-1398","type":"sort","hook":"Sort each into where it usually shows up in an advert.","items":[{"id":"a","text":"A woman happily mopping the floor"},{"id":"b","text":"A man speeding in a powerful car"},{"id":"c","text":"A woman serving the family dinner"},{"id":"d","text":"A man being the office boss"},{"id":"e","text":"A woman admiring a man's new watch"},{"id":"f","text":"A man fixing the broken machine"}],"bins":[{"id":"women","label":"Ad puts women here","valence":"neutral"},{"id":"men","label":"Ad puts men here","valence":"neutral"}],"key":{"a":"women","b":"men","c":"women","d":"men","e":"women","f":"men"},"relearn":"Ads slot women into care and men into power; in real life anyone can do any of these.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1399","type":"sort","hook":"Sort: a made-up media rule, or a real reason?","items":[{"id":"a","text":"\"Boys can't wear pink\""},{"id":"b","text":"\"Wear a helmet while cycling\""},{"id":"c","text":"\"Girls can't play football\""},{"id":"d","text":"\"Wash hands before eating\""},{"id":"e","text":"\"Long hair isn't for boys\""},{"id":"f","text":"\"Tie back loose hair near a stove\""}],"bins":[{"id":"madeup","label":"Made-up rule","valence":"neg"},{"id":"real","label":"Real reason","valence":"pos"}],"key":{"a":"madeup","b":"real","c":"madeup","d":"real","e":"madeup","f":"real"},"relearn":"Some media rules are invented; real rules have a real reason. Tell them apart.","persona":"any","source":"media literacy","cat":"spot-it"},
  {"id":"fs-1400","type":"sort","hook":"Sort each TV moment: stereotype, or flips it?","items":[{"id":"a","text":"A serial where only the bahu cooks"},{"id":"b","text":"A girl is the cricket captain"},{"id":"c","text":"The boy hero never cries"},{"id":"d","text":"A dad happily cooks dinner"},{"id":"e","text":"An ad calls science 'a boy's subject'"},{"id":"f","text":"A girl wins the science fair"}],"bins":[{"id":"stereo","label":"Stereotype","valence":"neg"},{"id":"flip","label":"Flips it","valence":"pos"}],"key":{"a":"stereo","b":"flip","c":"stereo","d":"flip","e":"stereo","f":"flip"},"relearn":"TV can repeat stereotypes or flip them; spotting the flips shows what's possible.","persona":"Diya","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1401","type":"sort","hook":"Sort each ad message: limits a kid, or frees a kid?","items":[{"id":"a","text":"\"Strong games are only for boys\""},{"id":"b","text":"\"Try any sport you enjoy\""},{"id":"c","text":"\"Pretty is what matters for girls\""},{"id":"d","text":"\"Your ideas matter, whoever you are\""},{"id":"e","text":"\"Boys who read are boring\""},{"id":"f","text":"\"Read whatever you love\""}],"bins":[{"id":"limit","label":"Limits a kid","valence":"neg"},{"id":"free","label":"Frees a kid","valence":"pos"}],"key":{"a":"limit","b":"free","c":"limit","d":"free","e":"limit","f":"free"},"relearn":"Some media messages box kids in; others set them free. Learn to tell which.","persona":"any","source":"media literacy","cat":"spot-it"},
  {"id":"fs-1402","type":"sort","hook":"Sort where each ad usually places these jobs.","items":[{"id":"a","text":"A nurse, drawn as a woman"},{"id":"b","text":"A pilot, drawn as a man"},{"id":"c","text":"A teacher, drawn as a woman"},{"id":"d","text":"An engineer, drawn as a man"},{"id":"e","text":"A receptionist, drawn as a woman"},{"id":"f","text":"A scientist, drawn as a man"}],"bins":[{"id":"aswoman","label":"Ad draws as a woman","valence":"neutral"},{"id":"asman","label":"Ad draws as a man","valence":"neutral"}],"key":{"a":"aswoman","b":"asman","c":"aswoman","d":"asman","e":"aswoman","f":"asman"},"relearn":"Ads keep slotting jobs by gender; in real life every job is open to anyone.","persona":"any","source":"media literacy / jobs","cat":"spot-it"},
  {"id":"fs-1403","type":"sort","hook":"Sort each line from a film: a stereotype to spot, or a fair line?","items":[{"id":"a","text":"\"Leave the rescuing to the men\""},{"id":"b","text":"\"Let's solve this together\""},{"id":"c","text":"\"Girls are too soft to lead\""},{"id":"d","text":"\"She'd make a great captain\""},{"id":"e","text":"\"A boy mustn't show fear\""},{"id":"f","text":"\"It's okay to feel scared\""}],"bins":[{"id":"spot","label":"Stereotype to spot","valence":"neg"},{"id":"fair","label":"Fair line","valence":"pos"}],"key":{"a":"spot","b":"fair","c":"spot","d":"fair","e":"spot","f":"fair"},"relearn":"Films carry both kinds of line; spotting the stereotype is the first flip.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1404","type":"branch","hook":"An ad shows only mum cleaning. Your cousin says \"that's just how it is\".","options":[{"text":"Say \"the ad just chose that; anyone can clean\"","consequence":"Your cousin starts noticing it too.","outcome":"fair","best":true},{"text":"Shrug and keep watching","consequence":"Cleaning isn't only women's work."},{"text":"Agree cleaning is for women","consequence":"An ad's choice isn't proof."}],"debrief":"Ads make choices; you can name that, not take it as truth.","relearn":"An ad's choice isn't a fact; chores belong to everyone.","persona":"Diya","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-1405","type":"branch","hook":"A friend shares a clip where the girl waits to be saved, laughing \"girls are useless\".","options":[{"text":"Say \"that's the script; real girls rescue too\"","consequence":"Your friend rethinks it.","outcome":"fair","best":true},{"text":"Laugh along to fit in","consequence":"Films aren't real life."},{"text":"Stay silent, feel uneasy","consequence":"A kind line can flip the moment."}],"debrief":"Films script who acts and who waits; name it kindly.","relearn":"A film's script isn't proof; girls are not helpless.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1406","type":"branch","hook":"A toy ad says \"dolls for girls\". Your little brother wants the doll but feels shy.","options":[{"text":"Say \"any kid can play with any toy\"","consequence":"He picks the doll happily.","outcome":"fair","best":true},{"text":"Tell him dolls aren't for boys","consequence":"Dolls help any kid practise caring."},{"text":"Say nothing","consequence":"A kind word frees him from a made-up rule."}],"debrief":"Toy ads invent gender rules; reassure a younger kid.","relearn":"Toy ads make up rules; any kid can enjoy any toy.","persona":"any","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-1407","type":"branch","hook":"A reel mocks a boy for crying in a film. The comments pile on.","options":[{"text":"Comment \"everyone cries; it's healthy\"","consequence":"A few agree; the mocking eases.","outcome":"fair","best":true},{"text":"Add a laughing reaction","consequence":"Mocking tears spreads a harmful script."},{"text":"Scroll past quickly","consequence":"One calm comment can shift others."}],"debrief":"Reels pile on a crying boy; one kind line reminds all that tears are human.","relearn":"Crying isn't weak; it's healthy for everyone.","persona":"Aarav","source":"media literacy / news","cat":"spot-it"},
  {"id":"fs-1408","type":"branch","hook":"A shop assistant steers your sister to the 'girls' pink bike, away from the blue one she likes.","options":[{"text":"Say \"she can pick any colour she likes\"","consequence":"She grins and takes the blue bike.","outcome":"fair","best":true},{"text":"Let the assistant choose pink","consequence":"Colours aren't gendered."},{"text":"Say pink suits girls better","consequence":"Bike colour is a free choice."}],"debrief":"Shops nudge colours by gender; let her choose what she likes.","relearn":"Bike colours are a free choice, not a gender rule.","persona":"Diya","source":"media literacy / products","cat":"spot-it"},
  {"id":"fs-1409","type":"branch","hook":"In class a video calls cooking 'women's work'. The teacher asks what you think.","options":[{"text":"Say \"top chefs are often men; cooking is for anyone\"","consequence":"The class discusses it; many nod.","outcome":"fair","best":true},{"text":"Agree cooking is women's work","consequence":"Cooking is a skill, not a gender duty."},{"text":"Say nothing","consequence":"Sharing the flip helps the class rethink."}],"debrief":"A video can repeat 'cooking is women's work'; offer the fair flip.","relearn":"Cooking is a learned skill, not a gender duty.","persona":"Rohit","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-1410","type":"branch","hook":"A 'genius kit' ad shows only boys. Your friend says \"maybe boys really are smarter\".","options":[{"text":"Say \"the ad just chose boys; brains aren't gendered\"","consequence":"Your friend drops the idea.","outcome":"fair","best":true},{"text":"Nod and say maybe","consequence":"The ad picked who to show."},{"text":"Change the subject","consequence":"A clear flip stops a false idea sticking."}],"debrief":"Ads showing only boys plant 'boys are smarter'; brains aren't gendered.","relearn":"Intelligence isn't decided by gender; an ad isn't proof.","persona":"Diya","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1411","type":"branch","hook":"A relative shares a forward joking 'girls can't drive'. Others laugh; you feel it's unfair.","options":[{"text":"Reply \"women drive trucks, buses and planes\"","consequence":"The forward loses steam.","outcome":"fair","best":true},{"text":"Forward it on too","consequence":"Spreading it grows the stereotype."},{"text":"Mute and ignore it","consequence":"A short, kind fact can flip the joke."}],"debrief":"Forwards spread 'girls can't drive'; a calm fact flips it.","relearn":"Driving is a skill, not a gender; women drive everything.","persona":"any","source":"media literacy / news","cat":"spot-it"},
  {"id":"fs-1412","type":"role-play","hook":"Your friend points at an ad and says \"see, cleaning really is a woman's job\".","setup":"Flip it kindly. Say:","yourLine":[{"text":"\"That's just the ad's choice; cleaning is everyone's job, na?\"","best":true},{"text":"\"Yeah, I suppose it must be true.\""}],"relearn":"You can gently name that an ad's choice isn't proof; chores are shared.","persona":"Diya","source":"media literacy / chores","cat":"spot-it"},
  {"id":"fs-1413","type":"role-play","hook":"Watching a film, your cousin laughs \"girls always need rescuing\".","setup":"Say the fair line:","yourLine":[{"text":"\"That's just the script; real girls rescue people too.\"","best":true},{"text":"\"Ha, yeah, girls can't do much.\""}],"relearn":"A film's script isn't real life; you can say so kindly.","persona":"any","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1414","type":"role-play","hook":"An ad says boys shouldn't cry. Your younger brother looks worried about his own tears.","setup":"Reassure him. Say:","yourLine":[{"text":"\"The ad's wrong, na. Everyone cries, and that's okay.\"","best":true},{"text":"\"Maybe you should toughen up like the ad says.\""}],"relearn":"You can flip a harmful ad message for a younger kid: tears are human.","persona":"Aarav","source":"media literacy / news","cat":"spot-it"},
  {"id":"fs-1415","type":"role-play","hook":"A shop sign says \"science toys, for boys\". Your sister hesitates near it.","setup":"Encourage her. Say:","yourLine":[{"text":"\"That sign made that up, science toys are for you too.\"","best":true},{"text":"\"It says boys, so maybe leave it.\""}],"relearn":"Shop signs invent gender rules; you can free a friend to choose.","persona":"Diya","source":"media literacy / toys","cat":"spot-it"},
  {"id":"fs-1416","type":"role-play","hook":"Friends are sharing a clip that mocks a boy for dancing. They wait for you to laugh.","setup":"Say it kindly:","yourLine":[{"text":"\"Dancing's just a skill, na. Anyone can do it.\"","best":true},{"text":"\"Haha, yeah, dancing's not for boys.\""}],"relearn":"You don't have to spread mocking content; a kind line flips it.","persona":"any","source":"media literacy / news","cat":"spot-it"},
  {"id":"fs-1417","type":"role-play","hook":"An advert calls pink 'a girl colour'. Your friend says you can't wear your pink shirt.","setup":"Flip it. Say:","yourLine":[{"text":"\"Colours are for everyone. Pink was once a boys' colour!\"","best":true},{"text":"\"You're right, I'll change it.\""}],"relearn":"Colour rules are made up and change; anyone can wear any colour.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1418","type":"role-play","hook":"A serial shows only the bahu cooking. Your aunt says \"that's a girl's duty\".","setup":"Question it kindly. Say:","yourLine":[{"text":"\"Is that fair, na? Cooking can be shared by everyone.\"","best":true},{"text":"\"Okay, if you say so.\""}],"relearn":"You can question an elder's line kindly, without attacking, na.","persona":"Diya","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1419","type":"role-play","hook":"A car ad shows the woman just watching the man drive. A friend says women can't really drive.","setup":"Say the fair line:","yourLine":[{"text":"\"Women drive scooters, trucks and planes. That's just an ad.\"","best":true},{"text":"\"Maybe driving really is a man's thing.\""}],"relearn":"Ads make men the drivers; in real life women drive everything.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1420","type":"match","hook":"Match each ad type to the stereotype it usually hides.","pairs":[{"left":"Cleaning-product ad","right":"Only women do the housework"},{"left":"Car advert","right":"Men drive, women decorate"},{"left":"Toy advert","right":"Toys split into 'boys' and 'girls'"},{"left":"Fairness-cream ad","right":"Fair skin means more success"},{"left":"Baby-product ad","right":"Only mothers care for babies"}],"relearn":"Each kind of ad tends to repeat a particular gender stereotype; learn to expect it.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1421","type":"match","hook":"Match the stereotype on screen to the fair flip.","pairs":[{"left":"\"Girls can't lead\"","right":"Anyone can lead with vision and care"},{"left":"\"Boys don't cry\"","right":"Everyone cries; it's healthy"},{"left":"\"Cooking is women's work\"","right":"Anyone can cook"},{"left":"\"Pink is only for girls\"","right":"Colours are for everyone"},{"left":"\"Science is a boy's subject\"","right":"Girls excel at science too"}],"relearn":"For every stereotype on screen there's a fair flip; matching them builds the habit.","persona":"Diya","source":"media literacy","cat":"spot-it"},
  {"id":"fs-1422","type":"match","hook":"Match each job a textbook stereotypes to a real Indian who breaks it.","pairs":[{"left":"Astronaut shown as a man","right":"Kalpana Chawla flew to space"},{"left":"Boxer shown as a man","right":"Mary Kom is a champion boxer"},{"left":"Pilot shown as a man","right":"India has many women pilots"},{"left":"Soldier shown as a man","right":"Women serve as soldiers too"},{"left":"Cricket captain shown as a man","right":"A woman captains India too"}],"relearn":"Real, nameable people break the very stereotypes the media keeps repeating.","persona":"any","source":"role models / media literacy","cat":"spot-it"},
  {"id":"fs-1423","type":"match","hook":"Match each media type to where it hides a gender stereotype.","pairs":[{"left":"Film poster","right":"Hero acts, heroine waits"},{"left":"Song lyric","right":"\"Boys will be boys\" excuses bad acts"},{"left":"Greeting card","right":"Boys = strong, girls = pretty"},{"left":"Sport broadcast","right":"Men's games treated as the 'real' ones"},{"left":"Family emoji set","right":"Mums care, dads earn"}],"relearn":"Stereotypes hide in every media format; matching them sharpens your spotting radar.","persona":"any","source":"media literacy","cat":"spot-it"},
  {"id":"fs-1424","type":"match","hook":"Match each gendered ad message to the made-up rule it pushes.","pairs":[{"left":"\"Strong games for boys\"","right":"Strength belongs to one gender"},{"left":"\"Pretty dresses for girls\"","right":"Looks matter most for girls"},{"left":"\"Tools for dad\"","right":"Fixing things is a man's job"},{"left":"\"Kitchen sets for mum\"","right":"Cooking is a woman's job"},{"left":"\"Adventure is for him\"","right":"Boldness is a boys-only trait"}],"relearn":"Ad slogans push made-up rules; naming the rule is the first step to flipping it.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1425","type":"match","hook":"Match each TV moment to stereotype or flip.","pairs":[{"left":"Only the bahu cooks","right":"Stereotype: cooking is a girl's duty"},{"left":"A dad cooks dinner","right":"Flip: cooking is shared"},{"left":"A girl captains the team","right":"Flip: girls can lead"},{"left":"A boy hides his tears","right":"Stereotype: boys mustn't cry"},{"left":"A girl wins the science fair","right":"Flip: girls excel at science"}],"relearn":"TV mixes stereotypes and flips; matching shows which scripts to keep.","persona":"Diya","source":"media literacy / film","cat":"spot-it"},
  {"id":"fs-1426","type":"match","hook":"Match each ad 'rule' about colour or clothes to the truth.","pairs":[{"left":"\"Pink is for girls\"","right":"Pink was once a boys' colour"},{"left":"\"Long hair isn't for boys\"","right":"All genders have worn long hair"},{"left":"\"Girls must wear dresses\"","right":"Clothes are about comfort"},{"left":"\"Blue is a boy colour\"","right":"Any colour suits any kid"},{"left":"\"Boys can't wear bangles\"","right":"Accessories have no gender"}],"relearn":"Ad 'rules' about colour and clothes are invented; they're free choices.","persona":"any","source":"media literacy / ads","cat":"spot-it"},
  {"id":"fs-1427","type":"match","hook":"Match each ad stereotype to the real Indian flip.","pairs":[{"left":"Cooking isn't a man's job","right":"Many dads cook every day"},{"left":"Women can't drive trucks","right":"Women drive trucks and buses"},{"left":"Caring is a mother's job","right":"Fathers soothe babies too"},{"left":"Science is a male field","right":"Girls top science and maths"},{"left":"Leadership is for men","right":"Women lead teams and cities"}],"relearn":"For every ad stereotype, real Indian life shows the flip.","persona":"Rohit","source":"media literacy","cat":"spot-it"},
];

